"""The four requested knobs, and nothing else, expressed in the edit DSL.

Two bodies carry two properties each: the bob's mass and its speed along the
arc, the block's mass and its speed along the bench. Restitution, friction,
thread length and the release geometry are deliberately *not* in the
vocabulary, so no edit can quietly change two things at once.

``initial_velocity`` is bound to a scalar speed, not a vector. Both bodies
start on the axis of the impact and their directions are fixed by the scene
(the block towards +X, the bob towards -X), so a vector edit would only offer
the chance to write a number that the simulator ignores along two of its
components. The prompt therefore reads "initial speed", which is exactly the
quantity the parameter names.
"""

# Locate reference common scripts and install this scene's embedded helpers.
import sys as _bundle_sys0
from pathlib import Path as _BundlePath0
_BUNDLE_SCENE = _BundlePath0(__file__).resolve().parent
_BUNDLE_SCRIPTS = _BUNDLE_SCENE.parent
_PCVE_PROJECT_ROOT = next(p for p in _BUNDLE_SCENE.parents if (p / "assets").is_dir())
if str(_BUNDLE_SCRIPTS) not in _bundle_sys0.path:
    _bundle_sys0.path.insert(0, str(_BUNDLE_SCRIPTS))

# Scene-local source bundle: installed before importing scene support modules.
import importlib.abc as _bundle_abc
import importlib.util as _bundle_util
import json as _bundle_json
import sys as _bundle_sys
from pathlib import Path as _BundlePath

_BUNDLE_SCENE = _BundlePath(__file__).resolve().parent
_BUNDLE_SCRIPTS = _BUNDLE_SCENE.parent
_BUNDLE_PROJECT = next(p for p in _BUNDLE_SCENE.parents if (p / "assets").is_dir())
if str(_BUNDLE_SCRIPTS) not in _bundle_sys.path:
    _bundle_sys.path.insert(0, str(_BUNDLE_SCRIPTS))

_BUNDLE_SOURCES = _bundle_json.loads(r"""{"pcve_project_paths": "\"\"\"Path helpers shared by standalone rigid-scene folders.\"\"\"\nfrom pathlib import Path\nimport sys\n\n\ndef project_root(anchor):\n    anchor = Path(anchor).resolve()\n    candidates = (anchor, *anchor.parents)\n    for candidate in candidates:\n        if (candidate / \"assets\").is_dir() and (candidate / \"clean_scripts\").is_dir():\n            return candidate\n    raise FileNotFoundError(f\"Cannot locate project root above {anchor}; expected assets/ and clean_scripts/\")\n\n\ndef scene_root(anchor):\n    \"\"\"Find the scene folder from argv first, then from the helper's parents.\"\"\"\n    candidates = []\n    if sys.argv and sys.argv[0] not in {\"-\", \"\"}:\n        argv_path = Path(sys.argv[0]).expanduser()\n        if not argv_path.is_absolute():\n            argv_path = Path.cwd() / argv_path\n        candidates.append(argv_path.resolve().parent)\n    anchor = Path(anchor).resolve()\n    candidates.extend(anchor.parents)\n    seen = set()\n    for candidate in candidates:\n        if candidate in seen:\n            continue\n        seen.add(candidate)\n        if any(candidate.glob(\"simulate_*.py\")) and any(candidate.glob(\"render_*.py\")):\n            return candidate\n    raise FileNotFoundError(f\"Cannot locate scene entrypoints above {anchor}\")\n", "pcve_scene_runtime": "\"\"\"Shared command-line and output contracts for PCVE scene entry points.\n\nBoth ``blender -b --python render.py -- ...`` and Python with bpy are supported.\nThis module has no Blender dependency until a renderer finishes.\n\"\"\"\n\nimport argparse\nimport hashlib\nimport json\nimport math\nimport os\nimport random\nimport shutil\nimport sys\nfrom pathlib import Path\n\nROOT = Path(__file__).resolve().parents[1]\n_render_args = None\n\n\ndef python_for(role: str) -> Path:\n    override = os.environ.get(\"PCVE_PHYSICS_PYTHON\" if role == \"physics\" else \"PCVE_RENDER_PYTHON\")\n    if override:\n        return Path(override).expanduser()\n    names = (\"sim/python.exe\", \"sim/bin/python\") if role == \"physics\" else (\n        \"render/Scripts/python.exe\", \"render/bin/python\")\n    for base in (ROOT / \".runtime\", ROOT.parent / \"PCVE-ElasticBench/.runtime\"):\n        for name in names:\n            if (base / name).is_file():\n                return base / name\n    if role == \"physics\":\n        # The original Linux setup activates a PyBullet conda environment and\n        # invokes Blender separately. Blender's sys.executable is not Python.\n        candidates = [ROOT.parent / \"miniconda/envs/physics/bin/python\"]\n        if os.environ.get(\"CONDA_PREFIX\"):\n            prefix = Path(os.environ[\"CONDA_PREFIX\"])\n            candidates += [prefix / \"python.exe\", prefix / \"bin/python\"]\n        for name in (\"python3\", \"python\"):\n            if shutil.which(name):\n                candidates.append(Path(shutil.which(name)))\n        for candidate in candidates:\n            if candidate.is_file() and \"blender\" not in candidate.name.lower():\n                return candidate\n    return Path(sys.executable)\n\n\ndef _add(parser, flag, **kwargs):\n    if flag not in parser._option_string_actions:\n        parser.add_argument(flag, **kwargs)\n\n\ndef implementation_hashes(directory):\n    files = list(Path(directory).glob(\"*.py\"))\n    files += [ROOT / \"clean_scripts\" / name for name in (\"pcve_scene_pipeline.py\", \"pcve_edit_dsl.py\")]\n    return {str(path.relative_to(ROOT)): hashlib.sha256(path.read_bytes()).hexdigest()\n            for path in files if path.is_file()}\n\n\ndef case_outputs(folder):\n    \"\"\"Semantic output keys used by the original suite manifests.\"\"\"\n    names = dict(video=\"video.mp4\", ground_truth=\"ground_truth_transforms.json\",\n                 scenario_metadata=\"scenario_metadata.json\", scenario_overrides=\"scenario_overrides.json\",\n                 physics=\"physics_transforms.json\", scenario_input=\"scenario_input.json\", preview=\"preview.png\")\n    return {key: str((Path(folder) / name).resolve()) for key, name in names.items()\n            if (Path(folder) / name).is_file()}\n\n\ndef add_build_arguments(parser):\n    _add(parser, \"--blender\", type=Path, help=\"Blender executable; otherwise use render Python with bpy.\")\n    _add(parser, \"--physics-python\", type=Path, default=python_for(\"physics\"))\n    _add(parser, \"--render-python\", type=Path, default=python_for(\"render\"))\n    _add(parser, \"--engine\", choices=(\"cycles\", \"eevee\"), default=\"cycles\")\n    _add(parser, \"--device\", choices=(\"auto\", \"cpu\"), default=\"auto\")\n    _add(parser, \"--preview-frame\", type=int)\n    _add(parser, \"--fps\", type=int)\n    _add(parser, \"--duration-sec\", type=float)\n    return parser\n\n\ndef render_prefix(args, script: Path) -> list[str]:\n    blender = getattr(args, \"blender\", None) or os.environ.get(\"BLENDER_BIN\")\n    render_python = Path(getattr(args, \"render_python\", python_for(\"render\")))\n    if not blender and render_python == Path(sys.executable):\n        candidates = [ROOT / \"tools/blender-3.6.23-linux-x64/blender\"]\n        if shutil.which(\"blender\"):\n            candidates.append(Path(shutil.which(\"blender\")))\n        blender = next((path for path in candidates if path.is_file()), None)\n    if blender:\n        # Blender otherwise returns success even when the Python script raises.\n        return [str(Path(blender).expanduser()), \"-b\", \"--python-exit-code\", \"1\",\n                \"--python\", str(script), \"--\"]\n    return [str(render_python), str(script)]\n\n\ndef append_render_options(command, args):\n    for name in (\"engine\", \"device\", \"preview_frame\"):\n        flag = \"--\" + name.replace(\"_\", \"-\")\n        value = getattr(args, name, None)\n        if value is not None and flag not in command:\n            command += [flag, str(value)]\n    return command\n\n\ndef parse_render_args(parser, argv=None):\n    global _render_args\n    _add(parser, \"--seed\", type=int, default=0)\n    _add(parser, \"--device\", choices=(\"auto\", \"cpu\"), default=\"auto\")\n    _add(parser, \"--preview-frame\", type=int)\n    _add(parser, \"--fps\", type=int)\n    _add(parser, \"--duration-sec\", type=float)\n    _add(parser, \"--physics-python\", type=Path, default=python_for(\"physics\"))\n    # Renderers without an engine switch currently implement Cycles only.\n    _add(parser, \"--engine\", choices=(\"cycles\",), default=\"cycles\")\n    if argv is None:\n        argv = sys.argv[sys.argv.index(\"--\") + 1:] if \"--\" in sys.argv else sys.argv[1:]\n    _render_args = parser.parse_args(argv)\n    # In the original CLI duration-sec is the real-time clip length. A scene's\n    # optional demo slow-motion preset must not silently multiply that request.\n    if \"--duration-sec\" in argv and \"--slow-motion\" not in argv and hasattr(_render_args, \"slow_motion\"):\n        _render_args.slow_motion = 1\n    random.seed(_render_args.seed)\n    return _render_args\n\n\ndef apply_physics_overrides(args, baseline):\n    \"\"\"Read the original {physics: ...} override format for scalar CLI scenes.\n\n    Bare schedule arrays remain accepted by the older timed-edit escape hatch.\n    Explicit scalar command-line values take precedence over the JSON defaults.\n    \"\"\"\n    path = getattr(args, \"scenario_overrides_json\", None)\n    if path is None:\n        return None\n    payload = json.loads(Path(path).read_text(encoding=\"utf-8\"))\n    if isinstance(payload, list):\n        return Path(path)\n    physics = payload.get(\"physics\", payload)\n    unknown = set(physics) - {*baseline, \"timed_edits\"}\n    if unknown:\n        raise ValueError(f\"Unknown physics overrides: {sorted(unknown)}\")\n    for name, value in physics.items():\n        if name != \"timed_edits\" and getattr(args, name, None) is None:\n            setattr(args, name, value)\n    if physics.get(\"timed_edits\"):\n        target = Path(args.out_dir) / \"timed_edits.json\"\n        target.parent.mkdir(parents=True, exist_ok=True)\n        target.write_text(json.dumps(physics[\"timed_edits\"], indent=2), encoding=\"utf-8\")\n        return target\n    return None\n\n\ndef _matrix(position, q):\n    x, y, z, w = q\n    return [[1-2*(y*y+z*z), 2*(x*y-z*w), 2*(x*z+y*w), position[0]],\n            [2*(x*y+z*w), 1-2*(x*x+z*z), 2*(y*z-x*w), position[1]],\n            [2*(x*z-y*w), 2*(y*z+x*w), 1-2*(x*x+y*y), position[2]],\n            [0, 0, 0, 1]]\n\n\ndef _optional_metrics(value):\n    if isinstance(value, dict):\n        return {key: _optional_metrics(item) for key, item in value.items()}\n    if isinstance(value, list):\n        return [_optional_metrics(item) for item in value]\n    if isinstance(value, float) and not math.isfinite(value):\n        return None\n    return value\n\n\ndef finalize_render_outputs(out: Path, scene_name: str, args, scene=None):\n    \"\"\"Keep scene-specific files and also publish the original PCVE filenames.\"\"\"\n    out = Path(out).resolve()\n    gt_path = out / \"ground_truth_transforms.json\"\n    if gt_path.is_file():\n        gt = json.loads(gt_path.read_text(encoding=\"utf-8\"))\n        gt.setdefault(\"scene\", scene_name)\n        gt.setdefault(\"schema_version\", 1)\n        camera = gt.setdefault(\"camera\", {})\n        camera.setdefault(\"resolution\", list(args.resolution))\n        camera.setdefault(\"sensor_width_mm\", 36.0)\n        if scene is not None and scene.camera is not None:\n            cam = scene.camera\n            camera.update(matrix_world=[list(row) for row in cam.matrix_world],\n                          sensor_width_mm=float(cam.data.sensor_width),\n                          sensor_fit=cam.data.sensor_fit)\n            if cam.data.type == \"ORTHO\":\n                camera.update(projection=\"orthographic\", ortho_scale=float(cam.data.ortho_scale))\n            else:\n                camera.update(projection=\"perspective\", lens_mm=float(cam.data.lens))\n        frames = gt.get(\"frames\", [])\n        # toy_car_bottle retains its raw simulation and render_frames as well.\n        rendered = gt.get(\"render_frames\", [])\n        for index, frame in enumerate(frames):\n            frame.setdefault(\"frame_index\", frame.get(\"frame\", index + 1))\n            frame.setdefault(\"time_sec\", frame.get(\"time\", index / gt.get(\"fps\", 24)))\n            if camera.get(\"matrix_world\") is not None:\n                frame.setdefault(\"camera_matrix_world\", camera[\"matrix_world\"])\n            if index < len(rendered):\n                for name, state in rendered[index].get(\"objects\", {}).items():\n                    raw = frame.get(\"objects\", {}).get(name, {})\n                    frame[name] = dict(raw, present=True, location=state[\"position\"],\n                                       quaternion_xyzw=state[\"quaternion_xyzw\"],\n                                       matrix_world=_matrix(state[\"position\"], state[\"quaternion_xyzw\"]))\n        gt.setdefault(\"frame_start\", 1)\n        gt.setdefault(\"frame_end\", len(frames))\n        if scene_name == \"toy_car_bottle\":\n            layout = gt[\"config\"][\"layout\"]\n            gt[\"objects\"] = {\n                \"car\": {\"object_name\": \"toy_car\", \"dimensions\": [layout[\"car_length\"], layout[\"car_width\"], layout[\"car_height\"]]},\n                \"bottle\": {\"object_name\": \"plastic_bottle\", \"radius\": layout[\"bottle_radius\"], \"height\": layout[\"bottle_height\"]},\n            }\n        # A short diagnostic clip may not contain an impact. Its unavailable\n        # post-contact quality measurements are null; poses must stay finite.\n        for container in (gt, gt.get(\"physics\", {})):\n            if \"quality\" in container:\n                container[\"quality\"] = _optional_metrics(container[\"quality\"])\n        for frame in frames:\n            matrices = [item[\"matrix_world\"] for item in frame.values()\n                        if isinstance(item, dict) and \"matrix_world\" in item\n                        and not (item.get(\"present\") is False and item[\"matrix_world\"] is None)]\n            matrices += [item for key, item in frame.items() if key.endswith(\"_matrix_world\")]\n            for matrix in matrices:\n                if matrix is None:\n                    raise ValueError(\"A present object must have a ground-truth transform\")\n                if not all(math.isfinite(value) for row in matrix for value in row):\n                    raise ValueError(\"Non-finite ground-truth transform\")\n        gt_path.write_text(json.dumps(gt, indent=2, ensure_ascii=False, allow_nan=False), encoding=\"utf-8\")\n    mode = getattr(args, \"mode\", \"preview\")\n    if mode == \"animation\":\n        stem = \"basketball_door\" if scene_name == \"home_basketball_door\" else scene_name\n        source = out / (stem + \".mp4\")\n        target = out / \"video.mp4\"\n        if source.is_file() and not (scene_name == \"uneven_ground_ball\" and getattr(args, \"label\", False)):\n            shutil.copy2(source, target)\n        if not target.is_file():\n            raise FileNotFoundError(f\"Animation did not produce {target}\")\n    refresh_alias = scene_name in (\"home_basketball_door\", \"pot_lid_drop\") or (\n        scene_name == \"toy_car_bottle\" and getattr(args, \"preview_frame\", None) is None)\n    if mode == \"preview\" and (refresh_alias or not (out / \"preview.png\").is_file()):\n        number = getattr(args, \"preview_frame\", None) or 1\n        candidates = [out / f\"preview_frame_{number:04d}.png\", out / \"first_frame.png\"]\n        candidates += sorted(out.glob(\"preview_frame_*.png\"))\n        source = next((p for p in candidates if p.is_file()), None)\n        if source is None:\n            raise FileNotFoundError(f\"Preview did not produce an image in {out}\")\n        shutil.copy2(source, out / \"preview.png\")\n\n\ndef run_renderer(main, scene_name):\n    global _render_args\n    _render_args = None\n    main()\n    if _render_args is not None:\n        import bpy\n        finalize_render_outputs(_render_args.out_dir, scene_name, _render_args, bpy.context.scene)\n", "pcve_blender_compat": "\"\"\"Small Blender 3.6/4.x API differences used by the scene renderers.\"\"\"\n\nSOCKET_NAMES = {\n    \"Coat Weight\": \"Clearcoat\", \"Coat Roughness\": \"Clearcoat Roughness\",\n    \"Specular IOR Level\": \"Specular\", \"Transmission Weight\": \"Transmission\",\n    \"Emission Color\": \"Emission\", \"Sheen Weight\": \"Sheen\",\n    \"Sheen Roughness\": \"Roughness\", \"Subsurface Weight\": \"Subsurface\",\n}\n\n\ndef shader_socket(node, name):\n    socket = node.inputs.get(name)\n    if socket is None:\n        socket = node.inputs.get(SOCKET_NAMES.get(name, name))\n    if socket is None:\n        raise KeyError(f\"{node.name}: missing shader input {name}\")\n    return socket\n\n\ndef set_shader_input(node, name, value):\n    socket = shader_socket(node, name)\n    if socket.type == \"VALUE\" and isinstance(value, (tuple, list)):\n        value = sum(value[:3]) / 3\n    socket.default_value = value\n\n\ndef eevee_engine():\n    import bpy\n    return \"BLENDER_EEVEE_NEXT\" if bpy.app.version >= (4, 2, 0) else \"BLENDER_EEVEE\"\n\n\ndef set_eevee_property(settings, name, value):\n    parts = name.split(\".\")\n    for part in parts[:-1]:\n        if not hasattr(settings, part):\n            return\n        settings = getattr(settings, part)\n    if hasattr(settings, parts[-1]):\n        setattr(settings, parts[-1], value)\n\n\ndef set_color_property(settings, name, value):\n    try:\n        setattr(settings, name, value)\n    except (TypeError, ValueError):\n        candidates = (\"Filmic\", \"Standard\") if name == \"view_transform\" else (\"Medium High Contrast\", \"None\")\n        for candidate in candidates:\n            try:\n                setattr(settings, name, candidate)\n                return\n            except (TypeError, ValueError):\n                continue\n        raise\n\n\ndef configure_cycles_device(bpy, scene, requested):\n    scene.cycles.device = \"CPU\"\n    scene.render.threads_mode = \"FIXED\"\n    scene.render.threads = 4\n    if requested == \"cpu\":\n        return \"CPU\"\n    prefs = bpy.context.preferences.addons[\"cycles\"].preferences\n    for backend in (\"OPTIX\", \"CUDA\", \"HIP\", \"METAL\"):\n        try:\n            prefs.compute_device_type = backend\n            prefs.get_devices()\n            found = [device for device in prefs.devices if device.type == backend]\n            if found:\n                for device in prefs.devices:\n                    device.use = device.type == backend\n                scene.cycles.device = \"GPU\"\n                return \"GPU\"\n        except (TypeError, RuntimeError, ValueError):\n            continue\n    return \"CPU\"\n", "pcve_legacy_scene": "\"\"\"Original batch/suite workflow for scenes backed by a scenario.json file.\"\"\"\n\nimport argparse\nimport hashlib\nimport importlib\nimport json\nimport random\nimport shutil\nimport subprocess\nimport time\nfrom pathlib import Path\n\nROOT = Path(__file__).resolve().parents[1]\n\nfrom pcve_scene_runtime import ROOT, add_build_arguments, append_render_options, render_prefix, implementation_hashes, case_outputs\n\nimport pcve_edit_dsl as dsl\n\n\nSCRIPTS = {\n    \"home_basketball_door\": (\"render_home_basketball_door.py\", \"simulate_home_basketball_door.py\"),\n    \"pot_lid_drop\": (\"render_pot_lid_drop.py\", \"simulate_pot_lid_drop.py\"),\n    \"toy_car_bottle\": (\"render_toy_car_bottle.py\", \"simulate_toy_car_bottle.py\"),\n}\n\n\ndef write_json(path, data):\n    path.parent.mkdir(parents=True, exist_ok=True)\n    path.write_text(json.dumps(data, indent=2, ensure_ascii=False, allow_nan=False), encoding=\"utf-8\")\n\n\ndef parser(scene, batch=False):\n    p = argparse.ArgumentParser(description=f\"Build {'randomized samples' if batch else 'a source/edit suite'} for {scene}.\")\n    p.add_argument(\"--out-root\", type=Path, default=ROOT / \"renders\" / (f\"batch_{scene}\" if batch else f\"pcve_{scene}_suite\"))\n    p.add_argument(\"--resolution\", nargs=2, type=int, default=[1280, 720])\n    p.add_argument(\"--fps\", type=int, default=24)\n    p.add_argument(\"--duration-sec\", type=float, default=4.0)\n    p.add_argument(\"--samples\", type=int, default=32)\n    p.add_argument(\"--engine\", choices=(\"cycles\",), default=\"cycles\")\n    p.add_argument(\"--mode\", choices=(\"preview\", \"animation\"), default=\"preview\" if batch else \"animation\")\n    p.add_argument(\"--skip-existing\", action=\"store_true\")\n    p.add_argument(\"--dry-run\", action=\"store_true\")\n    p.add_argument(\"--verbose-render\", action=\"store_true\")\n    p.add_argument(\"--simulate-only\", action=\"store_true\")\n    if batch:\n        p.add_argument(\"--count\", type=int, default=4)\n        p.add_argument(\"--start-index\", type=int, default=0)\n        p.add_argument(\"--seed-base\", type=int, default=7200)\n    else:\n        p.add_argument(\"--cases\", nargs=\"+\")\n        p.add_argument(\"--clean-stale-cases\", action=\"store_true\")\n    return add_build_arguments(p)\n\n\ndef scene_directory(scene):\n    candidates = (ROOT / \"clean_scripts\" / scene, ROOT / \"clean_scripts\" / scene)\n    for directory in candidates:\n        if directory.is_dir():\n            return directory\n    raise FileNotFoundError(f\"No scene directory found for {scene}: {candidates}\")\n\n\ndef command_for(scene, folder, args, seed, overrides):\n    render, simulate = SCRIPTS[scene]\n    directory = scene_directory(scene)\n    if args.simulate_only:\n        command = [str(args.physics_python), str(directory / simulate), \"--out\", str(folder / \"physics_transforms.json\")]\n    else:\n        command = render_prefix(args, directory / render)\n        command += [\"--out-dir\", str(folder), \"--mode\", args.mode,\n                    \"--resolution\", *map(str, args.resolution), \"--samples\", str(args.samples),\n                    \"--physics-python\", str(args.physics_python), \"--seed\", str(seed)]\n        append_render_options(command, args)\n    command += [\"--fps\", str(args.fps), \"--duration-sec\", str(args.duration_sec)]\n    if overrides is not None:\n        command += [\"--scenario-overrides-json\", str(overrides)]\n    return command\n\n\ndef run_case(scene, folder, args, seed, override):\n    folder = folder.resolve()\n    overrides = folder / \"scenario_overrides.json\" if override else None\n    command = command_for(scene, folder, args, seed, overrides)\n    if args.dry_run:\n        print(subprocess.list2cmdline(command))\n        return {\"status\": \"dry_run\"}\n    implementation = implementation_hashes(scene_directory(scene))\n    payload = dict(override=override, implementation=implementation, seed=seed, fps=args.fps,\n                   duration=args.duration_sec, mode=args.mode, samples=args.samples,\n                   resolution=args.resolution, engine=args.engine, device=args.device,\n                   preview_frame=args.preview_frame, simulation_only=args.simulate_only)\n    fp = hashlib.sha256(json.dumps(payload, sort_keys=True).encode()).hexdigest()\n    status_path = folder / \"run_status.json\"\n    required = [\"physics_transforms.json\"] if args.simulate_only else [\n        \"ground_truth_transforms.json\", \"scenario_metadata.json\",\n        \"video.mp4\" if args.mode == \"animation\" else \"preview.png\"]\n    if args.skip_existing and status_path.is_file():\n        previous = json.loads(status_path.read_text(encoding=\"utf-8\"))\n        if previous.get(\"fingerprint\") == fp and all((folder / p).is_file() for p in required):\n            return dict(previous, status=\"skipped_existing\")\n    if overrides is not None:\n        write_json(overrides, override)\n    folder.mkdir(parents=True, exist_ok=True)\n    start = time.perf_counter()\n    if args.verbose_render:\n        subprocess.run(command, check=True)\n    else:\n        with (folder / \"render.log\").open(\"w\", encoding=\"utf-8\") as log:\n            subprocess.run(command, stdout=log, stderr=subprocess.STDOUT, check=True)\n    for name in required:\n        if not (folder / name).is_file():\n            raise FileNotFoundError(folder / name)\n    status = dict(status=\"completed\", valid=True, fingerprint=fp, simulation_only=args.simulate_only,\n                  render_mode=args.mode, elapsed_sec=round(time.perf_counter() - start, 3),\n                  outputs=case_outputs(folder))\n    write_json(status_path, status)\n    return status\n\n\ndef batch_main(scene, argv=None):\n    args = parser(scene, batch=True).parse_args(argv)\n    args.out_root = args.out_root.resolve()\n    if args.count < 1 or args.start_index < 0:\n        raise ValueError(\"Count must be positive and start index nonnegative\")\n    directory = scene_directory(scene)\n    import sys\n    if str(directory.parent) not in sys.path:\n        sys.path.insert(0, str(directory.parent))\n    vocab = importlib.import_module(f\"{scene}.edit_vocab\").VOCAB\n    manifest = dict(schema_version=1, scene=scene, mode=args.mode, count=args.count,\n                    start_index=args.start_index, seed_base=args.seed_base, samples=[])\n    for offset in range(args.count):\n        index = args.start_index + offset\n        seed = args.seed_base + index\n        rng = random.Random(seed)\n        params = dict(vocab.baseline_physics)\n        for binding in vocab.sim_bindings.values():\n            if isinstance(binding, dsl.SimBinding) and isinstance(params[binding.key], (int, float)):\n                params[binding.key] *= rng.uniform(.8, 1.2)\n        folder = args.out_root / f\"sample_{index:04d}\"\n        result = run_case(scene, folder, args, seed, {\"physics\": params})\n        manifest[\"samples\"].append(dict(sample_index=index, seed=seed, params=params,\n                                         out_dir=str(folder), **result))\n        if not args.dry_run:\n            write_json(args.out_root / \"batch_manifest.json\", manifest)\n\n\ndef suite_main(scene, argv=None):\n    args = parser(scene).parse_args(argv)\n    args.out_root = args.out_root.resolve()\n    directory = scene_directory(scene)\n    import sys\n    if str(directory.parent) not in sys.path:\n        sys.path.insert(0, str(directory.parent))\n    module = importlib.import_module(f\"{scene}.edit_vocab\")\n    vocab = module.VOCAB\n    source_id = f\"{scene}_baseline\"\n    cases = list(module.EDIT_CASES)\n    if args.cases:\n        unknown = set(args.cases) - {source_id, *[name for name, _ in cases]}\n        if unknown:\n            raise ValueError(f\"Unknown cases: {sorted(unknown)}\")\n        cases = [(name, instruction) for name, instruction in cases if name in args.cases]\n    if args.clean_stale_cases and not args.dry_run:\n        keep = {source_id, *[name for name, _ in module.EDIT_CASES]}\n        for folder in (args.out_root / \"cases\").glob(\"*\"):\n            if folder.is_dir() and folder.name not in keep:\n                if not folder.resolve().is_relative_to(args.out_root):\n                    raise ValueError(f\"Unsafe case directory: {folder}\")\n                shutil.rmtree(folder)\n    manifest = dict(schema_version=3, suite_name=f\"pcve_{scene}_suite\", scene=scene,\n                    baseline_physics=vocab.baseline_physics, total_frames=round(args.fps * args.duration_sec),\n                    fps=args.fps, duration_sec=args.duration_sec, physical_duration_sec=args.duration_sec,\n                    playback_duration_sec=args.duration_sec, slow_motion=1, sample_fps=args.fps,\n                    samples=args.samples, resolution=args.resolution, source=None, edits=[])\n    path = args.out_root / \"suite_manifest.json\"\n    for index, (case_id, instruction) in enumerate([(source_id, None), *cases]):\n        folder = args.out_root / \"cases\" / case_id\n        record = dict(case_id=case_id, kind=\"edit\" if instruction else \"source\",\n                      case_dir=str(folder), seed=7300 + index, status=\"pending\")\n        override = None\n        if instruction:\n            edit = dsl.parse(instruction, vocab)\n            override = {\"physics\": dsl.to_scenario_override(edit, vocab)}\n            record.update(source_case_id=source_id, edit_dsl=instruction,\n                          edit_summary=\"Change the declared physical parameter and simulate the resulting rigid-body interaction.\",\n                          applies_from_frame=dsl.starts_at_frame(edit), prompts=dsl.make_prompts(edit, vocab),\n                          physics_diff={f\"{edit.property_name} ({edit.object_id})\": {\n                              \"from\": dsl.baseline_value_for(edit, vocab), \"to\": dsl.resolved_to_value(edit, vocab)},\n                              \"timing\": dsl.timing_diff(edit, vocab)})\n            manifest[\"edits\"].append(record)\n        else:\n            record[\"description\"] = module.DESCRIPTION\n            manifest[\"source\"] = record\n        if not args.dry_run:\n            prompts = dict(schema_version=2 if instruction else 1, **record)\n            if not instruction:\n                prompts[\"prompts\"] = module.DESCRIPTION\n            write_json(folder / \"prompts.json\", prompts)\n            write_json(path, manifest)\n        try:\n            record.update(run_case(scene, folder, args, record[\"seed\"], override))\n        except Exception:\n            record[\"status\"] = \"failed\"\n            write_json(path, manifest)\n            raise\n        if not args.dry_run:\n            write_json(path, manifest)\n", "pcve_render_quality": "\"\"\"Appearance render setup only; no simulation settings or shared project edits.\"\"\"\n\nimport sys\nfrom pathlib import Path\nsys.path.insert(0, str(Path(__file__).resolve().parents[2]))\nfrom pcve_blender_compat import (shader_socket, set_shader_input, eevee_engine, set_eevee_property, set_color_property)\ndef configure_renderer(bpy,scene,args):\n    scene.render.engine=eevee_engine() if args.engine=='eevee' else 'CYCLES'\n    if args.engine=='eevee':\n        set_eevee_property(scene.eevee, 'taa_render_samples', args.samples);set_eevee_property(scene.eevee, 'use_raytracing', False)\n        set_eevee_property(scene.eevee, 'ray_tracing_options.resolution_scale', '2');set_eevee_property(scene.eevee, 'ray_tracing_options.screen_trace_quality', 0.6)\n        set_eevee_property(scene.eevee, 'use_gtao', True);set_eevee_property(scene.eevee, 'gtao_distance', 0.2);set_eevee_property(scene.eevee, 'gtao_quality', 1.0)\n        set_eevee_property(scene.eevee, 'shadow_ray_count', 1);set_eevee_property(scene.eevee, 'shadow_step_count', 8)\n    else:\n        scene.cycles.samples=args.samples;scene.cycles.use_denoising=True;scene.cycles.max_bounces=8;scene.cycles.diffuse_bounces=4;scene.cycles.glossy_bounces=4\n        scene.cycles.adaptive_threshold=.008;scene.cycles.seed=19;scene.render.use_persistent_data=True\n        # Default 1.5 px pixel filter softens fine background detail; 1.0 keeps the\n        # scanned bookshelf textures crisp without aliasing the suspension threads.\n        scene.cycles.filter_width=1.0\n        scene.cycles.device='CPU'\n        if args.device=='auto':\n            prefs=bpy.context.preferences.addons['cycles'].preferences\n            try:\n                prefs.compute_device_type='CUDA';prefs.get_devices();available=[dev for dev in prefs.devices if dev.type=='CUDA']\n                for dev in prefs.devices:dev.use=(dev.type=='CUDA')\n                if available:\n                    scene.cycles.device='GPU';scene.cycles.denoiser='OPTIX' if any(dev.type=='OPTIX' for dev in prefs.devices) else 'OPENIMAGEDENOISE'\n                    print('[render] CUDA: '+', '.join(dev.name for dev in available),flush=True)\n            except Exception as exc:\n                scene.cycles.device='CPU';scene.cycles.denoiser='OPENIMAGEDENOISE'\n                print('[render] CPU fallback: '+str(exc),flush=True)\n        return scene.cycles.device\n    return 'GPU'\n\n\ndef configure_color(scene):\n    set_color_property(scene.view_settings, 'view_transform', 'AgX');set_color_property(scene.view_settings, 'look', 'AgX - Medium High Contrast');scene.view_settings.exposure=-.22\n\n\ndef prepare_eevee(bpy,scene,moving):\n    if scene.render.engine!=eevee_engine() or bpy.app.version<(4,2,0):return\n    for light in bpy.data.lights:light.use_shadow_jitter=False\n    scene.use_nodes=True;nodes=scene.node_tree.nodes;links=scene.node_tree.links;nodes.clear()\n    layers=nodes.new('CompositorNodeRLayers');denoise=nodes.new('CompositorNodeDenoise');denoise.use_hdr=True\n    composite=nodes.new('CompositorNodeComposite');links.new(layers.outputs['Image'],denoise.inputs['Image']);links.new(denoise.outputs['Image'],composite.inputs['Image'])\n    probe_data=bpy.data.lightprobes.new('Static room irradiance','VOLUME');probe_data.resolution_x=6;probe_data.resolution_y=4;probe_data.resolution_z=4;probe_data.bake_samples=32;probe_data.surfel_density=10\n    probe=bpy.data.objects.new('Static room irradiance',probe_data);scene.collection.objects.link(probe);probe.location=[.2,.5,1.3];probe.scale=[2.5,2.2,1.6]\n    dynamic=list(moving)\n    for obj in list(dynamic):dynamic.extend(obj.children_recursive)\n    dynamic=list(dict.fromkeys(dynamic));previous=[obj.hide_render for obj in dynamic]\n    try:\n        for obj in dynamic:obj.hide_render=True\n        bpy.context.view_layer.objects.active=probe;probe.select_set(True)\n        print('[render] Baking static room indirect light',flush=True);bpy.ops.object.lightprobe_cache_bake(subset='ALL')\n    finally:\n        for obj,hidden in zip(dynamic,previous):obj.hide_render=hidden\n", "scene_support": "", "scene_support.pendulum_box_collision.cache_contract": "\"\"\"Reject trajectories made with different geometry, dynamics or timing.\n\nThe cache is the only thing the renderer and the suite re-use across runs, so\nit has to be able to prove it belongs to the current code. The signature covers\nthe simulator implementation, the geometry module, this file, the four physics\nparameters and the sampling clock; the object metadata is compared field by\nfield as a second line of defence.\n\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nimport hashlib, json\nfrom pathlib import Path\nfrom scene_support.pendulum_box_collision.scene_geometry import (\n    BOB_CENTER_Z, BOB_RADIUS, BOX_SIZE, BOX_START_X, PENDULUM_LENGTH, PIVOT,\n    TABLE_Z, moving_objects)\n\ndef _scene_directory():\n    scripts_root = _PCVE_ROOT / 'clean_scripts'\n    for candidate in (scripts_root / \"rigid_rigid\" / \"pendulum_box_collision\", scripts_root / \"pendulum_box_collision\"):\n        if candidate.is_dir():\n            return candidate\n    raise FileNotFoundError(\"Scene directory not found for pendulum_box_collision\")\n\n\nCACHE_SCHEMA_VERSION = 3\n\n\ndef geometry_metadata():\n    return dict(box_size=list(BOX_SIZE), box_start_x=BOX_START_X, table_z=TABLE_Z,\n                bob_radius=BOB_RADIUS, pendulum_length=PENDULUM_LENGTH,\n                pivot=list(PIVOT), bob_center_z=BOB_CENTER_Z)\n\n\ndef simulation_signature(scenario):\n    import hashlib, json\n    scene_dir = _PCVE_SCENE_ROOT\n    common_dir = _PCVE_ROOT / \"clean_scripts\"\n    files = list(scene_dir.glob(\"*.py\")) + list(common_dir.glob(\"*.py\"))\n    implementation = {str(path.relative_to(_PCVE_ROOT)): hashlib.sha256(path.read_bytes()).hexdigest()\n                      for path in files if path.is_file()}\n    payload = dict(implementation=implementation, scenario=scenario)\n    return hashlib.sha256(json.dumps(payload, sort_keys=True, allow_nan=False, default=str).encode()).hexdigest()\ndef validate_cache(data, scenario=None):\n    error = 'Incompatible physics cache: geometry, dynamics or timing changed; resimulate first.'\n    if data.get('scene') != 'pendulum_box_collision' or data.get('schema_version') != CACHE_SCHEMA_VERSION:\n        raise ValueError(error)\n    requested = scenario if scenario is not None else data['scenario']\n    if data.get('simulation_signature') != simulation_signature(requested):\n        raise ValueError(error)\n    if data.get('geometry') != geometry_metadata() or data.get('objects') != moving_objects(requested['physics']):\n        raise ValueError(error)\n    r = requested['render']; count = round(r['fps'] * r['slow_motion'] * r['duration_sec'])\n    if (data.get('playback_fps') != r['fps'] or data.get('slow_motion') != r['slow_motion']\n            or data.get('physical_duration_sec') != r['duration_sec'] or data.get('frame_end') != count\n            or len(data.get('frames', [])) != count or data['scenario']['physics'] != requested['physics']):\n        raise ValueError(error)\n    if not data.get('quality', {}).get('valid'):\n        raise ValueError('Invalid physics cache')\n", "scene_support.pendulum_box_collision.render_quality": "\"\"\"The same engine/device interface used by the other scene renderers.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\n\nimport sys\nfrom pathlib import Path\nsys.path.insert(0, str(_PCVE_ROOT / 'clean_scripts'))\nfrom pcve_blender_compat import (shader_socket, set_shader_input, eevee_engine, set_eevee_property, set_color_property)\ndef configure_renderer(bpy, scene, args):\n    scene.render.engine = 'CYCLES' if args.engine == 'cycles' else eevee_engine()\n    scene.render.threads_mode = 'FIXED'; scene.render.threads = 4\n    if args.engine == 'cycles':\n        scene.cycles.samples = args.samples; scene.cycles.use_denoising = True\n        scene.cycles.use_adaptive_sampling = True; scene.cycles.adaptive_threshold = .005\n        scene.cycles.adaptive_min_samples = min(32, args.samples)\n        scene.cycles.max_bounces = 8; scene.cycles.diffuse_bounces = 4; scene.cycles.glossy_bounces = 4\n        scene.render.use_persistent_data = True; scene.cycles.device = 'CPU'\n        if args.device == 'auto':\n            try:\n                prefs = bpy.context.preferences.addons['cycles'].preferences\n                prefs.compute_device_type = 'CUDA'; prefs.get_devices()\n                available = [d for d in prefs.devices if d.type == 'CUDA']\n                for d in prefs.devices:\n                    d.use = d.type == 'CUDA'\n                if available:\n                    scene.cycles.device = 'GPU'\n            except Exception:\n                scene.cycles.device = 'CPU'\n        return scene.cycles.device\n    return 'GPU'\n\n\ndef configure_color(scene):\n    set_color_property(scene.view_settings, 'view_transform', 'AgX')\n    set_color_property(scene.view_settings, 'look', 'AgX - Medium High Contrast')\n    scene.view_settings.exposure = -.10\n", "scene_support.pendulum_box_collision.runtime_support": "\"\"\"Local runtime discovery; scripts also work in ordinary Python/Blender installs.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nimport os, sys\nfrom pathlib import Path\n\nROOT = _PCVE_ROOT\n_dll_handles = []\nif os.name == 'nt':\n    directory = Path(sys.prefix) / 'Library/bin'\n    if directory.exists():\n        _dll_handles.append(os.add_dll_directory(str(directory)))\n\n\ndef python_for(role):\n    sys.path.insert(0, str(ROOT/'clean_scripts'))\n    from pcve_scene_runtime import python_for as resolve_python\n    return resolve_python(role)\n", "scene_support.pendulum_box_collision.scene_config": "\"\"\"Scenario contract for the pendulum-and-box impact scene.\n\nOne definition of the four editable physics parameters, the sampling window and\nthe camera, imported by the simulator, the renderer, the suite builder and the\nbatch sampler. Nothing outside this file decides what an edit may change.\n\nWorld conventions\n-----------------\n* **+X** runs along the bench from the wooden box towards the pendulum. The box\n  starts at negative X and travels towards +X; the bob hangs at ``x = 0``.\n* **+Y** points from the camera into the wall, so the camera sits at negative Y.\n* **+Z** is up. The bench top is ``z = 0.76`` and gravity acts along -Z.\n* SI units everywhere: metres, kilograms, seconds, radians in the cache.\n\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nfrom copy import deepcopy\nimport json, math\n\nSCENE_NAME = 'pendulum_box_collision'\n\n# The four knobs the scene was built to expose. Bob mass and bob speed are the\n# pendulum's two; box mass and box speed are the slider's two. Everything else\n# -- restitution, friction, pendulum length, box size, release geometry -- is\n# fixed so that an edit changes one thing and nothing else.\nBASELINE_PHYSICS = dict(bob_mass=.40, bob_speed=.55, box_mass=.40, box_speed=1.30)\n\n# Legal ranges, enforced before every simulation.\n#\n# ``bob_speed`` is bounded from above by the block, not by the solver: the bob\n# starts at the lowest point and rises ``v^2/2g``, so the swing amplitude grows\n# with the square of this number. At 0.90 m/s the bob peaks 26.5 degrees up the\n# arc and its centre is still 17 mm below the top of the 85 mm slider, which is\n# what keeps a whole-face impact possible at any phase. Above roughly 0.97 m/s\n# the bob would meet the block's top edge instead of its face.\n#\n# ``box_speed`` is bounded from below by the approach: the slider has 0.70 m of\n# bench to cover before it reaches the bob, and the initial approach window is 1.05 s, so a\n# block below about 1.10 m/s would miss the original approach window.\n# Keep these staging limits unchanged when extending the aftermath.\nPHYSICS_LIMITS = dict(bob_mass=(.05, 5.0), bob_speed=(0.0, .90),\n                      box_mass=(.05, 5.0), box_speed=(1.12, 3.5))\n\n# Show the return collision and subsequent motion at real-time playback.\nDEFAULT_DURATION_SEC = 4.0\nTOTAL_FRAMES = 96\n\n\ndef defaults():\n    return dict(schema_version=1, scene=SCENE_NAME,\n        physics=deepcopy(BASELINE_PHYSICS),\n        render=dict(fps=24, duration_sec=DEFAULT_DURATION_SEC, slow_motion=1,\n                    resolution=[1280, 720], samples=128),\n        camera=dict(location=[.68, -2.28, 1.20], target=[-.02, .03, .925],\n                    ortho_scale=1.06))\n\n\ndef merge(base, overrides):\n    result = deepcopy(base)\n    for key, value in overrides.items():\n        result[key] = (merge(result[key], value)\n                       if isinstance(value, dict) and isinstance(result.get(key), dict)\n                       else deepcopy(value))\n    return result\n\n\ndef validate(s):\n    if set(s) - {'schema_version', 'scene', 'physics', 'render', 'camera', 'seed'} or s.get('scene') != SCENE_NAME:\n        raise ValueError('Invalid scenario fields or scene name')\n    c = s['physics']; r = s['render']\n    if set(c) != set(BASELINE_PHYSICS):\n        raise ValueError('Unknown or missing physics parameter')\n    for key, value in c.items():\n        if key == 'timed_edits':\n            if not isinstance(value, list) or any(\n                    not isinstance(entry, dict) or set(entry) != {'frame', 'params'}\n                    or type(entry['frame']) is not int\n                    or not isinstance(entry['params'], dict) or not entry['params']\n                    or any(not isinstance(v, (int, float)) or not math.isfinite(v)\n                           for v in entry['params'].values())\n                    for entry in value):\n                raise ValueError('Invalid timed_edits schedule')\n            continue\n        if not isinstance(value, (int, float)) or not math.isfinite(value):\n            raise ValueError(f'Invalid {key}')\n        low, high = PHYSICS_LIMITS[key]\n        if not low <= value <= high:\n            raise ValueError(f'{key} must be between {low} and {high}')\n    if not isinstance(r['fps'], int) or r['fps'] <= 0 or not math.isfinite(r['duration_sec']) or r['duration_sec'] <= 0:\n        raise ValueError('Invalid timing')\n    if r['slow_motion'] not in (1, 2, 4, 8):\n        raise ValueError('slow_motion must be 1, 2, 4 or 8')\n    if r['fps'] * r['slow_motion'] > 2400:\n        raise ValueError('Sample rate exceeds physics rate')\n    if round(r['fps'] * r['slow_motion'] * r['duration_sec']) < 1:\n        raise ValueError('Empty trajectory')\n    if (not isinstance(r['samples'], int) or r['samples'] < 1 or len(r['resolution']) != 2\n            or any(not isinstance(v, int) or v < 2 or v % 2 for v in r['resolution'])):\n        raise ValueError('Invalid render settings; use even resolution')\n    camera = s['camera']\n    for key in ('location', 'target'):\n        if len(camera[key]) != 3 or not all(math.isfinite(v) for v in camera[key]):\n            raise ValueError('Invalid camera vector')\n    if camera['location'] == camera['target'] or not math.isfinite(camera['ortho_scale']) or camera['ortho_scale'] <= 0:\n        raise ValueError('Invalid camera')\n\n\ndef load_scenario(args):\n    s = merge(defaults(), json.loads(args.scenario_json.read_text(encoding='utf-8'))) if args.scenario_json else defaults()\n    if args.scenario_overrides_json:\n        s = merge(s, json.loads(args.scenario_overrides_json.read_text(encoding='utf-8')))\n    for key in BASELINE_PHYSICS:\n        if getattr(args, key, None) is not None:\n            s['physics'][key] = getattr(args, key)\n    for key in ('fps', 'duration_sec', 'slow_motion', 'resolution', 'samples'):\n        if getattr(args, key, None) is not None:\n            s['render'][key] = getattr(args, key)\n    validate(s)\n    return s\n", "scene_support.pendulum_box_collision.scene_environment": "\"\"\"Procedural middle-school physics lab and the two visible rigid bodies.\n\nOnly geometry and appearance live here. Nothing in this module knows about\nphysics parameters, so a mass or speed edit changes the clip without touching\na single material, and the collision shapes in ``simulate_pendulum_box_collision.py``\nstay the authority on size and contact.\n\nThe set is built the way the other bench-top scenes build theirs: every prop is\nprocedural except for the local textured blackboard and pen assets; the bench top is exactly ``TABLE_Z`` so the\nblock visibly rests on the surface the solver uses, and the retort stand's rod\nends at ``scene_geometry.PIVOT`` so the drawn thread leaves from the point the\nconstraint hangs from.\n\nLayout, seen from the default camera at -Y\n------------------------------------------\n* the block starts left of centre and slides right;\n* the bob hangs at x = 0, just above the bench, and swings in the X-Z plane;\n* the retort stand stands to the right, its cross-arm reaching left to the\n  pivot, so neither the rod nor its base is ever in the block's path;\n* the slate board, splashback and shelf stay behind y = 1.2, out of reach.\n\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\n\nimport sys\nfrom pathlib import Path\nsys.path.insert(0, str(_PCVE_ROOT / 'clean_scripts'))\nfrom pcve_blender_compat import (shader_socket, set_shader_input, eevee_engine, set_eevee_property, set_color_property)\nimport math, random\nfrom pathlib import Path\nfrom scene_support.pendulum_box_collision.scene_geometry import (\n    BENCH_SIZE, BOB_RADIUS, BOX_SIZE, PENDULUM_LENGTH, PIVOT, TABLE_Z)\n\nENVIRONMENT_THEME = 'school_physics_lab_pendulum_bench'\nAPPEARANCE_VERSION = 4\n\n# The visible bench top must be the same surface the solver drops the block on.\nBENCH_TOP = TABLE_Z\nSTAND = (0.40, 0.12)          # foot of the retort stand, on the bench\nSTAND_TOP = PIVOT[2] + .055\n\n\n# --------------------------------------------------------------- materials\n\n\ndef _material(bpy, name, color, rough=.62, metallic=0., coat=0., bump=0., bump_scale=14.,\n              grain=None, speckle=None, speckle_color=None, bump_distance=.00025):\n    \"\"\"Principled surface with optional procedural relief, wood grain or aggregate.\"\"\"\n    material = bpy.data.materials.new(name)\n    material.diffuse_color = (*color, 1.); material.use_nodes = True\n    nodes = material.node_tree.nodes; links = material.node_tree.links\n    bsdf = nodes['Principled BSDF']\n    bsdf.inputs['Base Color'].default_value = (*color, 1.)\n    bsdf.inputs['Roughness'].default_value = rough\n    if metallic:\n        bsdf.inputs['Metallic'].default_value = metallic\n    if coat:\n        set_shader_input(bsdf, 'Coat Weight', coat)\n        set_shader_input(bsdf, 'Coat Roughness', 0.24)\n    if not (bump > 0. or speckle):\n        return material\n    vector = nodes.new('ShaderNodeTexCoord').outputs['Object']\n    if grain:\n        mapping = nodes.new('ShaderNodeMapping'); mapping.inputs['Scale'].default_value = grain\n        links.new(mapping.inputs['Vector'], vector); vector = mapping.outputs['Vector']\n    if bump > 0.:\n        noise = nodes.new('ShaderNodeTexNoise')\n        noise.inputs['Scale'].default_value = bump_scale\n        noise.inputs['Detail'].default_value = 3.\n        noise.inputs['Roughness'].default_value = .52\n        links.new(noise.inputs['Vector'], vector)\n        relief = nodes.new('ShaderNodeBump')\n        relief.inputs['Strength'].default_value = bump\n        relief.inputs['Distance'].default_value = bump_distance\n        links.new(relief.inputs['Height'], noise.outputs['Fac'])\n        links.new(bsdf.inputs['Normal'], relief.outputs['Normal'])\n    if speckle:\n        aggregate = nodes.new('ShaderNodeTexVoronoi'); aggregate.inputs['Scale'].default_value = speckle\n        links.new(aggregate.inputs['Vector'], vector)\n        ramp = nodes.new('ShaderNodeValToRGB')\n        ramp.color_ramp.elements[0].position = .36; ramp.color_ramp.elements[0].color = (*color, 1.)\n        ramp.color_ramp.elements[1].position = .68\n        ramp.color_ramp.elements[1].color = (*(speckle_color or tuple(c * .55 for c in color)), 1.)\n        links.new(ramp.inputs['Fac'], aggregate.outputs['Distance'])\n        links.new(bsdf.inputs['Base Color'], ramp.outputs['Color'])\n    return material\n\n\ndef _wood(bpy, name, light, dark, scale=(1.6, 9., 22.), rough=.44, coat=.12):\n    \"\"\"Two-tone grain: a stretched noise drives a colour ramp, plus fine relief.\n\n    A single flat brown cube reads as plastic at this distance. Wood needs the\n    value to wander along the length of the board, which is what the very\n    anisotropic mapping scale does: fine across the grain, long along it.\n    \"\"\"\n    material = bpy.data.materials.new(name); material.use_nodes = True\n    nodes = material.node_tree.nodes; links = material.node_tree.links\n    bsdf = nodes['Principled BSDF']\n    bsdf.inputs['Roughness'].default_value = rough\n    set_shader_input(bsdf, 'Coat Weight', coat)\n    set_shader_input(bsdf, 'Coat Roughness', 0.22)\n    coord = nodes.new('ShaderNodeTexCoord')\n    mapping = nodes.new('ShaderNodeMapping'); mapping.inputs['Scale'].default_value = scale\n    links.new(mapping.inputs['Vector'], coord.outputs['Object'])\n    grain = nodes.new('ShaderNodeTexNoise')\n    grain.inputs['Scale'].default_value = 5.2\n    grain.inputs['Detail'].default_value = 5.\n    grain.inputs['Roughness'].default_value = .55\n    links.new(grain.inputs['Vector'], mapping.outputs['Vector'])\n    ramp = nodes.new('ShaderNodeValToRGB')\n    ramp.color_ramp.elements[0].position = .30; ramp.color_ramp.elements[0].color = (*dark, 1.)\n    ramp.color_ramp.elements[1].position = .70; ramp.color_ramp.elements[1].color = (*light, 1.)\n    links.new(ramp.inputs['Fac'], grain.outputs['Fac'])\n    links.new(bsdf.inputs['Base Color'], ramp.outputs['Color'])\n    pores = nodes.new('ShaderNodeTexNoise')\n    pores.inputs['Scale'].default_value = 240.\n    pores.inputs['Detail'].default_value = 3.\n    links.new(pores.inputs['Vector'], mapping.outputs['Vector'])\n    relief = nodes.new('ShaderNodeBump')\n    relief.inputs['Strength'].default_value = .12\n    relief.inputs['Distance'].default_value = .00018\n    links.new(relief.inputs['Height'], pores.outputs['Fac'])\n    links.new(bsdf.inputs['Normal'], relief.outputs['Normal'])\n    return material\n\n\ndef _bench_top(bpy, name, color, rough=.46):\n    \"\"\"Dark lino bench top: tonal drift, long scuffs and a wide soft sheen.\"\"\"\n    material = bpy.data.materials.new(name); material.use_nodes = True\n    nodes = material.node_tree.nodes; links = material.node_tree.links\n    bsdf = nodes['Principled BSDF']\n    bsdf.inputs['Roughness'].default_value = rough\n    set_shader_input(bsdf, 'Coat Weight', 0.12)\n    set_shader_input(bsdf, 'Coat Roughness', 0.34)\n    coord = nodes.new('ShaderNodeTexCoord')\n    drift = nodes.new('ShaderNodeTexNoise')\n    drift.inputs['Scale'].default_value = 1.5\n    drift.inputs['Detail'].default_value = 4.\n    drift.inputs['Roughness'].default_value = .62\n    links.new(drift.inputs['Vector'], coord.outputs['Object'])\n    tone = nodes.new('ShaderNodeValToRGB')\n    tone.color_ramp.elements[0].position = .26\n    tone.color_ramp.elements[0].color = (*(c * .78 for c in color), 1.)\n    tone.color_ramp.elements[1].position = .78\n    tone.color_ramp.elements[1].color = (*(min(1., c * 1.26) for c in color), 1.)\n    links.new(tone.inputs['Fac'], drift.outputs['Fac'])\n    links.new(bsdf.inputs['Base Color'], tone.outputs['Color'])\n    scuff_coord = nodes.new('ShaderNodeMapping')\n    scuff_coord.inputs['Scale'].default_value = (2.6, 8., 3.)\n    links.new(scuff_coord.inputs['Vector'], coord.outputs['Object'])\n    scuff = nodes.new('ShaderNodeTexNoise')\n    scuff.inputs['Scale'].default_value = 4.0\n    scuff.inputs['Detail'].default_value = 2.\n    links.new(scuff.inputs['Vector'], scuff_coord.outputs['Vector'])\n    mask = nodes.new('ShaderNodeValToRGB')\n    mask.color_ramp.elements[0].position = .64; mask.color_ramp.elements[0].color = (0., 0., 0., 1.)\n    mask.color_ramp.elements[1].position = .77; mask.color_ramp.elements[1].color = (1., 1., 1., 1.)\n    links.new(mask.inputs['Fac'], scuff.outputs['Fac'])\n    wear = nodes.new('ShaderNodeMixRGB'); wear.inputs['Fac'].default_value = 1.\n    links.new(wear.inputs['Fac'], mask.outputs['Color'])\n    links.new(wear.inputs['Color1'], tone.outputs['Color'])\n    wear.inputs['Color2'].default_value = (*(c * .70 for c in color), 1.)\n    links.new(bsdf.inputs['Base Color'], wear.outputs['Color'])\n    gloss = nodes.new('ShaderNodeMixRGB'); gloss.blend_type = 'MIX'\n    links.new(gloss.inputs['Fac'], mask.outputs['Color'])\n    gloss.inputs['Color1'].default_value = (rough, rough, rough, 1.)\n    gloss.inputs['Color2'].default_value = (.64, .64, .64, 1.)\n    links.new(bsdf.inputs['Roughness'], gloss.outputs['Color'])\n    relief = nodes.new('ShaderNodeBump')\n    relief.inputs['Strength'].default_value = .05\n    relief.inputs['Distance'].default_value = .00012\n    links.new(relief.inputs['Height'], mask.outputs['Color'])\n    links.new(bsdf.inputs['Normal'], relief.outputs['Normal'])\n    return material\n\n\ndef _place_blackboard_asset(bpy):\n    \"\"\"Use the board's original mesh, UVs and PBR maps; omit its pinned note.\"\"\"\n    from mathutils import Matrix, Vector\n    asset = _PCVE_ROOT / 'assets' / 'models' / 'realistic_blackboard.glb'\n    before = set(bpy.data.objects)\n    bpy.ops.import_scene.gltf(filepath=str(asset))\n    imported = set(bpy.data.objects) - before\n    bpy.context.view_layer.update()\n    meshes = [obj for obj in imported if obj.type == 'MESH']\n    if not meshes:\n        raise ValueError(f'Blackboard asset contains no mesh: {asset}')\n    def bounds(obj):\n        points = [obj.matrix_world @ Vector(corner) for corner in obj.bound_box]\n        return (Vector(tuple(min(v[i] for v in points) for i in range(3))),\n                Vector(tuple(max(v[i] for v in points) for i in range(3))))\n    source = max(meshes, key=lambda obj: (bounds(obj)[1] - bounds(obj)[0]).length)\n    low, high = bounds(source)\n    centre = (low + high) / 2\n    scale = .74 / (high.z - low.z)\n    mesh = source.data.copy()\n    mesh.transform(source.matrix_world)\n    board = bpy.data.objects.new('Real blackboard (realistic_blackboard.glb)', mesh)\n    bpy.context.scene.collection.objects.link(board)\n    board.matrix_world = (Matrix.Translation((-.20, 1.24, 1.085))\n                          @ Matrix.Scale(scale, 4) @ Matrix.Translation(-centre))\n    board['asset_path'] = 'assets/models/realistic_blackboard.glb'\n    for obj in imported:\n        bpy.data.objects.remove(obj, do_unlink=True)\n    return board\n\n\ndef _place_pen_asset(bpy):\n    \"\"\"Keep the GLB's UVs/materials and seat its actual bounds on the bench.\"\"\"\n    from mathutils import Matrix, Vector\n    asset = _PCVE_ROOT / 'assets' / 'models' / 'the_pen.glb'\n    before = set(bpy.data.objects)\n    bpy.ops.import_scene.gltf(filepath=str(asset))\n    imported = set(bpy.data.objects) - before\n    bpy.context.view_layer.update()\n    points = [obj.matrix_world @ Vector(corner) for obj in imported\n              if obj.type == 'MESH' for corner in obj.bound_box]\n    if not points:\n        raise ValueError(f'Pen asset contains no mesh: {asset}')\n    low = Vector(tuple(min(v[i] for v in points) for i in range(3)))\n    high = Vector(tuple(max(v[i] for v in points) for i in range(3)))\n    scale = .145 / (high.x - low.x)\n    centre = (low + high) / 2\n    root = bpy.data.objects.new('Desk pen (the_pen.glb)', None)\n    bpy.context.scene.collection.objects.link(root)\n    for obj in imported:\n        if obj.parent not in imported:\n            obj.parent = root\n    root.matrix_world = (Matrix.Translation((-.30, -.235, BENCH_TOP + .00015))\n                         @ Matrix.Rotation(.32, 4, 'Z') @ Matrix.Scale(scale, 4)\n                         @ Matrix.Translation((-centre.x, -centre.y, -low.z)))\n    root['asset_path'] = 'assets/models/the_pen.glb'\n    root['length_m'] = .145\n    return root\n\n\ndef _alpha_material(bpy, name, color, rough):\n    \"\"\"Translucent surface helper; Cycles needs no blend mode, EEVEE does.\"\"\"\n    material = bpy.data.materials.new(name); material.use_nodes = True\n    bsdf = material.node_tree.nodes['Principled BSDF']\n    bsdf.inputs['Base Color'].default_value = (*color, 1.)\n    bsdf.inputs['Roughness'].default_value = rough\n    for attribute, value in (('surface_render_method', 'DITHERED'), ('blend_method', 'BLEND')):\n        try:\n            setattr(material, attribute, value)\n        except Exception:\n            pass\n    return material\n\n\ndef _alpha_surface(material, bsdf, alpha_socket):\n    \"\"\"Mix with a Transparent BSDF instead of using Principled's Alpha.\n\n    Feeding Alpha leaves the surface blocking shadow rays, which turns a film of\n    pigment into a black rectangle on whatever is behind it.\n    \"\"\"\n    nodes = material.node_tree.nodes; links = material.node_tree.links\n    output = [node for node in nodes if node.type == 'OUTPUT_MATERIAL'][0]\n    for link in list(output.inputs['Surface'].links):\n        links.remove(link)\n    clear = nodes.new('ShaderNodeBsdfTransparent')\n    mix = nodes.new('ShaderNodeMixShader')\n    links.new(mix.inputs[0], alpha_socket)\n    links.new(mix.inputs[1], clear.outputs[0])\n    links.new(mix.inputs[2], bsdf.outputs[0])\n    links.new(output.inputs['Surface'], mix.outputs[0])\n    return mix\n\n\ndef _chalk_material(bpy, name, color, dust=.42, value_spread=.22, bump=.30):\n    \"\"\"Pigment that skips and fades like pressed chalk instead of flat paint.\"\"\"\n    material = _alpha_material(bpy, name, color, .94)\n    nodes = material.node_tree.nodes; links = material.node_tree.links\n    bsdf = nodes['Principled BSDF']\n    set_shader_input(bsdf, 'Specular IOR Level', 0.02)\n    coord = nodes.new('ShaderNodeTexCoord')\n    coverage = nodes.new('ShaderNodeTexNoise')\n    coverage.inputs['Scale'].default_value = 64.\n    coverage.inputs['Detail'].default_value = 3.\n    coverage.inputs['Roughness'].default_value = .58\n    links.new(coverage.inputs['Vector'], coord.outputs['Object'])\n    ramp = nodes.new('ShaderNodeValToRGB')\n    ramp.color_ramp.elements[0].position = .36; ramp.color_ramp.elements[0].color = (0., 0., 0., 1.)\n    ramp.color_ramp.elements[1].position = .64; ramp.color_ramp.elements[1].color = (1., 1., 1., 1.)\n    links.new(ramp.inputs['Fac'], coverage.outputs['Fac'])\n    coarse = nodes.new('ShaderNodeMath'); coarse.operation = 'MULTIPLY_ADD'\n    coarse.inputs[1].default_value = 1. - dust; coarse.inputs[2].default_value = dust\n    links.new(coarse.inputs[0], ramp.outputs['Color'])\n    grain = nodes.new('ShaderNodeTexNoise')\n    grain.inputs['Scale'].default_value = 520.\n    grain.inputs['Detail'].default_value = 4.\n    grain.inputs['Roughness'].default_value = .5\n    links.new(grain.inputs['Vector'], coord.outputs['Object'])\n    speckle = nodes.new('ShaderNodeValToRGB')\n    speckle.color_ramp.elements[0].position = .28; speckle.color_ramp.elements[0].color = (0., 0., 0., 1.)\n    speckle.color_ramp.elements[1].position = .58; speckle.color_ramp.elements[1].color = (1., 1., 1., 1.)\n    links.new(speckle.inputs['Fac'], grain.outputs['Fac'])\n    lift = nodes.new('ShaderNodeMath'); lift.operation = 'MULTIPLY_ADD'\n    lift.inputs[1].default_value = .55; lift.inputs[2].default_value = .45\n    links.new(lift.inputs[0], speckle.outputs['Color'])\n    alpha = nodes.new('ShaderNodeMath'); alpha.operation = 'MULTIPLY'\n    links.new(alpha.inputs[0], coarse.outputs['Value']); links.new(alpha.inputs[1], lift.outputs['Value'])\n    _alpha_surface(material, bsdf, alpha.outputs['Value'])\n    tone = nodes.new('ShaderNodeMixRGB'); tone.blend_type = 'MIX'\n    tone.inputs['Color1'].default_value = (*color, 1.)\n    tone.inputs['Color2'].default_value = (*(c * (1. - value_spread) for c in color), 1.)\n    links.new(tone.inputs['Fac'], coverage.outputs['Fac'])\n    links.new(bsdf.inputs['Base Color'], tone.outputs['Color'])\n    if bump > 0.:\n        relief = nodes.new('ShaderNodeBump')\n        relief.inputs['Strength'].default_value = bump\n        relief.inputs['Distance'].default_value = .00008\n        links.new(relief.inputs['Height'], grain.outputs['Fac'])\n        links.new(bsdf.inputs['Normal'], relief.outputs['Normal'])\n    return material\n\n\ndef _chalk_halo_material(bpy, name, color, strength=.13):\n    \"\"\"Loose powder hugging a mark: wide, ragged and almost transparent.\"\"\"\n    material = _alpha_material(bpy, name, color, .96)\n    nodes = material.node_tree.nodes; links = material.node_tree.links\n    bsdf = nodes['Principled BSDF']\n    set_shader_input(bsdf, 'Specular IOR Level', 0.02)\n    coord = nodes.new('ShaderNodeTexCoord')\n    noise = nodes.new('ShaderNodeTexNoise')\n    noise.inputs['Scale'].default_value = 110.\n    noise.inputs['Detail'].default_value = 4.\n    noise.inputs['Roughness'].default_value = .62\n    links.new(noise.inputs['Vector'], coord.outputs['Object'])\n    ramp = nodes.new('ShaderNodeValToRGB')\n    ramp.color_ramp.elements[0].position = .30; ramp.color_ramp.elements[0].color = (0., 0., 0., 1.)\n    ramp.color_ramp.elements[1].position = .62; ramp.color_ramp.elements[1].color = (1., 1., 1., 1.)\n    links.new(ramp.inputs['Fac'], noise.outputs['Fac'])\n    level = nodes.new('ShaderNodeMath'); level.operation = 'MULTIPLY'\n    level.inputs[1].default_value = strength\n    links.new(level.inputs[0], ramp.outputs['Color'])\n    _alpha_surface(material, bsdf, level.outputs['Value'])\n    return material\n\n\ndef _residue_material(bpy, name, color):\n    \"\"\"Ghost of erased writing: horizontal wipes plus uneven haze.\"\"\"\n    material = _alpha_material(bpy, name, color, .96)\n    nodes = material.node_tree.nodes; links = material.node_tree.links\n    bsdf = nodes['Principled BSDF']\n    coord = nodes.new('ShaderNodeTexCoord')\n    wipe_coord = nodes.new('ShaderNodeMapping')\n    wipe_coord.inputs['Scale'].default_value = (2.2, 1., 17.)\n    links.new(wipe_coord.inputs['Vector'], coord.outputs['Object'])\n    wipe = nodes.new('ShaderNodeTexNoise')\n    wipe.inputs['Scale'].default_value = 4.5\n    wipe.inputs['Detail'].default_value = 3.\n    wipe.inputs['Roughness'].default_value = .6\n    links.new(wipe.inputs['Vector'], wipe_coord.outputs['Vector'])\n    streak = nodes.new('ShaderNodeValToRGB')\n    streak.color_ramp.elements[0].position = .44; streak.color_ramp.elements[0].color = (0., 0., 0., 1.)\n    streak.color_ramp.elements[1].position = .78; streak.color_ramp.elements[1].color = (1., 1., 1., 1.)\n    links.new(streak.inputs['Fac'], wipe.outputs['Fac'])\n    haze = nodes.new('ShaderNodeTexNoise')\n    haze.inputs['Scale'].default_value = 1.6\n    haze.inputs['Detail'].default_value = 4.\n    links.new(haze.inputs['Vector'], coord.outputs['Object'])\n    veil = nodes.new('ShaderNodeValToRGB')\n    veil.color_ramp.elements[0].position = .40; veil.color_ramp.elements[0].color = (.1, .1, .1, 1.)\n    veil.color_ramp.elements[1].position = .72; veil.color_ramp.elements[1].color = (.55, .55, .55, 1.)\n    links.new(veil.inputs['Fac'], haze.outputs['Fac'])\n    mix = nodes.new('ShaderNodeMath'); mix.operation = 'MULTIPLY'\n    links.new(mix.inputs[0], streak.outputs['Color']); links.new(mix.inputs[1], veil.outputs['Color'])\n    strength = nodes.new('ShaderNodeMath'); strength.operation = 'MULTIPLY'\n    strength.inputs[1].default_value = .085\n    links.new(strength.inputs[0], mix.outputs['Value'])\n    _alpha_surface(material, bsdf, strength.outputs['Value'])\n    return material\n\n\n# ------------------------------------------------------------------- meshes\n\n\ndef _cube_mesh(bpy, name, size):\n    \"\"\"A real-world-sized cube mesh, so Object texture coordinates stay isotropic.\"\"\"\n    x, y, z = (value * .5 for value in size)\n    mesh = bpy.data.meshes.new(name)\n    mesh.from_pydata([(-x, -y, -z), (x, -y, -z), (x, y, -z), (-x, y, -z),\n                      (-x, -y, z), (x, -y, z), (x, y, z), (-x, y, z)], [],\n                     [(0, 3, 2, 1), (4, 5, 6, 7), (0, 1, 5, 4),\n                      (1, 2, 6, 5), (2, 3, 7, 6), (3, 0, 4, 7)])\n    mesh.update()\n    return mesh\n\n\ndef _tube_mesh(bpy, name, radius, length, segments=48):\n    import bmesh\n    mesh = bpy.data.meshes.new(name); bm = bmesh.new()\n    bmesh.ops.create_cone(bm, cap_ends=True, cap_tris=False, segments=segments,\n                          radius1=radius, radius2=radius, depth=length)\n    bm.to_mesh(mesh); bm.free(); mesh.update()\n    return mesh\n\n\ndef _cone_mesh(bpy, name, radius1, radius2, length, segments=48):\n    import bmesh\n    mesh = bpy.data.meshes.new(name); bm = bmesh.new()\n    bmesh.ops.create_cone(bm, cap_ends=True, cap_tris=False, segments=segments,\n                          radius1=radius1, radius2=radius2, depth=length)\n    bm.to_mesh(mesh); bm.free(); mesh.update()\n    return mesh\n\n\ndef _sphere_mesh(bpy, name, radius, segments=64, rings=40):\n    import bmesh\n    mesh = bpy.data.meshes.new(name); bm = bmesh.new()\n    bmesh.ops.create_uvsphere(bm, u_segments=segments, v_segments=rings, radius=radius)\n    bm.to_mesh(mesh); bm.free(); mesh.update()\n    for polygon in mesh.polygons:\n        polygon.use_smooth = True\n    return mesh\n\n\n# ---------------------------------------------------------- hand-written chalk\n# Each glyph is a set of monoline strokes on a 0..1 cap-height grid. Stroke\n# geometry and pigment are what make the board read as chalk rather than as a\n# font: see ``_chalk_stroke``.\ndef _arc(cx, cy, rx, ry, a0, a1, steps=14):\n    return [(cx + rx * math.cos(math.radians(a0 + (a1 - a0) * i / steps)),\n             cy + ry * math.sin(math.radians(a0 + (a1 - a0) * i / steps)))\n            for i in range(steps + 1)]\n\n\ndef _bez(p0, p1, p2, steps=10):\n    return [((1 - t) ** 2 * p0[0] + 2 * (1 - t) * t * p1[0] + t * t * p2[0],\n             (1 - t) ** 2 * p0[1] + 2 * (1 - t) * t * p1[1] + t * t * p2[1])\n            for t in (i / steps for i in range(steps + 1))]\n\n\n_GLYPHS = {\n    'A': (.62, [[(0, 0), (.31, 1), (.62, 0)], [(.13, .34), (.49, .34)]]),\n    'B': (.54, [[(0, 0), (0, 1)],\n                [(0, 1), (.22, 1)] + _arc(.24, .78, .24, .22, 90, -90) + [(0, .56)],\n                [(0, .56), (.26, .56)] + _arc(.28, .28, .26, .28, 90, -90) + [(0, 0)]]),\n    'C': (.56, [_arc(.30, .50, .28, .50, 56, 304, 20)]),\n    'D': (.56, [[(0, 0), (0, 1)], [(0, 1), (.20, 1)] + _arc(.22, .50, .32, .50, 90, -90, 20) + [(0, 0)]]),\n    'E': (.50, [[(0, 0), (0, 1)], [(0, 1), (.47, 1)], [(0, .55), (.38, .55)], [(0, 0), (.47, 0)]]),\n    'F': (.48, [[(0, 0), (0, 1)], [(0, 1), (.45, 1)], [(0, .56), (.36, .56)]]),\n    'H': (.54, [[(0, 0), (0, 1)], [(.52, 0), (.52, 1)], [(0, .52), (.52, .52)]]),\n    'I': (.11, [[(.05, 0), (.05, 1)]]),\n    'K': (.52, [[(0, 0), (0, 1)], [(.44, .58), (0, .26)], [(.14, .36), (.46, 0)]]),\n    'L': (.48, [[(0, 1), (0, 0), (.45, 0)]]),\n    'M': (.68, [[(0, 0), (0, 1), (.34, .40), (.68, 1), (.68, 0)]]),\n    'N': (.54, [[(0, 0), (0, 1), (.52, 0), (.52, 1)]]),\n    'O': (.58, [_arc(.29, .50, .28, .50, 0, 360, 28)]),\n    'P': (.48, [[(0, 0), (0, 1)], [(0, 1), (.22, 1)] + _arc(.23, .76, .22, .24, 90, -90) + [(0, .52)]]),\n    'S': (.50, [[(.48, .86), (.40, 1), (.16, 1), (.04, .88), (.03, .74), (.12, .60),\n                 (.36, .53), (.46, .40), (.46, .16), (.34, 0), (.10, 0), (0, .14)]]),\n    'T': (.52, [[(0, 1), (.52, 1)], [(.26, 1), (.26, 0)]]),\n    'U': (.52, [[(0, 1), (0, .16)] + _arc(.26, .16, .26, .16, 180, 360, 16) + [(.52, 1)]]),\n    'V': (.52, [[(0, 1), (.26, 0), (.52, 1)]]),\n    'Y': (.56, [[(0, 1), (.27, .44), (.54, 1)], [(.27, .44), (.27, 0)]]),\n    '0': (.50, [_arc(.25, .50, .23, .50, 0, 360, 26)]),\n    '1': (.34, [[(.06, .78), (.22, 1), (.22, 0)]]),\n    '2': (.50, [[(0, .80), (.06, .94), (.20, 1), (.34, .96), (.44, .82), (.38, .64),\n                 (.04, .08), (0, .02), (.46, .02)]]),\n    '4': (.56, [[(.40, 0), (.40, 1), (.02, .28), (.56, .28)]]),\n    '5': (.48, [[(.44, 1), (.09, 1), (.07, .62), (.24, .66), (.40, .52), (.42, .30),\n                 (.30, .10), (.12, .06), (0, .14)]]),\n    '8': (.50, [_arc(.25, .76, .21, .24, 0, 360, 18), _arc(.25, .26, .23, .26, 0, 360, 20)]),\n    '=': (.44, [[(0, .38), (.42, .38)], [(0, .66), (.42, .66)]]),\n    '/': (.46, [[(.04, 0), (.40, 1)]]),\n    '+': (.44, [[(0, .50), (.42, .50)], [(.21, .29), (.21, .71)]]),\n    '.': (.10, [_arc(.05, .06, .045, .05, 0, 360, 10)]),\n    '\u00b7': (.30, [[(.02, .44), (.16, .44)]]),\n    'a': (.50, [_arc(.25, .34, .24, .34, 24, 336, 18) + [(.49, .66)], [(.49, .68), (.49, 0)]]),\n    'g': (.50, [_arc(.25, .34, .24, .34, 24, 336, 18) + [(.49, .66)],\n                [(.49, .66), (.49, -.20)] + _arc(.36, -.20, .13, .12, 0, -180, 8)]),\n    'k': (.50, [[(0, 0), (0, 1)], [(.40, .56), (0, .28)], [(.13, .38), (.44, 0)]]),\n    'm': (.58, [[(0, 0), (0, .54)],\n                [(0, .54)] + _bez((0, .54), (.15, .71), (.29, .54)) + [(.29, 0)],\n                [(.29, .54)] + _bez((.29, .54), (.44, .71), (.58, .54)) + [(.58, 0)]]),\n    's': (.44, [[(.42, .62), (.34, .72), (.14, .72), (.04, .64), (.06, .52), (.18, .44),\n                 (.36, .36), (.40, .24), (.30, .14), (.08, .14), (0, .22)]]),\n    'v': (.48, [[(0, .68), (.23, 0), (.46, .68)]]),\n}\n\n\ndef _chalk_stroke(bpy, scene, points, width, material, bow=.0, seed=0., depth=1.2145):\n    \"\"\"One chalk mark, built as a flat ribbon lying on the slate.\n\n    A round bevelled curve reads as coloured wire on a blackboard: its top and\n    sides catch the key light differently. Real chalk is a matte deposit with a\n    constant surface normal, so the mark is a strip of quads and all the life\n    comes from width drift, bow and the granular pigment shader.\n    \"\"\"\n    count = len(points)\n    verts = []; faces = []\n    for index, (px, pz) in enumerate(points):\n        t = index / (count - 1) if count > 1 else 0.\n        wobble = bow * math.sin(t * math.pi * 1.35 + seed)\n        press = 1. + .16 * math.sin(t * math.pi * 2.4 + seed * 1.7)\n        press *= 1. - .30 * max(0., t - .88) / .12 - .30 * max(0., .12 - t) / .12\n        pz = pz + wobble\n        if count > 1:\n            previous = points[max(0, index - 1)]; following = points[min(count - 1, index + 1)]\n            tangent = (following[0] - previous[0], following[1] - previous[1])\n        else:\n            tangent = (1., 0.)\n        length = math.hypot(*tangent) or 1.\n        normal = (-tangent[1] / length, tangent[0] / length)\n        half = width * .5 * max(.35, press)\n        verts.append((px + normal[0] * half, 0., pz + normal[1] * half))\n        verts.append((px - normal[0] * half, 0., pz - normal[1] * half))\n    for index in range(count - 1):\n        base = index * 2\n        faces.append((base, base + 1, base + 3, base + 2))\n    mesh = bpy.data.meshes.new('Chalk mark')\n    mesh.from_pydata(verts, [], faces); mesh.update()\n    mesh.materials.append(material)\n    obj = bpy.data.objects.new('Chalk mark', mesh)\n    obj.location.y = depth\n    scene.collection.objects.link(obj)\n    return obj\n\n\ndef _chalk_text(bpy, scene, text, x, z, cap, materials, seed=1, slant=.07, drift=.012,\n                jitter=.020, tracking=.17, width=.092, halo=None, halo_scale=2.1):\n    \"\"\"Hand-lettered line: per-glyph drift, rotation, weight and shear.\"\"\"\n    rng = random.Random(seed)\n    pen = 0.\n    for character in text:\n        if character == ' ':\n            pen += cap * .30\n            continue\n        advance, strokes = _GLYPHS[character]\n        offset_x = rng.uniform(-jitter, jitter) * cap\n        offset_z = rng.uniform(-jitter, jitter) * cap * .7\n        rotate = math.radians(rng.uniform(-2.4, 2.4))\n        scale = rng.uniform(.94, 1.05)\n        weight = cap * width * rng.uniform(.90, 1.12)\n        material = materials[rng.randrange(len(materials))]\n        centre_x, centre_z = advance * .5, .40\n        cos_r, sin_r = math.cos(rotate), math.sin(rotate)\n        for stroke in strokes:\n            points = []\n            for u, v in stroke:\n                du = (u - centre_x) * scale; dv = (v - centre_z) * scale\n                ru = du * cos_r - dv * sin_r + centre_x\n                rv = du * sin_r + dv * cos_r + centre_z\n                ru += offset_x / cap + slant * rv\n                rv += offset_z / cap\n                point_x = x + pen + ru * cap\n                points.append((point_x, z + rv * cap + drift * (point_x - x)))\n            if halo is not None:\n                _chalk_stroke(bpy, scene, points, weight * halo_scale, halo,\n                              bow=cap * .014, seed=rng.random() * 6., depth=1.2171)\n            _chalk_stroke(bpy, scene, points, weight, material, bow=cap * .014, seed=rng.random() * 6.)\n        pen += (advance + tracking) * cap\n    return x + pen\n\n\ndef _chalk_rule(bpy, scene, x0, x1, z, material, cap, seed=2):\n    points = []\n    for index in range(13):\n        t = index / 12\n        points.append((x0 + (x1 - x0) * t, z + cap * .05 * math.sin(t * math.pi)))\n    return _chalk_stroke(bpy, scene, points, cap * .034, material, bow=cap * .01, seed=seed)\n\n\n# -------------------------------------------------------------------- set\n\n\ndef build_room(bpy, data):\n    \"\"\"Build the lab, the block and the bob.\n\n    Returns ``(objects, rig)``: ``objects`` maps the simulation's body ids to the\n    empties the renderer keyframes, ``rig`` carries the thread that has to be\n    aimed at the bob every frame and the pivot it hangs from.\n    \"\"\"\n    from mathutils import Vector\n    scene = bpy.context.scene\n\n    def mat(name, color, **kw):\n        return _material(bpy, name, color, **kw)\n\n    bench = _bench_top(bpy, 'Dark lino bench top', (.043, .050, .047), rough=.44)\n    frame_wood = _wood(bpy, 'Beech bench frame', (.46, .30, .145), (.22, .125, .052))\n    pine = _wood(bpy, 'Pine block', (.500, .340, .165), (.275, .175, .078),\n                 scale=(1.1, 6., 18.), rough=.54, coat=.10)\n    wall = mat('Pale mineral plaster', (.610, .585, .520), rough=.80,\n               bump=.045, bump_scale=210., bump_distance=.00035)\n    floor = mat('Grey terrazzo', (.255, .245, .222), rough=.55, bump=.05,\n                bump_scale=140., speckle=64., speckle_color=(.125, .120, .112))\n    steel = mat('Brushed steel', (.520, .530, .545), rough=.26, metallic=1.,\n                bump=.012, bump_scale=320., bump_distance=.00006)\n    chrome = mat('Polished chrome', (.640, .650, .665), rough=.13, metallic=1.)\n    cast_iron = mat('Cast iron stand foot', (.052, .055, .058), rough=.52, metallic=.55,\n                    bump=.10, bump_scale=180., bump_distance=.0003)\n    # Satin, not mirror: at 48 mm across, a mirror finish gives one blown white\n    # blob where the key light lands and no readable roundness anywhere else.\n    steel_ball = mat('Satin steel bob', (.470, .480, .505), rough=.30, metallic=1.,\n                     bump=.006, bump_scale=460., bump_distance=.00004)\n    brass = mat('Tarnished brass', (.400, .285, .115), rough=.40, metallic=1.,\n                bump=.03, bump_scale=260., bump_distance=.00012)\n    # A medium grey, not black: the thread spends most of the clip in front of\n    # the slate board (dark) and the last third in front of the bench (light),\n    # and a mid tone is the only value that separates from both at 1 px wide.\n    thread = mat('Pendulum thread', (.360, .345, .320), rough=.82)\n    paper = mat('Worksheet paper', (.545, .520, .450), rough=.78,\n                bump=.02, bump_scale=520., bump_distance=.00008)\n    enamel = mat('Enamel tray', (.245, .300, .275), rough=.42, coat=.20)\n    watch_case = mat('Black watch case', (.030, .031, .034), rough=.34, coat=.20)\n    black_ink = mat('Printed ink', (.035, .036, .040), rough=.62)\n    white_face = mat('Stopwatch dial', (.860, .855, .820), rough=.36, coat=.25)\n    def cube(name, loc, size, material, parent=None, bevel=.003, rotation=None):\n        obj = bpy.data.objects.new(name, _cube_mesh(bpy, name, size))\n        scene.collection.objects.link(obj); obj.location = loc; obj.data.materials.append(material)\n        if bevel:\n            modifier = obj.modifiers.new('Soft manufactured edges', 'BEVEL')\n            modifier.width = bevel; modifier.segments = 5\n            obj.modifiers.new('Weighted normals', 'WEIGHTED_NORMAL')\n        if rotation is not None:\n            obj.rotation_euler = rotation\n        if parent:\n            obj.parent = parent\n        return obj\n\n    def rod(name, start, end, radius, material, segments=32):\n        \"\"\"Cylinder spanning two points; used for the stand, arm and thread.\"\"\"\n        begin = Vector(start); finish = Vector(end); direction = finish - begin\n        obj = bpy.data.objects.new(name, _tube_mesh(bpy, name, radius, direction.length, segments))\n        scene.collection.objects.link(obj); obj.data.materials.append(material)\n        obj.location = (begin + finish) / 2\n        obj.rotation_mode = 'QUATERNION'\n        obj.rotation_quaternion = direction.to_track_quat('Z', 'Y')\n        for polygon in obj.data.polygons:\n            polygon.use_smooth = True\n        return obj\n\n    def text(name, string, loc, size, material, parent=None, rotation=(math.pi / 2, 0, 0)):\n        curve = bpy.data.curves.new(name, 'FONT'); curve.body = string; curve.size = size\n        curve.align_x = 'CENTER'; curve.extrude = .0001\n        obj = bpy.data.objects.new(name, curve); scene.collection.objects.link(obj)\n        obj.location = loc; obj.rotation_euler = rotation\n        curve.materials.append(material)\n        if parent:\n            obj.parent = parent\n        return obj\n\n    # --- room shell -----------------------------------------------------\n    cube('Lab floor', (0, 0, -.06), (8, 5, .12), floor)\n    cube('Plaster wall', (0, 1.35, 1.5), (8, .12, 3), wall)\n    # A low upstand where the bench meets the wall: every school lab bench has\n    # one, and it gives the slate board a shadow line to sit on.\n    cube('Bench upstand', (-.15, 1.272, .782), (2.44, .026, .044), frame_wood, bevel=.003)\n\n    # --- bench ----------------------------------------------------------\n    # The top slab's upper face is exactly TABLE_Z: it is the surface the\n    # collision slab uses, so the block never floats or sinks on screen.\n    cube('Bench top', (0, 0, BENCH_TOP - BENCH_SIZE[2] / 2), BENCH_SIZE, bench, bevel=.004)\n    cube('Bench apron', (0, 0, BENCH_TOP - BENCH_SIZE[2] - .035), (2.5, .92, .07), frame_wood, bevel=.004)\n    for x in (-1.12, 1.12):\n        for y in (-.36, .36):\n            cube('Square bench leg', (x, y, (BENCH_TOP - .11) / 2), (.055, .055, BENCH_TOP - .11), frame_wood)\n    for y in (-.36, .36):\n        cube('Bench stretcher', (0, y, .10), (2.20, .035, .055), frame_wood, bevel=.002)\n\n    # --- local blackboard asset (without the pinned note) ---------------\n    _place_blackboard_asset(bpy)\n\n    # --- retort stand ---------------------------------------------------\n    cube('Retort stand foot', (STAND[0], STAND[1], BENCH_TOP + .008), (.26, .16, .016),\n         cast_iron, bevel=.006)\n    for dx, dy in ((-.085, -.055), (.085, -.055), (-.085, .055), (.085, .055)):\n        rod('Foot pad', (STAND[0] + dx, STAND[1] + dy, BENCH_TOP),\n            (STAND[0] + dx, STAND[1] + dy, BENCH_TOP + .004), .012, _material(\n                bpy, 'Rubber foot', (.030, .030, .032), rough=.92))\n    rod('Retort rod', (STAND[0], STAND[1], BENCH_TOP + .012),\n        (STAND[0], STAND[1], STAND_TOP), .0085, chrome)\n    cube('Boss head', (STAND[0], STAND[1], PIVOT[2]), (.040, .032, .046), cast_iron, bevel=.005)\n    rod('Boss screw', (STAND[0] + .023, STAND[1], PIVOT[2]),\n        (STAND[0] + .043, STAND[1], PIVOT[2]), .0075, brass, segments=12)\n    # Cross-arm: from the boss head to the pivot, so the drawn thread starts\n    # exactly where the solver's point constraint is anchored.\n    rod('Cross arm', (STAND[0], STAND[1], PIVOT[2]), PIVOT, .0045, chrome)\n    cube('Arm clamp', (PIVOT[0], PIVOT[1], PIVOT[2]), (.026, .026, .024), cast_iron, bevel=.003)\n\n    # --- bench dressing (kept clear of the block's lane) ----------------\n    # The weights tray sits beside the retort stand, where a lab keeps it, not\n    # on the left half of the bench: that half is the slider's runway now, and\n    # anything standing there turns into a pale shape the block has to slide\n    # through.\n    tray_x, tray_y = .26, .285\n    cube('Weights tray', (tray_x, tray_y, BENCH_TOP + .012), (.24, .15, .024), enamel, bevel=.005)\n    for index, (dx, dy) in enumerate(((-.07, -.035), (0, -.035), (.07, -.035),\n                                      (-.035, .035), (.035, .035))):\n        rod(f'Hooked weight {index}', (tray_x + dx, tray_y + dy, BENCH_TOP + .024),\n            (tray_x + dx, tray_y + dy, BENCH_TOP + .078), .0165, brass)\n        rod(f'Weight hook {index}', (tray_x + dx, tray_y + dy, BENCH_TOP + .078),\n            (tray_x + dx, tray_y + dy, BENCH_TOP + .094), .0035, steel, segments=8)\n    _place_pen_asset(bpy)\n    rod('Metre rule', (.60, -.17, BENCH_TOP + .006), (.60, .17, BENCH_TOP + .006), .011, frame_wood)\n    for index in range(20):\n        cube('Ruler tick', (.60, -.15 + index * .016, BENCH_TOP + .0135),\n             (.028 if index % 5 == 0 else .015, .0012, .0006), black_ink, bevel=0)\n    # Stopwatch: body, dial, bezel and crown, lying face up on the bench.\n    rod('Stopwatch case', (.16, -.175, BENCH_TOP + .006), (.16, -.175, BENCH_TOP + .018), .034, watch_case)\n    rod('Stopwatch dial', (.16, -.175, BENCH_TOP + .0185), (.16, -.175, BENCH_TOP + .0195), .029, white_face)\n    rod('Stopwatch crown', (.16, -.175, BENCH_TOP + .024), (.16, -.175, BENCH_TOP + .035), .006, watch_case, 12)\n    for index in range(12):\n        angle = index * math.pi / 6\n        cube('Stopwatch tick', (.16 + .024 * math.sin(angle), -.175 + .024 * math.cos(angle),\n                                BENCH_TOP + .0202), (.0018, .0045, .0004), black_ink,\n             bevel=0, rotation=(0, 0, -angle))\n    # --- the two rigid bodies -------------------------------------------\n    objects = {}\n    box_root = bpy.data.objects.new('box', None); scene.collection.objects.link(box_root)\n    objects['box'] = box_root\n    width, depth, height = BOX_SIZE\n    cube('Pine block', (0, 0, 0), (width, depth, height), pine, box_root, bevel=.0025)\n    cube('Block end grain', (-width / 2 + .0002, 0, 0), (.0004, depth * .98, height * .96),\n         frame_wood, box_root, bevel=0)\n    # A specimen tag, not a shipping label: the slider is 12 cm long, so the\n    # sticker is 4 cm wide and sits low on the face where a lab would chalk it.\n    cube('Block label', (0, -depth / 2 - .0004, -.010), (width * .30, .0005, height * .20),\n         paper, box_root, bevel=.0003)\n    text('Label lettering', 'WOOD  B', (0, -depth / 2 - .0007, -.010), .0085, black_ink, box_root)\n\n    bob_root = bpy.data.objects.new('bob', None); scene.collection.objects.link(bob_root)\n    objects['bob'] = bob_root\n    ball = bpy.data.objects.new('Steel bob', _sphere_mesh(bpy, 'Steel bob', BOB_RADIUS))\n    scene.collection.objects.link(ball); ball.parent = bob_root; ball.data.materials.append(steel_ball)\n\n    # The thread and its eyelet live in the rod's frame, not the ball's: a real\n    # bob turns freely on a swivel, so the eyelet must not whirl with the spin\n    # the contact friction gives the ball.\n    thread_obj = rod('Pendulum thread', PIVOT, (0, 0, PIVOT[2] - PENDULUM_LENGTH), .0007,\n                     thread, segments=8)\n    eyelet = bpy.data.objects.new('Eyelet', _tube_mesh(bpy, 'Eyelet', .0055, .012, 10))\n    scene.collection.objects.link(eyelet); eyelet.data.materials.append(steel)\n    eyelet.parent = thread_obj; eyelet.location = (0, 0, PENDULUM_LENGTH / 2 - BOB_RADIUS - .001)\n    return objects, dict(thread=thread_obj, pivot=Vector(PIVOT), thread_length=PENDULUM_LENGTH)\n\n\ndef configure_lighting(bpy, scene):\n    \"\"\"Cool window key from the front left, warm fill, and a wash on the board.\"\"\"\n    from mathutils import Vector\n    world = bpy.data.worlds.new('Lab ambient'); world.use_nodes = True\n    background = world.node_tree.nodes['Background']\n    background.inputs['Color'].default_value = (.145, .155, .170, 1.)\n    background.inputs['Strength'].default_value = 1.0\n    scene.world = world\n    rig = [('Window key', (-1.35, -1.80, 2.95), 155., 2.4, (1., .962, .905), (-.10, 0., .92)),\n           ('Soft fill', (1.90, -1.20, 2.10), 34., 2.2, (.94, .965, 1.), (.10, 0., .92)),\n           ('Board wash', (-.30, .60, 2.10), 26., 2.2, (1., .99, .962), (-.20, 1.25, 1.20)),\n           ('Bench kick', (.55, -1.10, 1.05), 12., 1.2, (.98, .97, .95), (-.05, 0., .86))]\n    for name, location, power, size, color, target in rig:\n        bpy.ops.object.light_add(type='AREA', location=location)\n        lamp = bpy.context.object; lamp.name = f'{name} light'\n        lamp.data.energy = power; lamp.data.shape = 'DISK'; lamp.data.size = size\n        lamp.data.color = color\n        lamp.rotation_euler = (Vector(target) - lamp.location).to_track_quat('-Z', 'Y').to_euler()\n", "scene_support.pendulum_box_collision.scene_geometry": "\"\"\"Metric dimensions shared by the collision shapes and the visible meshes.\n\nEvery number here is read by both ``simulate_pendulum_box_collision.py`` and\n``scene_environment.py``, so the block the solver moves and the block on screen\ncannot drift apart, and the thread in the picture is guaranteed to be the same\nlength as the rod constraint.\n\nThe block is a lab slider, not a crate: 12 x 7 x 8.5 cm of pine, the size of the\nblock that sits next to a dynamics track in a school lab. It is deliberately\nlong and shallow rather than cubic -- a tall block would have to be hit high on\nits face and would read as a box again.\n\nHeight is nonetheless load bearing. The bob rises as it swings and the block may\narrive at any point of the bob's first half period, so the top of the block has\nto stay above the bob's centre for the whole swing: with a 0.36 m thread and a\n26.5 degree maximum amplitude the bob's centre rises 37.8 mm above its lowest\npoint, which is why the block is 85 mm tall and not 60.\n\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\n\n# Bench top, matching the other bench-top scenes in this repo.\nTABLE_Z = .76\nBENCH_SIZE = (2.6, 1.0, .08)\n\n# 12 x 7 x 8.5 cm, 0.45 kg at about 630 kg/m^3 -- dry pine.\nBOX_SIZE = (.12, .07, .085)\n\n# The slider starts well outside the camera frame. Its whole approach is the\n# point: the block has to be far enough away that the pendulum finishes half a\n# period before anything touches it (about 0.605 s), and at 1.3 m/s with bench\n# friction that is 0.70 m of travel. The arithmetic is spelled out here so the\n# start position is not a magic constant.\nCONTACT_X = -(.020 + BOX_SIZE[0] / 2)      # block centre when its face meets the bob\nAPPROACH_DISTANCE = .701                   # 1.3 m/s for 0.605 s at 0.47 m/s^2 of friction\nBOX_START_X = CONTACT_X - APPROACH_DISTANCE\n\n# Bob: a 48 mm steel ball on a 360 mm thread -- a lab pendulum bob, not a\n# wrecking ball. Mass and size are deliberately independent: the mass is an\n# editable parameter, and a hollow demonstration ball is exactly the case where\n# the two come apart. 48 mm is about the largest ball that still reads as a\n# pendulum bob rather than a weight.\nBOB_RADIUS = .024\n# Gap between the bottom of the hung bob and the bench top.\nBOB_CLEARANCE = .010\nBOB_CENTER_Z = TABLE_Z + BOB_CLEARANCE + BOB_RADIUS\nPENDULUM_LENGTH = .36\nPIVOT = (0., 0., BOB_CENTER_Z + PENDULUM_LENGTH)\n\n\ndef box_center():\n    \"\"\"Resting centre of the block, the pose frame 1 must show.\"\"\"\n    return [BOX_START_X, 0., TABLE_Z + BOX_SIZE[2] / 2]\n\n\ndef moving_objects(physics):\n    \"\"\"Per-body metadata shared by the cache, the GT export and the renderer.\"\"\"\n    return {\n        'box': dict(size=list(BOX_SIZE), mass=physics['box_mass'],\n                    initial_location=box_center(), initial_yaw=0.),\n        'bob': dict(radius=BOB_RADIUS, mass=physics['bob_mass'],\n                    pivot=list(PIVOT), pendulum_length=PENDULUM_LENGTH,\n                    lowest_center=[0., 0., BOB_CENTER_Z]),\n    }\n", "scene_support.pendulum_box_collision": "\"\"\"Shared support modules for pendulum_box_collision.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\n", "cache_contract": "\"\"\"Reject trajectories made with different geometry, dynamics or timing.\n\nThe cache is the only thing the renderer and the suite re-use across runs, so\nit has to be able to prove it belongs to the current code. The signature covers\nthe simulator implementation, the geometry module, this file, the four physics\nparameters and the sampling clock; the object metadata is compared field by\nfield as a second line of defence.\n\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nimport hashlib, json\nfrom pathlib import Path\nfrom scene_support.pendulum_box_collision.scene_geometry import (\n    BOB_CENTER_Z, BOB_RADIUS, BOX_SIZE, BOX_START_X, PENDULUM_LENGTH, PIVOT,\n    TABLE_Z, moving_objects)\n\ndef _scene_directory():\n    scripts_root = _PCVE_ROOT / 'clean_scripts'\n    for candidate in (scripts_root / \"rigid_rigid\" / \"pendulum_box_collision\", scripts_root / \"pendulum_box_collision\"):\n        if candidate.is_dir():\n            return candidate\n    raise FileNotFoundError(\"Scene directory not found for pendulum_box_collision\")\n\n\nCACHE_SCHEMA_VERSION = 3\n\n\ndef geometry_metadata():\n    return dict(box_size=list(BOX_SIZE), box_start_x=BOX_START_X, table_z=TABLE_Z,\n                bob_radius=BOB_RADIUS, pendulum_length=PENDULUM_LENGTH,\n                pivot=list(PIVOT), bob_center_z=BOB_CENTER_Z)\n\n\ndef simulation_signature(scenario):\n    import hashlib, json\n    scene_dir = _PCVE_SCENE_ROOT\n    common_dir = _PCVE_ROOT / \"clean_scripts\"\n    files = list(scene_dir.glob(\"*.py\")) + list(common_dir.glob(\"*.py\"))\n    implementation = {str(path.relative_to(_PCVE_ROOT)): hashlib.sha256(path.read_bytes()).hexdigest()\n                      for path in files if path.is_file()}\n    payload = dict(implementation=implementation, scenario=scenario)\n    return hashlib.sha256(json.dumps(payload, sort_keys=True, allow_nan=False, default=str).encode()).hexdigest()\ndef validate_cache(data, scenario=None):\n    error = 'Incompatible physics cache: geometry, dynamics or timing changed; resimulate first.'\n    if data.get('scene') != 'pendulum_box_collision' or data.get('schema_version') != CACHE_SCHEMA_VERSION:\n        raise ValueError(error)\n    requested = scenario if scenario is not None else data['scenario']\n    if data.get('simulation_signature') != simulation_signature(requested):\n        raise ValueError(error)\n    if data.get('geometry') != geometry_metadata() or data.get('objects') != moving_objects(requested['physics']):\n        raise ValueError(error)\n    r = requested['render']; count = round(r['fps'] * r['slow_motion'] * r['duration_sec'])\n    if (data.get('playback_fps') != r['fps'] or data.get('slow_motion') != r['slow_motion']\n            or data.get('physical_duration_sec') != r['duration_sec'] or data.get('frame_end') != count\n            or len(data.get('frames', [])) != count or data['scenario']['physics'] != requested['physics']):\n        raise ValueError(error)\n    if not data.get('quality', {}).get('valid'):\n        raise ValueError('Invalid physics cache')\n", "render_quality": "\"\"\"The same engine/device interface used by the other scene renderers.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\n\nimport sys\nfrom pathlib import Path\nsys.path.insert(0, str(_PCVE_ROOT / 'clean_scripts'))\nfrom pcve_blender_compat import (shader_socket, set_shader_input, eevee_engine, set_eevee_property, set_color_property)\ndef configure_renderer(bpy, scene, args):\n    scene.render.engine = 'CYCLES' if args.engine == 'cycles' else eevee_engine()\n    scene.render.threads_mode = 'FIXED'; scene.render.threads = 4\n    if args.engine == 'cycles':\n        scene.cycles.samples = args.samples; scene.cycles.use_denoising = True\n        scene.cycles.use_adaptive_sampling = True; scene.cycles.adaptive_threshold = .005\n        scene.cycles.adaptive_min_samples = min(32, args.samples)\n        scene.cycles.max_bounces = 8; scene.cycles.diffuse_bounces = 4; scene.cycles.glossy_bounces = 4\n        scene.render.use_persistent_data = True; scene.cycles.device = 'CPU'\n        if args.device == 'auto':\n            try:\n                prefs = bpy.context.preferences.addons['cycles'].preferences\n                prefs.compute_device_type = 'CUDA'; prefs.get_devices()\n                available = [d for d in prefs.devices if d.type == 'CUDA']\n                for d in prefs.devices:\n                    d.use = d.type == 'CUDA'\n                if available:\n                    scene.cycles.device = 'GPU'\n            except Exception:\n                scene.cycles.device = 'CPU'\n        return scene.cycles.device\n    return 'GPU'\n\n\ndef configure_color(scene):\n    set_color_property(scene.view_settings, 'view_transform', 'AgX')\n    set_color_property(scene.view_settings, 'look', 'AgX - Medium High Contrast')\n    scene.view_settings.exposure = -.10\n", "runtime_support": "\"\"\"Local runtime discovery; scripts also work in ordinary Python/Blender installs.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nimport os, sys\nfrom pathlib import Path\n\nROOT = _PCVE_ROOT\n_dll_handles = []\nif os.name == 'nt':\n    directory = Path(sys.prefix) / 'Library/bin'\n    if directory.exists():\n        _dll_handles.append(os.add_dll_directory(str(directory)))\n\n\ndef python_for(role):\n    sys.path.insert(0, str(ROOT/'clean_scripts'))\n    from pcve_scene_runtime import python_for as resolve_python\n    return resolve_python(role)\n", "scene_config": "\"\"\"Scenario contract for the pendulum-and-box impact scene.\n\nOne definition of the four editable physics parameters, the sampling window and\nthe camera, imported by the simulator, the renderer, the suite builder and the\nbatch sampler. Nothing outside this file decides what an edit may change.\n\nWorld conventions\n-----------------\n* **+X** runs along the bench from the wooden box towards the pendulum. The box\n  starts at negative X and travels towards +X; the bob hangs at ``x = 0``.\n* **+Y** points from the camera into the wall, so the camera sits at negative Y.\n* **+Z** is up. The bench top is ``z = 0.76`` and gravity acts along -Z.\n* SI units everywhere: metres, kilograms, seconds, radians in the cache.\n\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nfrom copy import deepcopy\nimport json, math\n\nSCENE_NAME = 'pendulum_box_collision'\n\n# The four knobs the scene was built to expose. Bob mass and bob speed are the\n# pendulum's two; box mass and box speed are the slider's two. Everything else\n# -- restitution, friction, pendulum length, box size, release geometry -- is\n# fixed so that an edit changes one thing and nothing else.\nBASELINE_PHYSICS = dict(bob_mass=.40, bob_speed=.55, box_mass=.40, box_speed=1.30)\n\n# Legal ranges, enforced before every simulation.\n#\n# ``bob_speed`` is bounded from above by the block, not by the solver: the bob\n# starts at the lowest point and rises ``v^2/2g``, so the swing amplitude grows\n# with the square of this number. At 0.90 m/s the bob peaks 26.5 degrees up the\n# arc and its centre is still 17 mm below the top of the 85 mm slider, which is\n# what keeps a whole-face impact possible at any phase. Above roughly 0.97 m/s\n# the bob would meet the block's top edge instead of its face.\n#\n# ``box_speed`` is bounded from below by the approach: the slider has 0.70 m of\n# bench to cover before it reaches the bob, and the initial approach window is 1.05 s, so a\n# block below about 1.10 m/s would miss the original approach window.\n# Keep these staging limits unchanged when extending the aftermath.\nPHYSICS_LIMITS = dict(bob_mass=(.05, 5.0), bob_speed=(0.0, .90),\n                      box_mass=(.05, 5.0), box_speed=(1.12, 3.5))\n\n# Show the return collision and subsequent motion at real-time playback.\nDEFAULT_DURATION_SEC = 4.0\nTOTAL_FRAMES = 96\n\n\ndef defaults():\n    return dict(schema_version=1, scene=SCENE_NAME,\n        physics=deepcopy(BASELINE_PHYSICS),\n        render=dict(fps=24, duration_sec=DEFAULT_DURATION_SEC, slow_motion=1,\n                    resolution=[1280, 720], samples=128),\n        camera=dict(location=[.68, -2.28, 1.20], target=[-.02, .03, .925],\n                    ortho_scale=1.06))\n\n\ndef merge(base, overrides):\n    result = deepcopy(base)\n    for key, value in overrides.items():\n        result[key] = (merge(result[key], value)\n                       if isinstance(value, dict) and isinstance(result.get(key), dict)\n                       else deepcopy(value))\n    return result\n\n\ndef validate(s):\n    if set(s) - {'schema_version', 'scene', 'physics', 'render', 'camera', 'seed'} or s.get('scene') != SCENE_NAME:\n        raise ValueError('Invalid scenario fields or scene name')\n    c = s['physics']; r = s['render']\n    if set(c) != set(BASELINE_PHYSICS):\n        raise ValueError('Unknown or missing physics parameter')\n    for key, value in c.items():\n        if key == 'timed_edits':\n            if not isinstance(value, list) or any(\n                    not isinstance(entry, dict) or set(entry) != {'frame', 'params'}\n                    or type(entry['frame']) is not int\n                    or not isinstance(entry['params'], dict) or not entry['params']\n                    or any(not isinstance(v, (int, float)) or not math.isfinite(v)\n                           for v in entry['params'].values())\n                    for entry in value):\n                raise ValueError('Invalid timed_edits schedule')\n            continue\n        if not isinstance(value, (int, float)) or not math.isfinite(value):\n            raise ValueError(f'Invalid {key}')\n        low, high = PHYSICS_LIMITS[key]\n        if not low <= value <= high:\n            raise ValueError(f'{key} must be between {low} and {high}')\n    if not isinstance(r['fps'], int) or r['fps'] <= 0 or not math.isfinite(r['duration_sec']) or r['duration_sec'] <= 0:\n        raise ValueError('Invalid timing')\n    if r['slow_motion'] not in (1, 2, 4, 8):\n        raise ValueError('slow_motion must be 1, 2, 4 or 8')\n    if r['fps'] * r['slow_motion'] > 2400:\n        raise ValueError('Sample rate exceeds physics rate')\n    if round(r['fps'] * r['slow_motion'] * r['duration_sec']) < 1:\n        raise ValueError('Empty trajectory')\n    if (not isinstance(r['samples'], int) or r['samples'] < 1 or len(r['resolution']) != 2\n            or any(not isinstance(v, int) or v < 2 or v % 2 for v in r['resolution'])):\n        raise ValueError('Invalid render settings; use even resolution')\n    camera = s['camera']\n    for key in ('location', 'target'):\n        if len(camera[key]) != 3 or not all(math.isfinite(v) for v in camera[key]):\n            raise ValueError('Invalid camera vector')\n    if camera['location'] == camera['target'] or not math.isfinite(camera['ortho_scale']) or camera['ortho_scale'] <= 0:\n        raise ValueError('Invalid camera')\n\n\ndef load_scenario(args):\n    s = merge(defaults(), json.loads(args.scenario_json.read_text(encoding='utf-8'))) if args.scenario_json else defaults()\n    if args.scenario_overrides_json:\n        s = merge(s, json.loads(args.scenario_overrides_json.read_text(encoding='utf-8')))\n    for key in BASELINE_PHYSICS:\n        if getattr(args, key, None) is not None:\n            s['physics'][key] = getattr(args, key)\n    for key in ('fps', 'duration_sec', 'slow_motion', 'resolution', 'samples'):\n        if getattr(args, key, None) is not None:\n            s['render'][key] = getattr(args, key)\n    validate(s)\n    return s\n", "scene_environment": "\"\"\"Procedural middle-school physics lab and the two visible rigid bodies.\n\nOnly geometry and appearance live here. Nothing in this module knows about\nphysics parameters, so a mass or speed edit changes the clip without touching\na single material, and the collision shapes in ``simulate_pendulum_box_collision.py``\nstay the authority on size and contact.\n\nThe set is built the way the other bench-top scenes build theirs: every prop is\nprocedural except for the local textured blackboard and pen assets; the bench top is exactly ``TABLE_Z`` so the\nblock visibly rests on the surface the solver uses, and the retort stand's rod\nends at ``scene_geometry.PIVOT`` so the drawn thread leaves from the point the\nconstraint hangs from.\n\nLayout, seen from the default camera at -Y\n------------------------------------------\n* the block starts left of centre and slides right;\n* the bob hangs at x = 0, just above the bench, and swings in the X-Z plane;\n* the retort stand stands to the right, its cross-arm reaching left to the\n  pivot, so neither the rod nor its base is ever in the block's path;\n* the slate board, splashback and shelf stay behind y = 1.2, out of reach.\n\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\n\nimport sys\nfrom pathlib import Path\nsys.path.insert(0, str(_PCVE_ROOT / 'clean_scripts'))\nfrom pcve_blender_compat import (shader_socket, set_shader_input, eevee_engine, set_eevee_property, set_color_property)\nimport math, random\nfrom pathlib import Path\nfrom scene_support.pendulum_box_collision.scene_geometry import (\n    BENCH_SIZE, BOB_RADIUS, BOX_SIZE, PENDULUM_LENGTH, PIVOT, TABLE_Z)\n\nENVIRONMENT_THEME = 'school_physics_lab_pendulum_bench'\nAPPEARANCE_VERSION = 4\n\n# The visible bench top must be the same surface the solver drops the block on.\nBENCH_TOP = TABLE_Z\nSTAND = (0.40, 0.12)          # foot of the retort stand, on the bench\nSTAND_TOP = PIVOT[2] + .055\n\n\n# --------------------------------------------------------------- materials\n\n\ndef _material(bpy, name, color, rough=.62, metallic=0., coat=0., bump=0., bump_scale=14.,\n              grain=None, speckle=None, speckle_color=None, bump_distance=.00025):\n    \"\"\"Principled surface with optional procedural relief, wood grain or aggregate.\"\"\"\n    material = bpy.data.materials.new(name)\n    material.diffuse_color = (*color, 1.); material.use_nodes = True\n    nodes = material.node_tree.nodes; links = material.node_tree.links\n    bsdf = nodes['Principled BSDF']\n    bsdf.inputs['Base Color'].default_value = (*color, 1.)\n    bsdf.inputs['Roughness'].default_value = rough\n    if metallic:\n        bsdf.inputs['Metallic'].default_value = metallic\n    if coat:\n        set_shader_input(bsdf, 'Coat Weight', coat)\n        set_shader_input(bsdf, 'Coat Roughness', 0.24)\n    if not (bump > 0. or speckle):\n        return material\n    vector = nodes.new('ShaderNodeTexCoord').outputs['Object']\n    if grain:\n        mapping = nodes.new('ShaderNodeMapping'); mapping.inputs['Scale'].default_value = grain\n        links.new(mapping.inputs['Vector'], vector); vector = mapping.outputs['Vector']\n    if bump > 0.:\n        noise = nodes.new('ShaderNodeTexNoise')\n        noise.inputs['Scale'].default_value = bump_scale\n        noise.inputs['Detail'].default_value = 3.\n        noise.inputs['Roughness'].default_value = .52\n        links.new(noise.inputs['Vector'], vector)\n        relief = nodes.new('ShaderNodeBump')\n        relief.inputs['Strength'].default_value = bump\n        relief.inputs['Distance'].default_value = bump_distance\n        links.new(relief.inputs['Height'], noise.outputs['Fac'])\n        links.new(bsdf.inputs['Normal'], relief.outputs['Normal'])\n    if speckle:\n        aggregate = nodes.new('ShaderNodeTexVoronoi'); aggregate.inputs['Scale'].default_value = speckle\n        links.new(aggregate.inputs['Vector'], vector)\n        ramp = nodes.new('ShaderNodeValToRGB')\n        ramp.color_ramp.elements[0].position = .36; ramp.color_ramp.elements[0].color = (*color, 1.)\n        ramp.color_ramp.elements[1].position = .68\n        ramp.color_ramp.elements[1].color = (*(speckle_color or tuple(c * .55 for c in color)), 1.)\n        links.new(ramp.inputs['Fac'], aggregate.outputs['Distance'])\n        links.new(bsdf.inputs['Base Color'], ramp.outputs['Color'])\n    return material\n\n\ndef _wood(bpy, name, light, dark, scale=(1.6, 9., 22.), rough=.44, coat=.12):\n    \"\"\"Two-tone grain: a stretched noise drives a colour ramp, plus fine relief.\n\n    A single flat brown cube reads as plastic at this distance. Wood needs the\n    value to wander along the length of the board, which is what the very\n    anisotropic mapping scale does: fine across the grain, long along it.\n    \"\"\"\n    material = bpy.data.materials.new(name); material.use_nodes = True\n    nodes = material.node_tree.nodes; links = material.node_tree.links\n    bsdf = nodes['Principled BSDF']\n    bsdf.inputs['Roughness'].default_value = rough\n    set_shader_input(bsdf, 'Coat Weight', coat)\n    set_shader_input(bsdf, 'Coat Roughness', 0.22)\n    coord = nodes.new('ShaderNodeTexCoord')\n    mapping = nodes.new('ShaderNodeMapping'); mapping.inputs['Scale'].default_value = scale\n    links.new(mapping.inputs['Vector'], coord.outputs['Object'])\n    grain = nodes.new('ShaderNodeTexNoise')\n    grain.inputs['Scale'].default_value = 5.2\n    grain.inputs['Detail'].default_value = 5.\n    grain.inputs['Roughness'].default_value = .55\n    links.new(grain.inputs['Vector'], mapping.outputs['Vector'])\n    ramp = nodes.new('ShaderNodeValToRGB')\n    ramp.color_ramp.elements[0].position = .30; ramp.color_ramp.elements[0].color = (*dark, 1.)\n    ramp.color_ramp.elements[1].position = .70; ramp.color_ramp.elements[1].color = (*light, 1.)\n    links.new(ramp.inputs['Fac'], grain.outputs['Fac'])\n    links.new(bsdf.inputs['Base Color'], ramp.outputs['Color'])\n    pores = nodes.new('ShaderNodeTexNoise')\n    pores.inputs['Scale'].default_value = 240.\n    pores.inputs['Detail'].default_value = 3.\n    links.new(pores.inputs['Vector'], mapping.outputs['Vector'])\n    relief = nodes.new('ShaderNodeBump')\n    relief.inputs['Strength'].default_value = .12\n    relief.inputs['Distance'].default_value = .00018\n    links.new(relief.inputs['Height'], pores.outputs['Fac'])\n    links.new(bsdf.inputs['Normal'], relief.outputs['Normal'])\n    return material\n\n\ndef _bench_top(bpy, name, color, rough=.46):\n    \"\"\"Dark lino bench top: tonal drift, long scuffs and a wide soft sheen.\"\"\"\n    material = bpy.data.materials.new(name); material.use_nodes = True\n    nodes = material.node_tree.nodes; links = material.node_tree.links\n    bsdf = nodes['Principled BSDF']\n    bsdf.inputs['Roughness'].default_value = rough\n    set_shader_input(bsdf, 'Coat Weight', 0.12)\n    set_shader_input(bsdf, 'Coat Roughness', 0.34)\n    coord = nodes.new('ShaderNodeTexCoord')\n    drift = nodes.new('ShaderNodeTexNoise')\n    drift.inputs['Scale'].default_value = 1.5\n    drift.inputs['Detail'].default_value = 4.\n    drift.inputs['Roughness'].default_value = .62\n    links.new(drift.inputs['Vector'], coord.outputs['Object'])\n    tone = nodes.new('ShaderNodeValToRGB')\n    tone.color_ramp.elements[0].position = .26\n    tone.color_ramp.elements[0].color = (*(c * .78 for c in color), 1.)\n    tone.color_ramp.elements[1].position = .78\n    tone.color_ramp.elements[1].color = (*(min(1., c * 1.26) for c in color), 1.)\n    links.new(tone.inputs['Fac'], drift.outputs['Fac'])\n    links.new(bsdf.inputs['Base Color'], tone.outputs['Color'])\n    scuff_coord = nodes.new('ShaderNodeMapping')\n    scuff_coord.inputs['Scale'].default_value = (2.6, 8., 3.)\n    links.new(scuff_coord.inputs['Vector'], coord.outputs['Object'])\n    scuff = nodes.new('ShaderNodeTexNoise')\n    scuff.inputs['Scale'].default_value = 4.0\n    scuff.inputs['Detail'].default_value = 2.\n    links.new(scuff.inputs['Vector'], scuff_coord.outputs['Vector'])\n    mask = nodes.new('ShaderNodeValToRGB')\n    mask.color_ramp.elements[0].position = .64; mask.color_ramp.elements[0].color = (0., 0., 0., 1.)\n    mask.color_ramp.elements[1].position = .77; mask.color_ramp.elements[1].color = (1., 1., 1., 1.)\n    links.new(mask.inputs['Fac'], scuff.outputs['Fac'])\n    wear = nodes.new('ShaderNodeMixRGB'); wear.inputs['Fac'].default_value = 1.\n    links.new(wear.inputs['Fac'], mask.outputs['Color'])\n    links.new(wear.inputs['Color1'], tone.outputs['Color'])\n    wear.inputs['Color2'].default_value = (*(c * .70 for c in color), 1.)\n    links.new(bsdf.inputs['Base Color'], wear.outputs['Color'])\n    gloss = nodes.new('ShaderNodeMixRGB'); gloss.blend_type = 'MIX'\n    links.new(gloss.inputs['Fac'], mask.outputs['Color'])\n    gloss.inputs['Color1'].default_value = (rough, rough, rough, 1.)\n    gloss.inputs['Color2'].default_value = (.64, .64, .64, 1.)\n    links.new(bsdf.inputs['Roughness'], gloss.outputs['Color'])\n    relief = nodes.new('ShaderNodeBump')\n    relief.inputs['Strength'].default_value = .05\n    relief.inputs['Distance'].default_value = .00012\n    links.new(relief.inputs['Height'], mask.outputs['Color'])\n    links.new(bsdf.inputs['Normal'], relief.outputs['Normal'])\n    return material\n\n\ndef _place_blackboard_asset(bpy):\n    \"\"\"Use the board's original mesh, UVs and PBR maps; omit its pinned note.\"\"\"\n    from mathutils import Matrix, Vector\n    asset = _PCVE_ROOT / 'assets' / 'models' / 'realistic_blackboard.glb'\n    before = set(bpy.data.objects)\n    bpy.ops.import_scene.gltf(filepath=str(asset))\n    imported = set(bpy.data.objects) - before\n    bpy.context.view_layer.update()\n    meshes = [obj for obj in imported if obj.type == 'MESH']\n    if not meshes:\n        raise ValueError(f'Blackboard asset contains no mesh: {asset}')\n    def bounds(obj):\n        points = [obj.matrix_world @ Vector(corner) for corner in obj.bound_box]\n        return (Vector(tuple(min(v[i] for v in points) for i in range(3))),\n                Vector(tuple(max(v[i] for v in points) for i in range(3))))\n    source = max(meshes, key=lambda obj: (bounds(obj)[1] - bounds(obj)[0]).length)\n    low, high = bounds(source)\n    centre = (low + high) / 2\n    scale = .74 / (high.z - low.z)\n    mesh = source.data.copy()\n    mesh.transform(source.matrix_world)\n    board = bpy.data.objects.new('Real blackboard (realistic_blackboard.glb)', mesh)\n    bpy.context.scene.collection.objects.link(board)\n    board.matrix_world = (Matrix.Translation((-.20, 1.24, 1.085))\n                          @ Matrix.Scale(scale, 4) @ Matrix.Translation(-centre))\n    board['asset_path'] = 'assets/models/realistic_blackboard.glb'\n    for obj in imported:\n        bpy.data.objects.remove(obj, do_unlink=True)\n    return board\n\n\ndef _place_pen_asset(bpy):\n    \"\"\"Keep the GLB's UVs/materials and seat its actual bounds on the bench.\"\"\"\n    from mathutils import Matrix, Vector\n    asset = _PCVE_ROOT / 'assets' / 'models' / 'the_pen.glb'\n    before = set(bpy.data.objects)\n    bpy.ops.import_scene.gltf(filepath=str(asset))\n    imported = set(bpy.data.objects) - before\n    bpy.context.view_layer.update()\n    points = [obj.matrix_world @ Vector(corner) for obj in imported\n              if obj.type == 'MESH' for corner in obj.bound_box]\n    if not points:\n        raise ValueError(f'Pen asset contains no mesh: {asset}')\n    low = Vector(tuple(min(v[i] for v in points) for i in range(3)))\n    high = Vector(tuple(max(v[i] for v in points) for i in range(3)))\n    scale = .145 / (high.x - low.x)\n    centre = (low + high) / 2\n    root = bpy.data.objects.new('Desk pen (the_pen.glb)', None)\n    bpy.context.scene.collection.objects.link(root)\n    for obj in imported:\n        if obj.parent not in imported:\n            obj.parent = root\n    root.matrix_world = (Matrix.Translation((-.30, -.235, BENCH_TOP + .00015))\n                         @ Matrix.Rotation(.32, 4, 'Z') @ Matrix.Scale(scale, 4)\n                         @ Matrix.Translation((-centre.x, -centre.y, -low.z)))\n    root['asset_path'] = 'assets/models/the_pen.glb'\n    root['length_m'] = .145\n    return root\n\n\ndef _alpha_material(bpy, name, color, rough):\n    \"\"\"Translucent surface helper; Cycles needs no blend mode, EEVEE does.\"\"\"\n    material = bpy.data.materials.new(name); material.use_nodes = True\n    bsdf = material.node_tree.nodes['Principled BSDF']\n    bsdf.inputs['Base Color'].default_value = (*color, 1.)\n    bsdf.inputs['Roughness'].default_value = rough\n    for attribute, value in (('surface_render_method', 'DITHERED'), ('blend_method', 'BLEND')):\n        try:\n            setattr(material, attribute, value)\n        except Exception:\n            pass\n    return material\n\n\ndef _alpha_surface(material, bsdf, alpha_socket):\n    \"\"\"Mix with a Transparent BSDF instead of using Principled's Alpha.\n\n    Feeding Alpha leaves the surface blocking shadow rays, which turns a film of\n    pigment into a black rectangle on whatever is behind it.\n    \"\"\"\n    nodes = material.node_tree.nodes; links = material.node_tree.links\n    output = [node for node in nodes if node.type == 'OUTPUT_MATERIAL'][0]\n    for link in list(output.inputs['Surface'].links):\n        links.remove(link)\n    clear = nodes.new('ShaderNodeBsdfTransparent')\n    mix = nodes.new('ShaderNodeMixShader')\n    links.new(mix.inputs[0], alpha_socket)\n    links.new(mix.inputs[1], clear.outputs[0])\n    links.new(mix.inputs[2], bsdf.outputs[0])\n    links.new(output.inputs['Surface'], mix.outputs[0])\n    return mix\n\n\ndef _chalk_material(bpy, name, color, dust=.42, value_spread=.22, bump=.30):\n    \"\"\"Pigment that skips and fades like pressed chalk instead of flat paint.\"\"\"\n    material = _alpha_material(bpy, name, color, .94)\n    nodes = material.node_tree.nodes; links = material.node_tree.links\n    bsdf = nodes['Principled BSDF']\n    set_shader_input(bsdf, 'Specular IOR Level', 0.02)\n    coord = nodes.new('ShaderNodeTexCoord')\n    coverage = nodes.new('ShaderNodeTexNoise')\n    coverage.inputs['Scale'].default_value = 64.\n    coverage.inputs['Detail'].default_value = 3.\n    coverage.inputs['Roughness'].default_value = .58\n    links.new(coverage.inputs['Vector'], coord.outputs['Object'])\n    ramp = nodes.new('ShaderNodeValToRGB')\n    ramp.color_ramp.elements[0].position = .36; ramp.color_ramp.elements[0].color = (0., 0., 0., 1.)\n    ramp.color_ramp.elements[1].position = .64; ramp.color_ramp.elements[1].color = (1., 1., 1., 1.)\n    links.new(ramp.inputs['Fac'], coverage.outputs['Fac'])\n    coarse = nodes.new('ShaderNodeMath'); coarse.operation = 'MULTIPLY_ADD'\n    coarse.inputs[1].default_value = 1. - dust; coarse.inputs[2].default_value = dust\n    links.new(coarse.inputs[0], ramp.outputs['Color'])\n    grain = nodes.new('ShaderNodeTexNoise')\n    grain.inputs['Scale'].default_value = 520.\n    grain.inputs['Detail'].default_value = 4.\n    grain.inputs['Roughness'].default_value = .5\n    links.new(grain.inputs['Vector'], coord.outputs['Object'])\n    speckle = nodes.new('ShaderNodeValToRGB')\n    speckle.color_ramp.elements[0].position = .28; speckle.color_ramp.elements[0].color = (0., 0., 0., 1.)\n    speckle.color_ramp.elements[1].position = .58; speckle.color_ramp.elements[1].color = (1., 1., 1., 1.)\n    links.new(speckle.inputs['Fac'], grain.outputs['Fac'])\n    lift = nodes.new('ShaderNodeMath'); lift.operation = 'MULTIPLY_ADD'\n    lift.inputs[1].default_value = .55; lift.inputs[2].default_value = .45\n    links.new(lift.inputs[0], speckle.outputs['Color'])\n    alpha = nodes.new('ShaderNodeMath'); alpha.operation = 'MULTIPLY'\n    links.new(alpha.inputs[0], coarse.outputs['Value']); links.new(alpha.inputs[1], lift.outputs['Value'])\n    _alpha_surface(material, bsdf, alpha.outputs['Value'])\n    tone = nodes.new('ShaderNodeMixRGB'); tone.blend_type = 'MIX'\n    tone.inputs['Color1'].default_value = (*color, 1.)\n    tone.inputs['Color2'].default_value = (*(c * (1. - value_spread) for c in color), 1.)\n    links.new(tone.inputs['Fac'], coverage.outputs['Fac'])\n    links.new(bsdf.inputs['Base Color'], tone.outputs['Color'])\n    if bump > 0.:\n        relief = nodes.new('ShaderNodeBump')\n        relief.inputs['Strength'].default_value = bump\n        relief.inputs['Distance'].default_value = .00008\n        links.new(relief.inputs['Height'], grain.outputs['Fac'])\n        links.new(bsdf.inputs['Normal'], relief.outputs['Normal'])\n    return material\n\n\ndef _chalk_halo_material(bpy, name, color, strength=.13):\n    \"\"\"Loose powder hugging a mark: wide, ragged and almost transparent.\"\"\"\n    material = _alpha_material(bpy, name, color, .96)\n    nodes = material.node_tree.nodes; links = material.node_tree.links\n    bsdf = nodes['Principled BSDF']\n    set_shader_input(bsdf, 'Specular IOR Level', 0.02)\n    coord = nodes.new('ShaderNodeTexCoord')\n    noise = nodes.new('ShaderNodeTexNoise')\n    noise.inputs['Scale'].default_value = 110.\n    noise.inputs['Detail'].default_value = 4.\n    noise.inputs['Roughness'].default_value = .62\n    links.new(noise.inputs['Vector'], coord.outputs['Object'])\n    ramp = nodes.new('ShaderNodeValToRGB')\n    ramp.color_ramp.elements[0].position = .30; ramp.color_ramp.elements[0].color = (0., 0., 0., 1.)\n    ramp.color_ramp.elements[1].position = .62; ramp.color_ramp.elements[1].color = (1., 1., 1., 1.)\n    links.new(ramp.inputs['Fac'], noise.outputs['Fac'])\n    level = nodes.new('ShaderNodeMath'); level.operation = 'MULTIPLY'\n    level.inputs[1].default_value = strength\n    links.new(level.inputs[0], ramp.outputs['Color'])\n    _alpha_surface(material, bsdf, level.outputs['Value'])\n    return material\n\n\ndef _residue_material(bpy, name, color):\n    \"\"\"Ghost of erased writing: horizontal wipes plus uneven haze.\"\"\"\n    material = _alpha_material(bpy, name, color, .96)\n    nodes = material.node_tree.nodes; links = material.node_tree.links\n    bsdf = nodes['Principled BSDF']\n    coord = nodes.new('ShaderNodeTexCoord')\n    wipe_coord = nodes.new('ShaderNodeMapping')\n    wipe_coord.inputs['Scale'].default_value = (2.2, 1., 17.)\n    links.new(wipe_coord.inputs['Vector'], coord.outputs['Object'])\n    wipe = nodes.new('ShaderNodeTexNoise')\n    wipe.inputs['Scale'].default_value = 4.5\n    wipe.inputs['Detail'].default_value = 3.\n    wipe.inputs['Roughness'].default_value = .6\n    links.new(wipe.inputs['Vector'], wipe_coord.outputs['Vector'])\n    streak = nodes.new('ShaderNodeValToRGB')\n    streak.color_ramp.elements[0].position = .44; streak.color_ramp.elements[0].color = (0., 0., 0., 1.)\n    streak.color_ramp.elements[1].position = .78; streak.color_ramp.elements[1].color = (1., 1., 1., 1.)\n    links.new(streak.inputs['Fac'], wipe.outputs['Fac'])\n    haze = nodes.new('ShaderNodeTexNoise')\n    haze.inputs['Scale'].default_value = 1.6\n    haze.inputs['Detail'].default_value = 4.\n    links.new(haze.inputs['Vector'], coord.outputs['Object'])\n    veil = nodes.new('ShaderNodeValToRGB')\n    veil.color_ramp.elements[0].position = .40; veil.color_ramp.elements[0].color = (.1, .1, .1, 1.)\n    veil.color_ramp.elements[1].position = .72; veil.color_ramp.elements[1].color = (.55, .55, .55, 1.)\n    links.new(veil.inputs['Fac'], haze.outputs['Fac'])\n    mix = nodes.new('ShaderNodeMath'); mix.operation = 'MULTIPLY'\n    links.new(mix.inputs[0], streak.outputs['Color']); links.new(mix.inputs[1], veil.outputs['Color'])\n    strength = nodes.new('ShaderNodeMath'); strength.operation = 'MULTIPLY'\n    strength.inputs[1].default_value = .085\n    links.new(strength.inputs[0], mix.outputs['Value'])\n    _alpha_surface(material, bsdf, strength.outputs['Value'])\n    return material\n\n\n# ------------------------------------------------------------------- meshes\n\n\ndef _cube_mesh(bpy, name, size):\n    \"\"\"A real-world-sized cube mesh, so Object texture coordinates stay isotropic.\"\"\"\n    x, y, z = (value * .5 for value in size)\n    mesh = bpy.data.meshes.new(name)\n    mesh.from_pydata([(-x, -y, -z), (x, -y, -z), (x, y, -z), (-x, y, -z),\n                      (-x, -y, z), (x, -y, z), (x, y, z), (-x, y, z)], [],\n                     [(0, 3, 2, 1), (4, 5, 6, 7), (0, 1, 5, 4),\n                      (1, 2, 6, 5), (2, 3, 7, 6), (3, 0, 4, 7)])\n    mesh.update()\n    return mesh\n\n\ndef _tube_mesh(bpy, name, radius, length, segments=48):\n    import bmesh\n    mesh = bpy.data.meshes.new(name); bm = bmesh.new()\n    bmesh.ops.create_cone(bm, cap_ends=True, cap_tris=False, segments=segments,\n                          radius1=radius, radius2=radius, depth=length)\n    bm.to_mesh(mesh); bm.free(); mesh.update()\n    return mesh\n\n\ndef _cone_mesh(bpy, name, radius1, radius2, length, segments=48):\n    import bmesh\n    mesh = bpy.data.meshes.new(name); bm = bmesh.new()\n    bmesh.ops.create_cone(bm, cap_ends=True, cap_tris=False, segments=segments,\n                          radius1=radius1, radius2=radius2, depth=length)\n    bm.to_mesh(mesh); bm.free(); mesh.update()\n    return mesh\n\n\ndef _sphere_mesh(bpy, name, radius, segments=64, rings=40):\n    import bmesh\n    mesh = bpy.data.meshes.new(name); bm = bmesh.new()\n    bmesh.ops.create_uvsphere(bm, u_segments=segments, v_segments=rings, radius=radius)\n    bm.to_mesh(mesh); bm.free(); mesh.update()\n    for polygon in mesh.polygons:\n        polygon.use_smooth = True\n    return mesh\n\n\n# ---------------------------------------------------------- hand-written chalk\n# Each glyph is a set of monoline strokes on a 0..1 cap-height grid. Stroke\n# geometry and pigment are what make the board read as chalk rather than as a\n# font: see ``_chalk_stroke``.\ndef _arc(cx, cy, rx, ry, a0, a1, steps=14):\n    return [(cx + rx * math.cos(math.radians(a0 + (a1 - a0) * i / steps)),\n             cy + ry * math.sin(math.radians(a0 + (a1 - a0) * i / steps)))\n            for i in range(steps + 1)]\n\n\ndef _bez(p0, p1, p2, steps=10):\n    return [((1 - t) ** 2 * p0[0] + 2 * (1 - t) * t * p1[0] + t * t * p2[0],\n             (1 - t) ** 2 * p0[1] + 2 * (1 - t) * t * p1[1] + t * t * p2[1])\n            for t in (i / steps for i in range(steps + 1))]\n\n\n_GLYPHS = {\n    'A': (.62, [[(0, 0), (.31, 1), (.62, 0)], [(.13, .34), (.49, .34)]]),\n    'B': (.54, [[(0, 0), (0, 1)],\n                [(0, 1), (.22, 1)] + _arc(.24, .78, .24, .22, 90, -90) + [(0, .56)],\n                [(0, .56), (.26, .56)] + _arc(.28, .28, .26, .28, 90, -90) + [(0, 0)]]),\n    'C': (.56, [_arc(.30, .50, .28, .50, 56, 304, 20)]),\n    'D': (.56, [[(0, 0), (0, 1)], [(0, 1), (.20, 1)] + _arc(.22, .50, .32, .50, 90, -90, 20) + [(0, 0)]]),\n    'E': (.50, [[(0, 0), (0, 1)], [(0, 1), (.47, 1)], [(0, .55), (.38, .55)], [(0, 0), (.47, 0)]]),\n    'F': (.48, [[(0, 0), (0, 1)], [(0, 1), (.45, 1)], [(0, .56), (.36, .56)]]),\n    'H': (.54, [[(0, 0), (0, 1)], [(.52, 0), (.52, 1)], [(0, .52), (.52, .52)]]),\n    'I': (.11, [[(.05, 0), (.05, 1)]]),\n    'K': (.52, [[(0, 0), (0, 1)], [(.44, .58), (0, .26)], [(.14, .36), (.46, 0)]]),\n    'L': (.48, [[(0, 1), (0, 0), (.45, 0)]]),\n    'M': (.68, [[(0, 0), (0, 1), (.34, .40), (.68, 1), (.68, 0)]]),\n    'N': (.54, [[(0, 0), (0, 1), (.52, 0), (.52, 1)]]),\n    'O': (.58, [_arc(.29, .50, .28, .50, 0, 360, 28)]),\n    'P': (.48, [[(0, 0), (0, 1)], [(0, 1), (.22, 1)] + _arc(.23, .76, .22, .24, 90, -90) + [(0, .52)]]),\n    'S': (.50, [[(.48, .86), (.40, 1), (.16, 1), (.04, .88), (.03, .74), (.12, .60),\n                 (.36, .53), (.46, .40), (.46, .16), (.34, 0), (.10, 0), (0, .14)]]),\n    'T': (.52, [[(0, 1), (.52, 1)], [(.26, 1), (.26, 0)]]),\n    'U': (.52, [[(0, 1), (0, .16)] + _arc(.26, .16, .26, .16, 180, 360, 16) + [(.52, 1)]]),\n    'V': (.52, [[(0, 1), (.26, 0), (.52, 1)]]),\n    'Y': (.56, [[(0, 1), (.27, .44), (.54, 1)], [(.27, .44), (.27, 0)]]),\n    '0': (.50, [_arc(.25, .50, .23, .50, 0, 360, 26)]),\n    '1': (.34, [[(.06, .78), (.22, 1), (.22, 0)]]),\n    '2': (.50, [[(0, .80), (.06, .94), (.20, 1), (.34, .96), (.44, .82), (.38, .64),\n                 (.04, .08), (0, .02), (.46, .02)]]),\n    '4': (.56, [[(.40, 0), (.40, 1), (.02, .28), (.56, .28)]]),\n    '5': (.48, [[(.44, 1), (.09, 1), (.07, .62), (.24, .66), (.40, .52), (.42, .30),\n                 (.30, .10), (.12, .06), (0, .14)]]),\n    '8': (.50, [_arc(.25, .76, .21, .24, 0, 360, 18), _arc(.25, .26, .23, .26, 0, 360, 20)]),\n    '=': (.44, [[(0, .38), (.42, .38)], [(0, .66), (.42, .66)]]),\n    '/': (.46, [[(.04, 0), (.40, 1)]]),\n    '+': (.44, [[(0, .50), (.42, .50)], [(.21, .29), (.21, .71)]]),\n    '.': (.10, [_arc(.05, .06, .045, .05, 0, 360, 10)]),\n    '\u00b7': (.30, [[(.02, .44), (.16, .44)]]),\n    'a': (.50, [_arc(.25, .34, .24, .34, 24, 336, 18) + [(.49, .66)], [(.49, .68), (.49, 0)]]),\n    'g': (.50, [_arc(.25, .34, .24, .34, 24, 336, 18) + [(.49, .66)],\n                [(.49, .66), (.49, -.20)] + _arc(.36, -.20, .13, .12, 0, -180, 8)]),\n    'k': (.50, [[(0, 0), (0, 1)], [(.40, .56), (0, .28)], [(.13, .38), (.44, 0)]]),\n    'm': (.58, [[(0, 0), (0, .54)],\n                [(0, .54)] + _bez((0, .54), (.15, .71), (.29, .54)) + [(.29, 0)],\n                [(.29, .54)] + _bez((.29, .54), (.44, .71), (.58, .54)) + [(.58, 0)]]),\n    's': (.44, [[(.42, .62), (.34, .72), (.14, .72), (.04, .64), (.06, .52), (.18, .44),\n                 (.36, .36), (.40, .24), (.30, .14), (.08, .14), (0, .22)]]),\n    'v': (.48, [[(0, .68), (.23, 0), (.46, .68)]]),\n}\n\n\ndef _chalk_stroke(bpy, scene, points, width, material, bow=.0, seed=0., depth=1.2145):\n    \"\"\"One chalk mark, built as a flat ribbon lying on the slate.\n\n    A round bevelled curve reads as coloured wire on a blackboard: its top and\n    sides catch the key light differently. Real chalk is a matte deposit with a\n    constant surface normal, so the mark is a strip of quads and all the life\n    comes from width drift, bow and the granular pigment shader.\n    \"\"\"\n    count = len(points)\n    verts = []; faces = []\n    for index, (px, pz) in enumerate(points):\n        t = index / (count - 1) if count > 1 else 0.\n        wobble = bow * math.sin(t * math.pi * 1.35 + seed)\n        press = 1. + .16 * math.sin(t * math.pi * 2.4 + seed * 1.7)\n        press *= 1. - .30 * max(0., t - .88) / .12 - .30 * max(0., .12 - t) / .12\n        pz = pz + wobble\n        if count > 1:\n            previous = points[max(0, index - 1)]; following = points[min(count - 1, index + 1)]\n            tangent = (following[0] - previous[0], following[1] - previous[1])\n        else:\n            tangent = (1., 0.)\n        length = math.hypot(*tangent) or 1.\n        normal = (-tangent[1] / length, tangent[0] / length)\n        half = width * .5 * max(.35, press)\n        verts.append((px + normal[0] * half, 0., pz + normal[1] * half))\n        verts.append((px - normal[0] * half, 0., pz - normal[1] * half))\n    for index in range(count - 1):\n        base = index * 2\n        faces.append((base, base + 1, base + 3, base + 2))\n    mesh = bpy.data.meshes.new('Chalk mark')\n    mesh.from_pydata(verts, [], faces); mesh.update()\n    mesh.materials.append(material)\n    obj = bpy.data.objects.new('Chalk mark', mesh)\n    obj.location.y = depth\n    scene.collection.objects.link(obj)\n    return obj\n\n\ndef _chalk_text(bpy, scene, text, x, z, cap, materials, seed=1, slant=.07, drift=.012,\n                jitter=.020, tracking=.17, width=.092, halo=None, halo_scale=2.1):\n    \"\"\"Hand-lettered line: per-glyph drift, rotation, weight and shear.\"\"\"\n    rng = random.Random(seed)\n    pen = 0.\n    for character in text:\n        if character == ' ':\n            pen += cap * .30\n            continue\n        advance, strokes = _GLYPHS[character]\n        offset_x = rng.uniform(-jitter, jitter) * cap\n        offset_z = rng.uniform(-jitter, jitter) * cap * .7\n        rotate = math.radians(rng.uniform(-2.4, 2.4))\n        scale = rng.uniform(.94, 1.05)\n        weight = cap * width * rng.uniform(.90, 1.12)\n        material = materials[rng.randrange(len(materials))]\n        centre_x, centre_z = advance * .5, .40\n        cos_r, sin_r = math.cos(rotate), math.sin(rotate)\n        for stroke in strokes:\n            points = []\n            for u, v in stroke:\n                du = (u - centre_x) * scale; dv = (v - centre_z) * scale\n                ru = du * cos_r - dv * sin_r + centre_x\n                rv = du * sin_r + dv * cos_r + centre_z\n                ru += offset_x / cap + slant * rv\n                rv += offset_z / cap\n                point_x = x + pen + ru * cap\n                points.append((point_x, z + rv * cap + drift * (point_x - x)))\n            if halo is not None:\n                _chalk_stroke(bpy, scene, points, weight * halo_scale, halo,\n                              bow=cap * .014, seed=rng.random() * 6., depth=1.2171)\n            _chalk_stroke(bpy, scene, points, weight, material, bow=cap * .014, seed=rng.random() * 6.)\n        pen += (advance + tracking) * cap\n    return x + pen\n\n\ndef _chalk_rule(bpy, scene, x0, x1, z, material, cap, seed=2):\n    points = []\n    for index in range(13):\n        t = index / 12\n        points.append((x0 + (x1 - x0) * t, z + cap * .05 * math.sin(t * math.pi)))\n    return _chalk_stroke(bpy, scene, points, cap * .034, material, bow=cap * .01, seed=seed)\n\n\n# -------------------------------------------------------------------- set\n\n\ndef build_room(bpy, data):\n    \"\"\"Build the lab, the block and the bob.\n\n    Returns ``(objects, rig)``: ``objects`` maps the simulation's body ids to the\n    empties the renderer keyframes, ``rig`` carries the thread that has to be\n    aimed at the bob every frame and the pivot it hangs from.\n    \"\"\"\n    from mathutils import Vector\n    scene = bpy.context.scene\n\n    def mat(name, color, **kw):\n        return _material(bpy, name, color, **kw)\n\n    bench = _bench_top(bpy, 'Dark lino bench top', (.043, .050, .047), rough=.44)\n    frame_wood = _wood(bpy, 'Beech bench frame', (.46, .30, .145), (.22, .125, .052))\n    pine = _wood(bpy, 'Pine block', (.500, .340, .165), (.275, .175, .078),\n                 scale=(1.1, 6., 18.), rough=.54, coat=.10)\n    wall = mat('Pale mineral plaster', (.610, .585, .520), rough=.80,\n               bump=.045, bump_scale=210., bump_distance=.00035)\n    floor = mat('Grey terrazzo', (.255, .245, .222), rough=.55, bump=.05,\n                bump_scale=140., speckle=64., speckle_color=(.125, .120, .112))\n    steel = mat('Brushed steel', (.520, .530, .545), rough=.26, metallic=1.,\n                bump=.012, bump_scale=320., bump_distance=.00006)\n    chrome = mat('Polished chrome', (.640, .650, .665), rough=.13, metallic=1.)\n    cast_iron = mat('Cast iron stand foot', (.052, .055, .058), rough=.52, metallic=.55,\n                    bump=.10, bump_scale=180., bump_distance=.0003)\n    # Satin, not mirror: at 48 mm across, a mirror finish gives one blown white\n    # blob where the key light lands and no readable roundness anywhere else.\n    steel_ball = mat('Satin steel bob', (.470, .480, .505), rough=.30, metallic=1.,\n                     bump=.006, bump_scale=460., bump_distance=.00004)\n    brass = mat('Tarnished brass', (.400, .285, .115), rough=.40, metallic=1.,\n                bump=.03, bump_scale=260., bump_distance=.00012)\n    # A medium grey, not black: the thread spends most of the clip in front of\n    # the slate board (dark) and the last third in front of the bench (light),\n    # and a mid tone is the only value that separates from both at 1 px wide.\n    thread = mat('Pendulum thread', (.360, .345, .320), rough=.82)\n    paper = mat('Worksheet paper', (.545, .520, .450), rough=.78,\n                bump=.02, bump_scale=520., bump_distance=.00008)\n    enamel = mat('Enamel tray', (.245, .300, .275), rough=.42, coat=.20)\n    watch_case = mat('Black watch case', (.030, .031, .034), rough=.34, coat=.20)\n    black_ink = mat('Printed ink', (.035, .036, .040), rough=.62)\n    white_face = mat('Stopwatch dial', (.860, .855, .820), rough=.36, coat=.25)\n    def cube(name, loc, size, material, parent=None, bevel=.003, rotation=None):\n        obj = bpy.data.objects.new(name, _cube_mesh(bpy, name, size))\n        scene.collection.objects.link(obj); obj.location = loc; obj.data.materials.append(material)\n        if bevel:\n            modifier = obj.modifiers.new('Soft manufactured edges', 'BEVEL')\n            modifier.width = bevel; modifier.segments = 5\n            obj.modifiers.new('Weighted normals', 'WEIGHTED_NORMAL')\n        if rotation is not None:\n            obj.rotation_euler = rotation\n        if parent:\n            obj.parent = parent\n        return obj\n\n    def rod(name, start, end, radius, material, segments=32):\n        \"\"\"Cylinder spanning two points; used for the stand, arm and thread.\"\"\"\n        begin = Vector(start); finish = Vector(end); direction = finish - begin\n        obj = bpy.data.objects.new(name, _tube_mesh(bpy, name, radius, direction.length, segments))\n        scene.collection.objects.link(obj); obj.data.materials.append(material)\n        obj.location = (begin + finish) / 2\n        obj.rotation_mode = 'QUATERNION'\n        obj.rotation_quaternion = direction.to_track_quat('Z', 'Y')\n        for polygon in obj.data.polygons:\n            polygon.use_smooth = True\n        return obj\n\n    def text(name, string, loc, size, material, parent=None, rotation=(math.pi / 2, 0, 0)):\n        curve = bpy.data.curves.new(name, 'FONT'); curve.body = string; curve.size = size\n        curve.align_x = 'CENTER'; curve.extrude = .0001\n        obj = bpy.data.objects.new(name, curve); scene.collection.objects.link(obj)\n        obj.location = loc; obj.rotation_euler = rotation\n        curve.materials.append(material)\n        if parent:\n            obj.parent = parent\n        return obj\n\n    # --- room shell -----------------------------------------------------\n    cube('Lab floor', (0, 0, -.06), (8, 5, .12), floor)\n    cube('Plaster wall', (0, 1.35, 1.5), (8, .12, 3), wall)\n    # A low upstand where the bench meets the wall: every school lab bench has\n    # one, and it gives the slate board a shadow line to sit on.\n    cube('Bench upstand', (-.15, 1.272, .782), (2.44, .026, .044), frame_wood, bevel=.003)\n\n    # --- bench ----------------------------------------------------------\n    # The top slab's upper face is exactly TABLE_Z: it is the surface the\n    # collision slab uses, so the block never floats or sinks on screen.\n    cube('Bench top', (0, 0, BENCH_TOP - BENCH_SIZE[2] / 2), BENCH_SIZE, bench, bevel=.004)\n    cube('Bench apron', (0, 0, BENCH_TOP - BENCH_SIZE[2] - .035), (2.5, .92, .07), frame_wood, bevel=.004)\n    for x in (-1.12, 1.12):\n        for y in (-.36, .36):\n            cube('Square bench leg', (x, y, (BENCH_TOP - .11) / 2), (.055, .055, BENCH_TOP - .11), frame_wood)\n    for y in (-.36, .36):\n        cube('Bench stretcher', (0, y, .10), (2.20, .035, .055), frame_wood, bevel=.002)\n\n    # --- local blackboard asset (without the pinned note) ---------------\n    _place_blackboard_asset(bpy)\n\n    # --- retort stand ---------------------------------------------------\n    cube('Retort stand foot', (STAND[0], STAND[1], BENCH_TOP + .008), (.26, .16, .016),\n         cast_iron, bevel=.006)\n    for dx, dy in ((-.085, -.055), (.085, -.055), (-.085, .055), (.085, .055)):\n        rod('Foot pad', (STAND[0] + dx, STAND[1] + dy, BENCH_TOP),\n            (STAND[0] + dx, STAND[1] + dy, BENCH_TOP + .004), .012, _material(\n                bpy, 'Rubber foot', (.030, .030, .032), rough=.92))\n    rod('Retort rod', (STAND[0], STAND[1], BENCH_TOP + .012),\n        (STAND[0], STAND[1], STAND_TOP), .0085, chrome)\n    cube('Boss head', (STAND[0], STAND[1], PIVOT[2]), (.040, .032, .046), cast_iron, bevel=.005)\n    rod('Boss screw', (STAND[0] + .023, STAND[1], PIVOT[2]),\n        (STAND[0] + .043, STAND[1], PIVOT[2]), .0075, brass, segments=12)\n    # Cross-arm: from the boss head to the pivot, so the drawn thread starts\n    # exactly where the solver's point constraint is anchored.\n    rod('Cross arm', (STAND[0], STAND[1], PIVOT[2]), PIVOT, .0045, chrome)\n    cube('Arm clamp', (PIVOT[0], PIVOT[1], PIVOT[2]), (.026, .026, .024), cast_iron, bevel=.003)\n\n    # --- bench dressing (kept clear of the block's lane) ----------------\n    # The weights tray sits beside the retort stand, where a lab keeps it, not\n    # on the left half of the bench: that half is the slider's runway now, and\n    # anything standing there turns into a pale shape the block has to slide\n    # through.\n    tray_x, tray_y = .26, .285\n    cube('Weights tray', (tray_x, tray_y, BENCH_TOP + .012), (.24, .15, .024), enamel, bevel=.005)\n    for index, (dx, dy) in enumerate(((-.07, -.035), (0, -.035), (.07, -.035),\n                                      (-.035, .035), (.035, .035))):\n        rod(f'Hooked weight {index}', (tray_x + dx, tray_y + dy, BENCH_TOP + .024),\n            (tray_x + dx, tray_y + dy, BENCH_TOP + .078), .0165, brass)\n        rod(f'Weight hook {index}', (tray_x + dx, tray_y + dy, BENCH_TOP + .078),\n            (tray_x + dx, tray_y + dy, BENCH_TOP + .094), .0035, steel, segments=8)\n    _place_pen_asset(bpy)\n    rod('Metre rule', (.60, -.17, BENCH_TOP + .006), (.60, .17, BENCH_TOP + .006), .011, frame_wood)\n    for index in range(20):\n        cube('Ruler tick', (.60, -.15 + index * .016, BENCH_TOP + .0135),\n             (.028 if index % 5 == 0 else .015, .0012, .0006), black_ink, bevel=0)\n    # Stopwatch: body, dial, bezel and crown, lying face up on the bench.\n    rod('Stopwatch case', (.16, -.175, BENCH_TOP + .006), (.16, -.175, BENCH_TOP + .018), .034, watch_case)\n    rod('Stopwatch dial', (.16, -.175, BENCH_TOP + .0185), (.16, -.175, BENCH_TOP + .0195), .029, white_face)\n    rod('Stopwatch crown', (.16, -.175, BENCH_TOP + .024), (.16, -.175, BENCH_TOP + .035), .006, watch_case, 12)\n    for index in range(12):\n        angle = index * math.pi / 6\n        cube('Stopwatch tick', (.16 + .024 * math.sin(angle), -.175 + .024 * math.cos(angle),\n                                BENCH_TOP + .0202), (.0018, .0045, .0004), black_ink,\n             bevel=0, rotation=(0, 0, -angle))\n    # --- the two rigid bodies -------------------------------------------\n    objects = {}\n    box_root = bpy.data.objects.new('box', None); scene.collection.objects.link(box_root)\n    objects['box'] = box_root\n    width, depth, height = BOX_SIZE\n    cube('Pine block', (0, 0, 0), (width, depth, height), pine, box_root, bevel=.0025)\n    cube('Block end grain', (-width / 2 + .0002, 0, 0), (.0004, depth * .98, height * .96),\n         frame_wood, box_root, bevel=0)\n    # A specimen tag, not a shipping label: the slider is 12 cm long, so the\n    # sticker is 4 cm wide and sits low on the face where a lab would chalk it.\n    cube('Block label', (0, -depth / 2 - .0004, -.010), (width * .30, .0005, height * .20),\n         paper, box_root, bevel=.0003)\n    text('Label lettering', 'WOOD  B', (0, -depth / 2 - .0007, -.010), .0085, black_ink, box_root)\n\n    bob_root = bpy.data.objects.new('bob', None); scene.collection.objects.link(bob_root)\n    objects['bob'] = bob_root\n    ball = bpy.data.objects.new('Steel bob', _sphere_mesh(bpy, 'Steel bob', BOB_RADIUS))\n    scene.collection.objects.link(ball); ball.parent = bob_root; ball.data.materials.append(steel_ball)\n\n    # The thread and its eyelet live in the rod's frame, not the ball's: a real\n    # bob turns freely on a swivel, so the eyelet must not whirl with the spin\n    # the contact friction gives the ball.\n    thread_obj = rod('Pendulum thread', PIVOT, (0, 0, PIVOT[2] - PENDULUM_LENGTH), .0007,\n                     thread, segments=8)\n    eyelet = bpy.data.objects.new('Eyelet', _tube_mesh(bpy, 'Eyelet', .0055, .012, 10))\n    scene.collection.objects.link(eyelet); eyelet.data.materials.append(steel)\n    eyelet.parent = thread_obj; eyelet.location = (0, 0, PENDULUM_LENGTH / 2 - BOB_RADIUS - .001)\n    return objects, dict(thread=thread_obj, pivot=Vector(PIVOT), thread_length=PENDULUM_LENGTH)\n\n\ndef configure_lighting(bpy, scene):\n    \"\"\"Cool window key from the front left, warm fill, and a wash on the board.\"\"\"\n    from mathutils import Vector\n    world = bpy.data.worlds.new('Lab ambient'); world.use_nodes = True\n    background = world.node_tree.nodes['Background']\n    background.inputs['Color'].default_value = (.145, .155, .170, 1.)\n    background.inputs['Strength'].default_value = 1.0\n    scene.world = world\n    rig = [('Window key', (-1.35, -1.80, 2.95), 155., 2.4, (1., .962, .905), (-.10, 0., .92)),\n           ('Soft fill', (1.90, -1.20, 2.10), 34., 2.2, (.94, .965, 1.), (.10, 0., .92)),\n           ('Board wash', (-.30, .60, 2.10), 26., 2.2, (1., .99, .962), (-.20, 1.25, 1.20)),\n           ('Bench kick', (.55, -1.10, 1.05), 12., 1.2, (.98, .97, .95), (-.05, 0., .86))]\n    for name, location, power, size, color, target in rig:\n        bpy.ops.object.light_add(type='AREA', location=location)\n        lamp = bpy.context.object; lamp.name = f'{name} light'\n        lamp.data.energy = power; lamp.data.shape = 'DISK'; lamp.data.size = size\n        lamp.data.color = color\n        lamp.rotation_euler = (Vector(target) - lamp.location).to_track_quat('-Z', 'Y').to_euler()\n", "scene_geometry": "\"\"\"Metric dimensions shared by the collision shapes and the visible meshes.\n\nEvery number here is read by both ``simulate_pendulum_box_collision.py`` and\n``scene_environment.py``, so the block the solver moves and the block on screen\ncannot drift apart, and the thread in the picture is guaranteed to be the same\nlength as the rod constraint.\n\nThe block is a lab slider, not a crate: 12 x 7 x 8.5 cm of pine, the size of the\nblock that sits next to a dynamics track in a school lab. It is deliberately\nlong and shallow rather than cubic -- a tall block would have to be hit high on\nits face and would read as a box again.\n\nHeight is nonetheless load bearing. The bob rises as it swings and the block may\narrive at any point of the bob's first half period, so the top of the block has\nto stay above the bob's centre for the whole swing: with a 0.36 m thread and a\n26.5 degree maximum amplitude the bob's centre rises 37.8 mm above its lowest\npoint, which is why the block is 85 mm tall and not 60.\n\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\n\n# Bench top, matching the other bench-top scenes in this repo.\nTABLE_Z = .76\nBENCH_SIZE = (2.6, 1.0, .08)\n\n# 12 x 7 x 8.5 cm, 0.45 kg at about 630 kg/m^3 -- dry pine.\nBOX_SIZE = (.12, .07, .085)\n\n# The slider starts well outside the camera frame. Its whole approach is the\n# point: the block has to be far enough away that the pendulum finishes half a\n# period before anything touches it (about 0.605 s), and at 1.3 m/s with bench\n# friction that is 0.70 m of travel. The arithmetic is spelled out here so the\n# start position is not a magic constant.\nCONTACT_X = -(.020 + BOX_SIZE[0] / 2)      # block centre when its face meets the bob\nAPPROACH_DISTANCE = .701                   # 1.3 m/s for 0.605 s at 0.47 m/s^2 of friction\nBOX_START_X = CONTACT_X - APPROACH_DISTANCE\n\n# Bob: a 48 mm steel ball on a 360 mm thread -- a lab pendulum bob, not a\n# wrecking ball. Mass and size are deliberately independent: the mass is an\n# editable parameter, and a hollow demonstration ball is exactly the case where\n# the two come apart. 48 mm is about the largest ball that still reads as a\n# pendulum bob rather than a weight.\nBOB_RADIUS = .024\n# Gap between the bottom of the hung bob and the bench top.\nBOB_CLEARANCE = .010\nBOB_CENTER_Z = TABLE_Z + BOB_CLEARANCE + BOB_RADIUS\nPENDULUM_LENGTH = .36\nPIVOT = (0., 0., BOB_CENTER_Z + PENDULUM_LENGTH)\n\n\ndef box_center():\n    \"\"\"Resting centre of the block, the pose frame 1 must show.\"\"\"\n    return [BOX_START_X, 0., TABLE_Z + BOX_SIZE[2] / 2]\n\n\ndef moving_objects(physics):\n    \"\"\"Per-body metadata shared by the cache, the GT export and the renderer.\"\"\"\n    return {\n        'box': dict(size=list(BOX_SIZE), mass=physics['box_mass'],\n                    initial_location=box_center(), initial_yaw=0.),\n        'bob': dict(radius=BOB_RADIUS, mass=physics['bob_mass'],\n                    pivot=list(PIVOT), pendulum_length=PENDULUM_LENGTH,\n                    lowest_center=[0., 0., BOB_CENTER_Z]),\n    }\n", "pendulum_box_collision.cache_contract": "\"\"\"Reject trajectories made with different geometry, dynamics or timing.\n\nThe cache is the only thing the renderer and the suite re-use across runs, so\nit has to be able to prove it belongs to the current code. The signature covers\nthe simulator implementation, the geometry module, this file, the four physics\nparameters and the sampling clock; the object metadata is compared field by\nfield as a second line of defence.\n\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nimport hashlib, json\nfrom pathlib import Path\nfrom scene_support.pendulum_box_collision.scene_geometry import (\n    BOB_CENTER_Z, BOB_RADIUS, BOX_SIZE, BOX_START_X, PENDULUM_LENGTH, PIVOT,\n    TABLE_Z, moving_objects)\n\ndef _scene_directory():\n    scripts_root = _PCVE_ROOT / 'clean_scripts'\n    for candidate in (scripts_root / \"rigid_rigid\" / \"pendulum_box_collision\", scripts_root / \"pendulum_box_collision\"):\n        if candidate.is_dir():\n            return candidate\n    raise FileNotFoundError(\"Scene directory not found for pendulum_box_collision\")\n\n\nCACHE_SCHEMA_VERSION = 3\n\n\ndef geometry_metadata():\n    return dict(box_size=list(BOX_SIZE), box_start_x=BOX_START_X, table_z=TABLE_Z,\n                bob_radius=BOB_RADIUS, pendulum_length=PENDULUM_LENGTH,\n                pivot=list(PIVOT), bob_center_z=BOB_CENTER_Z)\n\n\ndef simulation_signature(scenario):\n    import hashlib, json\n    scene_dir = _PCVE_SCENE_ROOT\n    common_dir = _PCVE_ROOT / \"clean_scripts\"\n    files = list(scene_dir.glob(\"*.py\")) + list(common_dir.glob(\"*.py\"))\n    implementation = {str(path.relative_to(_PCVE_ROOT)): hashlib.sha256(path.read_bytes()).hexdigest()\n                      for path in files if path.is_file()}\n    payload = dict(implementation=implementation, scenario=scenario)\n    return hashlib.sha256(json.dumps(payload, sort_keys=True, allow_nan=False, default=str).encode()).hexdigest()\ndef validate_cache(data, scenario=None):\n    error = 'Incompatible physics cache: geometry, dynamics or timing changed; resimulate first.'\n    if data.get('scene') != 'pendulum_box_collision' or data.get('schema_version') != CACHE_SCHEMA_VERSION:\n        raise ValueError(error)\n    requested = scenario if scenario is not None else data['scenario']\n    if data.get('simulation_signature') != simulation_signature(requested):\n        raise ValueError(error)\n    if data.get('geometry') != geometry_metadata() or data.get('objects') != moving_objects(requested['physics']):\n        raise ValueError(error)\n    r = requested['render']; count = round(r['fps'] * r['slow_motion'] * r['duration_sec'])\n    if (data.get('playback_fps') != r['fps'] or data.get('slow_motion') != r['slow_motion']\n            or data.get('physical_duration_sec') != r['duration_sec'] or data.get('frame_end') != count\n            or len(data.get('frames', [])) != count or data['scenario']['physics'] != requested['physics']):\n        raise ValueError(error)\n    if not data.get('quality', {}).get('valid'):\n        raise ValueError('Invalid physics cache')\n", "pendulum_box_collision.render_quality": "\"\"\"The same engine/device interface used by the other scene renderers.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\n\nimport sys\nfrom pathlib import Path\nsys.path.insert(0, str(_PCVE_ROOT / 'clean_scripts'))\nfrom pcve_blender_compat import (shader_socket, set_shader_input, eevee_engine, set_eevee_property, set_color_property)\ndef configure_renderer(bpy, scene, args):\n    scene.render.engine = 'CYCLES' if args.engine == 'cycles' else eevee_engine()\n    scene.render.threads_mode = 'FIXED'; scene.render.threads = 4\n    if args.engine == 'cycles':\n        scene.cycles.samples = args.samples; scene.cycles.use_denoising = True\n        scene.cycles.use_adaptive_sampling = True; scene.cycles.adaptive_threshold = .005\n        scene.cycles.adaptive_min_samples = min(32, args.samples)\n        scene.cycles.max_bounces = 8; scene.cycles.diffuse_bounces = 4; scene.cycles.glossy_bounces = 4\n        scene.render.use_persistent_data = True; scene.cycles.device = 'CPU'\n        if args.device == 'auto':\n            try:\n                prefs = bpy.context.preferences.addons['cycles'].preferences\n                prefs.compute_device_type = 'CUDA'; prefs.get_devices()\n                available = [d for d in prefs.devices if d.type == 'CUDA']\n                for d in prefs.devices:\n                    d.use = d.type == 'CUDA'\n                if available:\n                    scene.cycles.device = 'GPU'\n            except Exception:\n                scene.cycles.device = 'CPU'\n        return scene.cycles.device\n    return 'GPU'\n\n\ndef configure_color(scene):\n    set_color_property(scene.view_settings, 'view_transform', 'AgX')\n    set_color_property(scene.view_settings, 'look', 'AgX - Medium High Contrast')\n    scene.view_settings.exposure = -.10\n", "pendulum_box_collision.runtime_support": "\"\"\"Local runtime discovery; scripts also work in ordinary Python/Blender installs.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nimport os, sys\nfrom pathlib import Path\n\nROOT = _PCVE_ROOT\n_dll_handles = []\nif os.name == 'nt':\n    directory = Path(sys.prefix) / 'Library/bin'\n    if directory.exists():\n        _dll_handles.append(os.add_dll_directory(str(directory)))\n\n\ndef python_for(role):\n    sys.path.insert(0, str(ROOT/'clean_scripts'))\n    from pcve_scene_runtime import python_for as resolve_python\n    return resolve_python(role)\n", "pendulum_box_collision.scene_config": "\"\"\"Scenario contract for the pendulum-and-box impact scene.\n\nOne definition of the four editable physics parameters, the sampling window and\nthe camera, imported by the simulator, the renderer, the suite builder and the\nbatch sampler. Nothing outside this file decides what an edit may change.\n\nWorld conventions\n-----------------\n* **+X** runs along the bench from the wooden box towards the pendulum. The box\n  starts at negative X and travels towards +X; the bob hangs at ``x = 0``.\n* **+Y** points from the camera into the wall, so the camera sits at negative Y.\n* **+Z** is up. The bench top is ``z = 0.76`` and gravity acts along -Z.\n* SI units everywhere: metres, kilograms, seconds, radians in the cache.\n\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\nfrom copy import deepcopy\nimport json, math\n\nSCENE_NAME = 'pendulum_box_collision'\n\n# The four knobs the scene was built to expose. Bob mass and bob speed are the\n# pendulum's two; box mass and box speed are the slider's two. Everything else\n# -- restitution, friction, pendulum length, box size, release geometry -- is\n# fixed so that an edit changes one thing and nothing else.\nBASELINE_PHYSICS = dict(bob_mass=.40, bob_speed=.55, box_mass=.40, box_speed=1.30)\n\n# Legal ranges, enforced before every simulation.\n#\n# ``bob_speed`` is bounded from above by the block, not by the solver: the bob\n# starts at the lowest point and rises ``v^2/2g``, so the swing amplitude grows\n# with the square of this number. At 0.90 m/s the bob peaks 26.5 degrees up the\n# arc and its centre is still 17 mm below the top of the 85 mm slider, which is\n# what keeps a whole-face impact possible at any phase. Above roughly 0.97 m/s\n# the bob would meet the block's top edge instead of its face.\n#\n# ``box_speed`` is bounded from below by the approach: the slider has 0.70 m of\n# bench to cover before it reaches the bob, and the initial approach window is 1.05 s, so a\n# block below about 1.10 m/s would miss the original approach window.\n# Keep these staging limits unchanged when extending the aftermath.\nPHYSICS_LIMITS = dict(bob_mass=(.05, 5.0), bob_speed=(0.0, .90),\n                      box_mass=(.05, 5.0), box_speed=(1.12, 3.5))\n\n# Show the return collision and subsequent motion at real-time playback.\nDEFAULT_DURATION_SEC = 4.0\nTOTAL_FRAMES = 96\n\n\ndef defaults():\n    return dict(schema_version=1, scene=SCENE_NAME,\n        physics=deepcopy(BASELINE_PHYSICS),\n        render=dict(fps=24, duration_sec=DEFAULT_DURATION_SEC, slow_motion=1,\n                    resolution=[1280, 720], samples=128),\n        camera=dict(location=[.68, -2.28, 1.20], target=[-.02, .03, .925],\n                    ortho_scale=1.06))\n\n\ndef merge(base, overrides):\n    result = deepcopy(base)\n    for key, value in overrides.items():\n        result[key] = (merge(result[key], value)\n                       if isinstance(value, dict) and isinstance(result.get(key), dict)\n                       else deepcopy(value))\n    return result\n\n\ndef validate(s):\n    if set(s) - {'schema_version', 'scene', 'physics', 'render', 'camera', 'seed'} or s.get('scene') != SCENE_NAME:\n        raise ValueError('Invalid scenario fields or scene name')\n    c = s['physics']; r = s['render']\n    if set(c) != set(BASELINE_PHYSICS):\n        raise ValueError('Unknown or missing physics parameter')\n    for key, value in c.items():\n        if key == 'timed_edits':\n            if not isinstance(value, list) or any(\n                    not isinstance(entry, dict) or set(entry) != {'frame', 'params'}\n                    or type(entry['frame']) is not int\n                    or not isinstance(entry['params'], dict) or not entry['params']\n                    or any(not isinstance(v, (int, float)) or not math.isfinite(v)\n                           for v in entry['params'].values())\n                    for entry in value):\n                raise ValueError('Invalid timed_edits schedule')\n            continue\n        if not isinstance(value, (int, float)) or not math.isfinite(value):\n            raise ValueError(f'Invalid {key}')\n        low, high = PHYSICS_LIMITS[key]\n        if not low <= value <= high:\n            raise ValueError(f'{key} must be between {low} and {high}')\n    if not isinstance(r['fps'], int) or r['fps'] <= 0 or not math.isfinite(r['duration_sec']) or r['duration_sec'] <= 0:\n        raise ValueError('Invalid timing')\n    if r['slow_motion'] not in (1, 2, 4, 8):\n        raise ValueError('slow_motion must be 1, 2, 4 or 8')\n    if r['fps'] * r['slow_motion'] > 2400:\n        raise ValueError('Sample rate exceeds physics rate')\n    if round(r['fps'] * r['slow_motion'] * r['duration_sec']) < 1:\n        raise ValueError('Empty trajectory')\n    if (not isinstance(r['samples'], int) or r['samples'] < 1 or len(r['resolution']) != 2\n            or any(not isinstance(v, int) or v < 2 or v % 2 for v in r['resolution'])):\n        raise ValueError('Invalid render settings; use even resolution')\n    camera = s['camera']\n    for key in ('location', 'target'):\n        if len(camera[key]) != 3 or not all(math.isfinite(v) for v in camera[key]):\n            raise ValueError('Invalid camera vector')\n    if camera['location'] == camera['target'] or not math.isfinite(camera['ortho_scale']) or camera['ortho_scale'] <= 0:\n        raise ValueError('Invalid camera')\n\n\ndef load_scenario(args):\n    s = merge(defaults(), json.loads(args.scenario_json.read_text(encoding='utf-8'))) if args.scenario_json else defaults()\n    if args.scenario_overrides_json:\n        s = merge(s, json.loads(args.scenario_overrides_json.read_text(encoding='utf-8')))\n    for key in BASELINE_PHYSICS:\n        if getattr(args, key, None) is not None:\n            s['physics'][key] = getattr(args, key)\n    for key in ('fps', 'duration_sec', 'slow_motion', 'resolution', 'samples'):\n        if getattr(args, key, None) is not None:\n            s['render'][key] = getattr(args, key)\n    validate(s)\n    return s\n", "pendulum_box_collision.scene_environment": "\"\"\"Procedural middle-school physics lab and the two visible rigid bodies.\n\nOnly geometry and appearance live here. Nothing in this module knows about\nphysics parameters, so a mass or speed edit changes the clip without touching\na single material, and the collision shapes in ``simulate_pendulum_box_collision.py``\nstay the authority on size and contact.\n\nThe set is built the way the other bench-top scenes build theirs: every prop is\nprocedural except for the local textured blackboard and pen assets; the bench top is exactly ``TABLE_Z`` so the\nblock visibly rests on the surface the solver uses, and the retort stand's rod\nends at ``scene_geometry.PIVOT`` so the drawn thread leaves from the point the\nconstraint hangs from.\n\nLayout, seen from the default camera at -Y\n------------------------------------------\n* the block starts left of centre and slides right;\n* the bob hangs at x = 0, just above the bench, and swings in the X-Z plane;\n* the retort stand stands to the right, its cross-arm reaching left to the\n  pivot, so neither the rod nor its base is ever in the block's path;\n* the slate board, splashback and shelf stay behind y = 1.2, out of reach.\n\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\n\nimport sys\nfrom pathlib import Path\nsys.path.insert(0, str(_PCVE_ROOT / 'clean_scripts'))\nfrom pcve_blender_compat import (shader_socket, set_shader_input, eevee_engine, set_eevee_property, set_color_property)\nimport math, random\nfrom pathlib import Path\nfrom scene_support.pendulum_box_collision.scene_geometry import (\n    BENCH_SIZE, BOB_RADIUS, BOX_SIZE, PENDULUM_LENGTH, PIVOT, TABLE_Z)\n\nENVIRONMENT_THEME = 'school_physics_lab_pendulum_bench'\nAPPEARANCE_VERSION = 4\n\n# The visible bench top must be the same surface the solver drops the block on.\nBENCH_TOP = TABLE_Z\nSTAND = (0.40, 0.12)          # foot of the retort stand, on the bench\nSTAND_TOP = PIVOT[2] + .055\n\n\n# --------------------------------------------------------------- materials\n\n\ndef _material(bpy, name, color, rough=.62, metallic=0., coat=0., bump=0., bump_scale=14.,\n              grain=None, speckle=None, speckle_color=None, bump_distance=.00025):\n    \"\"\"Principled surface with optional procedural relief, wood grain or aggregate.\"\"\"\n    material = bpy.data.materials.new(name)\n    material.diffuse_color = (*color, 1.); material.use_nodes = True\n    nodes = material.node_tree.nodes; links = material.node_tree.links\n    bsdf = nodes['Principled BSDF']\n    bsdf.inputs['Base Color'].default_value = (*color, 1.)\n    bsdf.inputs['Roughness'].default_value = rough\n    if metallic:\n        bsdf.inputs['Metallic'].default_value = metallic\n    if coat:\n        set_shader_input(bsdf, 'Coat Weight', coat)\n        set_shader_input(bsdf, 'Coat Roughness', 0.24)\n    if not (bump > 0. or speckle):\n        return material\n    vector = nodes.new('ShaderNodeTexCoord').outputs['Object']\n    if grain:\n        mapping = nodes.new('ShaderNodeMapping'); mapping.inputs['Scale'].default_value = grain\n        links.new(mapping.inputs['Vector'], vector); vector = mapping.outputs['Vector']\n    if bump > 0.:\n        noise = nodes.new('ShaderNodeTexNoise')\n        noise.inputs['Scale'].default_value = bump_scale\n        noise.inputs['Detail'].default_value = 3.\n        noise.inputs['Roughness'].default_value = .52\n        links.new(noise.inputs['Vector'], vector)\n        relief = nodes.new('ShaderNodeBump')\n        relief.inputs['Strength'].default_value = bump\n        relief.inputs['Distance'].default_value = bump_distance\n        links.new(relief.inputs['Height'], noise.outputs['Fac'])\n        links.new(bsdf.inputs['Normal'], relief.outputs['Normal'])\n    if speckle:\n        aggregate = nodes.new('ShaderNodeTexVoronoi'); aggregate.inputs['Scale'].default_value = speckle\n        links.new(aggregate.inputs['Vector'], vector)\n        ramp = nodes.new('ShaderNodeValToRGB')\n        ramp.color_ramp.elements[0].position = .36; ramp.color_ramp.elements[0].color = (*color, 1.)\n        ramp.color_ramp.elements[1].position = .68\n        ramp.color_ramp.elements[1].color = (*(speckle_color or tuple(c * .55 for c in color)), 1.)\n        links.new(ramp.inputs['Fac'], aggregate.outputs['Distance'])\n        links.new(bsdf.inputs['Base Color'], ramp.outputs['Color'])\n    return material\n\n\ndef _wood(bpy, name, light, dark, scale=(1.6, 9., 22.), rough=.44, coat=.12):\n    \"\"\"Two-tone grain: a stretched noise drives a colour ramp, plus fine relief.\n\n    A single flat brown cube reads as plastic at this distance. Wood needs the\n    value to wander along the length of the board, which is what the very\n    anisotropic mapping scale does: fine across the grain, long along it.\n    \"\"\"\n    material = bpy.data.materials.new(name); material.use_nodes = True\n    nodes = material.node_tree.nodes; links = material.node_tree.links\n    bsdf = nodes['Principled BSDF']\n    bsdf.inputs['Roughness'].default_value = rough\n    set_shader_input(bsdf, 'Coat Weight', coat)\n    set_shader_input(bsdf, 'Coat Roughness', 0.22)\n    coord = nodes.new('ShaderNodeTexCoord')\n    mapping = nodes.new('ShaderNodeMapping'); mapping.inputs['Scale'].default_value = scale\n    links.new(mapping.inputs['Vector'], coord.outputs['Object'])\n    grain = nodes.new('ShaderNodeTexNoise')\n    grain.inputs['Scale'].default_value = 5.2\n    grain.inputs['Detail'].default_value = 5.\n    grain.inputs['Roughness'].default_value = .55\n    links.new(grain.inputs['Vector'], mapping.outputs['Vector'])\n    ramp = nodes.new('ShaderNodeValToRGB')\n    ramp.color_ramp.elements[0].position = .30; ramp.color_ramp.elements[0].color = (*dark, 1.)\n    ramp.color_ramp.elements[1].position = .70; ramp.color_ramp.elements[1].color = (*light, 1.)\n    links.new(ramp.inputs['Fac'], grain.outputs['Fac'])\n    links.new(bsdf.inputs['Base Color'], ramp.outputs['Color'])\n    pores = nodes.new('ShaderNodeTexNoise')\n    pores.inputs['Scale'].default_value = 240.\n    pores.inputs['Detail'].default_value = 3.\n    links.new(pores.inputs['Vector'], mapping.outputs['Vector'])\n    relief = nodes.new('ShaderNodeBump')\n    relief.inputs['Strength'].default_value = .12\n    relief.inputs['Distance'].default_value = .00018\n    links.new(relief.inputs['Height'], pores.outputs['Fac'])\n    links.new(bsdf.inputs['Normal'], relief.outputs['Normal'])\n    return material\n\n\ndef _bench_top(bpy, name, color, rough=.46):\n    \"\"\"Dark lino bench top: tonal drift, long scuffs and a wide soft sheen.\"\"\"\n    material = bpy.data.materials.new(name); material.use_nodes = True\n    nodes = material.node_tree.nodes; links = material.node_tree.links\n    bsdf = nodes['Principled BSDF']\n    bsdf.inputs['Roughness'].default_value = rough\n    set_shader_input(bsdf, 'Coat Weight', 0.12)\n    set_shader_input(bsdf, 'Coat Roughness', 0.34)\n    coord = nodes.new('ShaderNodeTexCoord')\n    drift = nodes.new('ShaderNodeTexNoise')\n    drift.inputs['Scale'].default_value = 1.5\n    drift.inputs['Detail'].default_value = 4.\n    drift.inputs['Roughness'].default_value = .62\n    links.new(drift.inputs['Vector'], coord.outputs['Object'])\n    tone = nodes.new('ShaderNodeValToRGB')\n    tone.color_ramp.elements[0].position = .26\n    tone.color_ramp.elements[0].color = (*(c * .78 for c in color), 1.)\n    tone.color_ramp.elements[1].position = .78\n    tone.color_ramp.elements[1].color = (*(min(1., c * 1.26) for c in color), 1.)\n    links.new(tone.inputs['Fac'], drift.outputs['Fac'])\n    links.new(bsdf.inputs['Base Color'], tone.outputs['Color'])\n    scuff_coord = nodes.new('ShaderNodeMapping')\n    scuff_coord.inputs['Scale'].default_value = (2.6, 8., 3.)\n    links.new(scuff_coord.inputs['Vector'], coord.outputs['Object'])\n    scuff = nodes.new('ShaderNodeTexNoise')\n    scuff.inputs['Scale'].default_value = 4.0\n    scuff.inputs['Detail'].default_value = 2.\n    links.new(scuff.inputs['Vector'], scuff_coord.outputs['Vector'])\n    mask = nodes.new('ShaderNodeValToRGB')\n    mask.color_ramp.elements[0].position = .64; mask.color_ramp.elements[0].color = (0., 0., 0., 1.)\n    mask.color_ramp.elements[1].position = .77; mask.color_ramp.elements[1].color = (1., 1., 1., 1.)\n    links.new(mask.inputs['Fac'], scuff.outputs['Fac'])\n    wear = nodes.new('ShaderNodeMixRGB'); wear.inputs['Fac'].default_value = 1.\n    links.new(wear.inputs['Fac'], mask.outputs['Color'])\n    links.new(wear.inputs['Color1'], tone.outputs['Color'])\n    wear.inputs['Color2'].default_value = (*(c * .70 for c in color), 1.)\n    links.new(bsdf.inputs['Base Color'], wear.outputs['Color'])\n    gloss = nodes.new('ShaderNodeMixRGB'); gloss.blend_type = 'MIX'\n    links.new(gloss.inputs['Fac'], mask.outputs['Color'])\n    gloss.inputs['Color1'].default_value = (rough, rough, rough, 1.)\n    gloss.inputs['Color2'].default_value = (.64, .64, .64, 1.)\n    links.new(bsdf.inputs['Roughness'], gloss.outputs['Color'])\n    relief = nodes.new('ShaderNodeBump')\n    relief.inputs['Strength'].default_value = .05\n    relief.inputs['Distance'].default_value = .00012\n    links.new(relief.inputs['Height'], mask.outputs['Color'])\n    links.new(bsdf.inputs['Normal'], relief.outputs['Normal'])\n    return material\n\n\ndef _place_blackboard_asset(bpy):\n    \"\"\"Use the board's original mesh, UVs and PBR maps; omit its pinned note.\"\"\"\n    from mathutils import Matrix, Vector\n    asset = _PCVE_ROOT / 'assets' / 'models' / 'realistic_blackboard.glb'\n    before = set(bpy.data.objects)\n    bpy.ops.import_scene.gltf(filepath=str(asset))\n    imported = set(bpy.data.objects) - before\n    bpy.context.view_layer.update()\n    meshes = [obj for obj in imported if obj.type == 'MESH']\n    if not meshes:\n        raise ValueError(f'Blackboard asset contains no mesh: {asset}')\n    def bounds(obj):\n        points = [obj.matrix_world @ Vector(corner) for corner in obj.bound_box]\n        return (Vector(tuple(min(v[i] for v in points) for i in range(3))),\n                Vector(tuple(max(v[i] for v in points) for i in range(3))))\n    source = max(meshes, key=lambda obj: (bounds(obj)[1] - bounds(obj)[0]).length)\n    low, high = bounds(source)\n    centre = (low + high) / 2\n    scale = .74 / (high.z - low.z)\n    mesh = source.data.copy()\n    mesh.transform(source.matrix_world)\n    board = bpy.data.objects.new('Real blackboard (realistic_blackboard.glb)', mesh)\n    bpy.context.scene.collection.objects.link(board)\n    board.matrix_world = (Matrix.Translation((-.20, 1.24, 1.085))\n                          @ Matrix.Scale(scale, 4) @ Matrix.Translation(-centre))\n    board['asset_path'] = 'assets/models/realistic_blackboard.glb'\n    for obj in imported:\n        bpy.data.objects.remove(obj, do_unlink=True)\n    return board\n\n\ndef _place_pen_asset(bpy):\n    \"\"\"Keep the GLB's UVs/materials and seat its actual bounds on the bench.\"\"\"\n    from mathutils import Matrix, Vector\n    asset = _PCVE_ROOT / 'assets' / 'models' / 'the_pen.glb'\n    before = set(bpy.data.objects)\n    bpy.ops.import_scene.gltf(filepath=str(asset))\n    imported = set(bpy.data.objects) - before\n    bpy.context.view_layer.update()\n    points = [obj.matrix_world @ Vector(corner) for obj in imported\n              if obj.type == 'MESH' for corner in obj.bound_box]\n    if not points:\n        raise ValueError(f'Pen asset contains no mesh: {asset}')\n    low = Vector(tuple(min(v[i] for v in points) for i in range(3)))\n    high = Vector(tuple(max(v[i] for v in points) for i in range(3)))\n    scale = .145 / (high.x - low.x)\n    centre = (low + high) / 2\n    root = bpy.data.objects.new('Desk pen (the_pen.glb)', None)\n    bpy.context.scene.collection.objects.link(root)\n    for obj in imported:\n        if obj.parent not in imported:\n            obj.parent = root\n    root.matrix_world = (Matrix.Translation((-.30, -.235, BENCH_TOP + .00015))\n                         @ Matrix.Rotation(.32, 4, 'Z') @ Matrix.Scale(scale, 4)\n                         @ Matrix.Translation((-centre.x, -centre.y, -low.z)))\n    root['asset_path'] = 'assets/models/the_pen.glb'\n    root['length_m'] = .145\n    return root\n\n\ndef _alpha_material(bpy, name, color, rough):\n    \"\"\"Translucent surface helper; Cycles needs no blend mode, EEVEE does.\"\"\"\n    material = bpy.data.materials.new(name); material.use_nodes = True\n    bsdf = material.node_tree.nodes['Principled BSDF']\n    bsdf.inputs['Base Color'].default_value = (*color, 1.)\n    bsdf.inputs['Roughness'].default_value = rough\n    for attribute, value in (('surface_render_method', 'DITHERED'), ('blend_method', 'BLEND')):\n        try:\n            setattr(material, attribute, value)\n        except Exception:\n            pass\n    return material\n\n\ndef _alpha_surface(material, bsdf, alpha_socket):\n    \"\"\"Mix with a Transparent BSDF instead of using Principled's Alpha.\n\n    Feeding Alpha leaves the surface blocking shadow rays, which turns a film of\n    pigment into a black rectangle on whatever is behind it.\n    \"\"\"\n    nodes = material.node_tree.nodes; links = material.node_tree.links\n    output = [node for node in nodes if node.type == 'OUTPUT_MATERIAL'][0]\n    for link in list(output.inputs['Surface'].links):\n        links.remove(link)\n    clear = nodes.new('ShaderNodeBsdfTransparent')\n    mix = nodes.new('ShaderNodeMixShader')\n    links.new(mix.inputs[0], alpha_socket)\n    links.new(mix.inputs[1], clear.outputs[0])\n    links.new(mix.inputs[2], bsdf.outputs[0])\n    links.new(output.inputs['Surface'], mix.outputs[0])\n    return mix\n\n\ndef _chalk_material(bpy, name, color, dust=.42, value_spread=.22, bump=.30):\n    \"\"\"Pigment that skips and fades like pressed chalk instead of flat paint.\"\"\"\n    material = _alpha_material(bpy, name, color, .94)\n    nodes = material.node_tree.nodes; links = material.node_tree.links\n    bsdf = nodes['Principled BSDF']\n    set_shader_input(bsdf, 'Specular IOR Level', 0.02)\n    coord = nodes.new('ShaderNodeTexCoord')\n    coverage = nodes.new('ShaderNodeTexNoise')\n    coverage.inputs['Scale'].default_value = 64.\n    coverage.inputs['Detail'].default_value = 3.\n    coverage.inputs['Roughness'].default_value = .58\n    links.new(coverage.inputs['Vector'], coord.outputs['Object'])\n    ramp = nodes.new('ShaderNodeValToRGB')\n    ramp.color_ramp.elements[0].position = .36; ramp.color_ramp.elements[0].color = (0., 0., 0., 1.)\n    ramp.color_ramp.elements[1].position = .64; ramp.color_ramp.elements[1].color = (1., 1., 1., 1.)\n    links.new(ramp.inputs['Fac'], coverage.outputs['Fac'])\n    coarse = nodes.new('ShaderNodeMath'); coarse.operation = 'MULTIPLY_ADD'\n    coarse.inputs[1].default_value = 1. - dust; coarse.inputs[2].default_value = dust\n    links.new(coarse.inputs[0], ramp.outputs['Color'])\n    grain = nodes.new('ShaderNodeTexNoise')\n    grain.inputs['Scale'].default_value = 520.\n    grain.inputs['Detail'].default_value = 4.\n    grain.inputs['Roughness'].default_value = .5\n    links.new(grain.inputs['Vector'], coord.outputs['Object'])\n    speckle = nodes.new('ShaderNodeValToRGB')\n    speckle.color_ramp.elements[0].position = .28; speckle.color_ramp.elements[0].color = (0., 0., 0., 1.)\n    speckle.color_ramp.elements[1].position = .58; speckle.color_ramp.elements[1].color = (1., 1., 1., 1.)\n    links.new(speckle.inputs['Fac'], grain.outputs['Fac'])\n    lift = nodes.new('ShaderNodeMath'); lift.operation = 'MULTIPLY_ADD'\n    lift.inputs[1].default_value = .55; lift.inputs[2].default_value = .45\n    links.new(lift.inputs[0], speckle.outputs['Color'])\n    alpha = nodes.new('ShaderNodeMath'); alpha.operation = 'MULTIPLY'\n    links.new(alpha.inputs[0], coarse.outputs['Value']); links.new(alpha.inputs[1], lift.outputs['Value'])\n    _alpha_surface(material, bsdf, alpha.outputs['Value'])\n    tone = nodes.new('ShaderNodeMixRGB'); tone.blend_type = 'MIX'\n    tone.inputs['Color1'].default_value = (*color, 1.)\n    tone.inputs['Color2'].default_value = (*(c * (1. - value_spread) for c in color), 1.)\n    links.new(tone.inputs['Fac'], coverage.outputs['Fac'])\n    links.new(bsdf.inputs['Base Color'], tone.outputs['Color'])\n    if bump > 0.:\n        relief = nodes.new('ShaderNodeBump')\n        relief.inputs['Strength'].default_value = bump\n        relief.inputs['Distance'].default_value = .00008\n        links.new(relief.inputs['Height'], grain.outputs['Fac'])\n        links.new(bsdf.inputs['Normal'], relief.outputs['Normal'])\n    return material\n\n\ndef _chalk_halo_material(bpy, name, color, strength=.13):\n    \"\"\"Loose powder hugging a mark: wide, ragged and almost transparent.\"\"\"\n    material = _alpha_material(bpy, name, color, .96)\n    nodes = material.node_tree.nodes; links = material.node_tree.links\n    bsdf = nodes['Principled BSDF']\n    set_shader_input(bsdf, 'Specular IOR Level', 0.02)\n    coord = nodes.new('ShaderNodeTexCoord')\n    noise = nodes.new('ShaderNodeTexNoise')\n    noise.inputs['Scale'].default_value = 110.\n    noise.inputs['Detail'].default_value = 4.\n    noise.inputs['Roughness'].default_value = .62\n    links.new(noise.inputs['Vector'], coord.outputs['Object'])\n    ramp = nodes.new('ShaderNodeValToRGB')\n    ramp.color_ramp.elements[0].position = .30; ramp.color_ramp.elements[0].color = (0., 0., 0., 1.)\n    ramp.color_ramp.elements[1].position = .62; ramp.color_ramp.elements[1].color = (1., 1., 1., 1.)\n    links.new(ramp.inputs['Fac'], noise.outputs['Fac'])\n    level = nodes.new('ShaderNodeMath'); level.operation = 'MULTIPLY'\n    level.inputs[1].default_value = strength\n    links.new(level.inputs[0], ramp.outputs['Color'])\n    _alpha_surface(material, bsdf, level.outputs['Value'])\n    return material\n\n\ndef _residue_material(bpy, name, color):\n    \"\"\"Ghost of erased writing: horizontal wipes plus uneven haze.\"\"\"\n    material = _alpha_material(bpy, name, color, .96)\n    nodes = material.node_tree.nodes; links = material.node_tree.links\n    bsdf = nodes['Principled BSDF']\n    coord = nodes.new('ShaderNodeTexCoord')\n    wipe_coord = nodes.new('ShaderNodeMapping')\n    wipe_coord.inputs['Scale'].default_value = (2.2, 1., 17.)\n    links.new(wipe_coord.inputs['Vector'], coord.outputs['Object'])\n    wipe = nodes.new('ShaderNodeTexNoise')\n    wipe.inputs['Scale'].default_value = 4.5\n    wipe.inputs['Detail'].default_value = 3.\n    wipe.inputs['Roughness'].default_value = .6\n    links.new(wipe.inputs['Vector'], wipe_coord.outputs['Vector'])\n    streak = nodes.new('ShaderNodeValToRGB')\n    streak.color_ramp.elements[0].position = .44; streak.color_ramp.elements[0].color = (0., 0., 0., 1.)\n    streak.color_ramp.elements[1].position = .78; streak.color_ramp.elements[1].color = (1., 1., 1., 1.)\n    links.new(streak.inputs['Fac'], wipe.outputs['Fac'])\n    haze = nodes.new('ShaderNodeTexNoise')\n    haze.inputs['Scale'].default_value = 1.6\n    haze.inputs['Detail'].default_value = 4.\n    links.new(haze.inputs['Vector'], coord.outputs['Object'])\n    veil = nodes.new('ShaderNodeValToRGB')\n    veil.color_ramp.elements[0].position = .40; veil.color_ramp.elements[0].color = (.1, .1, .1, 1.)\n    veil.color_ramp.elements[1].position = .72; veil.color_ramp.elements[1].color = (.55, .55, .55, 1.)\n    links.new(veil.inputs['Fac'], haze.outputs['Fac'])\n    mix = nodes.new('ShaderNodeMath'); mix.operation = 'MULTIPLY'\n    links.new(mix.inputs[0], streak.outputs['Color']); links.new(mix.inputs[1], veil.outputs['Color'])\n    strength = nodes.new('ShaderNodeMath'); strength.operation = 'MULTIPLY'\n    strength.inputs[1].default_value = .085\n    links.new(strength.inputs[0], mix.outputs['Value'])\n    _alpha_surface(material, bsdf, strength.outputs['Value'])\n    return material\n\n\n# ------------------------------------------------------------------- meshes\n\n\ndef _cube_mesh(bpy, name, size):\n    \"\"\"A real-world-sized cube mesh, so Object texture coordinates stay isotropic.\"\"\"\n    x, y, z = (value * .5 for value in size)\n    mesh = bpy.data.meshes.new(name)\n    mesh.from_pydata([(-x, -y, -z), (x, -y, -z), (x, y, -z), (-x, y, -z),\n                      (-x, -y, z), (x, -y, z), (x, y, z), (-x, y, z)], [],\n                     [(0, 3, 2, 1), (4, 5, 6, 7), (0, 1, 5, 4),\n                      (1, 2, 6, 5), (2, 3, 7, 6), (3, 0, 4, 7)])\n    mesh.update()\n    return mesh\n\n\ndef _tube_mesh(bpy, name, radius, length, segments=48):\n    import bmesh\n    mesh = bpy.data.meshes.new(name); bm = bmesh.new()\n    bmesh.ops.create_cone(bm, cap_ends=True, cap_tris=False, segments=segments,\n                          radius1=radius, radius2=radius, depth=length)\n    bm.to_mesh(mesh); bm.free(); mesh.update()\n    return mesh\n\n\ndef _cone_mesh(bpy, name, radius1, radius2, length, segments=48):\n    import bmesh\n    mesh = bpy.data.meshes.new(name); bm = bmesh.new()\n    bmesh.ops.create_cone(bm, cap_ends=True, cap_tris=False, segments=segments,\n                          radius1=radius1, radius2=radius2, depth=length)\n    bm.to_mesh(mesh); bm.free(); mesh.update()\n    return mesh\n\n\ndef _sphere_mesh(bpy, name, radius, segments=64, rings=40):\n    import bmesh\n    mesh = bpy.data.meshes.new(name); bm = bmesh.new()\n    bmesh.ops.create_uvsphere(bm, u_segments=segments, v_segments=rings, radius=radius)\n    bm.to_mesh(mesh); bm.free(); mesh.update()\n    for polygon in mesh.polygons:\n        polygon.use_smooth = True\n    return mesh\n\n\n# ---------------------------------------------------------- hand-written chalk\n# Each glyph is a set of monoline strokes on a 0..1 cap-height grid. Stroke\n# geometry and pigment are what make the board read as chalk rather than as a\n# font: see ``_chalk_stroke``.\ndef _arc(cx, cy, rx, ry, a0, a1, steps=14):\n    return [(cx + rx * math.cos(math.radians(a0 + (a1 - a0) * i / steps)),\n             cy + ry * math.sin(math.radians(a0 + (a1 - a0) * i / steps)))\n            for i in range(steps + 1)]\n\n\ndef _bez(p0, p1, p2, steps=10):\n    return [((1 - t) ** 2 * p0[0] + 2 * (1 - t) * t * p1[0] + t * t * p2[0],\n             (1 - t) ** 2 * p0[1] + 2 * (1 - t) * t * p1[1] + t * t * p2[1])\n            for t in (i / steps for i in range(steps + 1))]\n\n\n_GLYPHS = {\n    'A': (.62, [[(0, 0), (.31, 1), (.62, 0)], [(.13, .34), (.49, .34)]]),\n    'B': (.54, [[(0, 0), (0, 1)],\n                [(0, 1), (.22, 1)] + _arc(.24, .78, .24, .22, 90, -90) + [(0, .56)],\n                [(0, .56), (.26, .56)] + _arc(.28, .28, .26, .28, 90, -90) + [(0, 0)]]),\n    'C': (.56, [_arc(.30, .50, .28, .50, 56, 304, 20)]),\n    'D': (.56, [[(0, 0), (0, 1)], [(0, 1), (.20, 1)] + _arc(.22, .50, .32, .50, 90, -90, 20) + [(0, 0)]]),\n    'E': (.50, [[(0, 0), (0, 1)], [(0, 1), (.47, 1)], [(0, .55), (.38, .55)], [(0, 0), (.47, 0)]]),\n    'F': (.48, [[(0, 0), (0, 1)], [(0, 1), (.45, 1)], [(0, .56), (.36, .56)]]),\n    'H': (.54, [[(0, 0), (0, 1)], [(.52, 0), (.52, 1)], [(0, .52), (.52, .52)]]),\n    'I': (.11, [[(.05, 0), (.05, 1)]]),\n    'K': (.52, [[(0, 0), (0, 1)], [(.44, .58), (0, .26)], [(.14, .36), (.46, 0)]]),\n    'L': (.48, [[(0, 1), (0, 0), (.45, 0)]]),\n    'M': (.68, [[(0, 0), (0, 1), (.34, .40), (.68, 1), (.68, 0)]]),\n    'N': (.54, [[(0, 0), (0, 1), (.52, 0), (.52, 1)]]),\n    'O': (.58, [_arc(.29, .50, .28, .50, 0, 360, 28)]),\n    'P': (.48, [[(0, 0), (0, 1)], [(0, 1), (.22, 1)] + _arc(.23, .76, .22, .24, 90, -90) + [(0, .52)]]),\n    'S': (.50, [[(.48, .86), (.40, 1), (.16, 1), (.04, .88), (.03, .74), (.12, .60),\n                 (.36, .53), (.46, .40), (.46, .16), (.34, 0), (.10, 0), (0, .14)]]),\n    'T': (.52, [[(0, 1), (.52, 1)], [(.26, 1), (.26, 0)]]),\n    'U': (.52, [[(0, 1), (0, .16)] + _arc(.26, .16, .26, .16, 180, 360, 16) + [(.52, 1)]]),\n    'V': (.52, [[(0, 1), (.26, 0), (.52, 1)]]),\n    'Y': (.56, [[(0, 1), (.27, .44), (.54, 1)], [(.27, .44), (.27, 0)]]),\n    '0': (.50, [_arc(.25, .50, .23, .50, 0, 360, 26)]),\n    '1': (.34, [[(.06, .78), (.22, 1), (.22, 0)]]),\n    '2': (.50, [[(0, .80), (.06, .94), (.20, 1), (.34, .96), (.44, .82), (.38, .64),\n                 (.04, .08), (0, .02), (.46, .02)]]),\n    '4': (.56, [[(.40, 0), (.40, 1), (.02, .28), (.56, .28)]]),\n    '5': (.48, [[(.44, 1), (.09, 1), (.07, .62), (.24, .66), (.40, .52), (.42, .30),\n                 (.30, .10), (.12, .06), (0, .14)]]),\n    '8': (.50, [_arc(.25, .76, .21, .24, 0, 360, 18), _arc(.25, .26, .23, .26, 0, 360, 20)]),\n    '=': (.44, [[(0, .38), (.42, .38)], [(0, .66), (.42, .66)]]),\n    '/': (.46, [[(.04, 0), (.40, 1)]]),\n    '+': (.44, [[(0, .50), (.42, .50)], [(.21, .29), (.21, .71)]]),\n    '.': (.10, [_arc(.05, .06, .045, .05, 0, 360, 10)]),\n    '\u00b7': (.30, [[(.02, .44), (.16, .44)]]),\n    'a': (.50, [_arc(.25, .34, .24, .34, 24, 336, 18) + [(.49, .66)], [(.49, .68), (.49, 0)]]),\n    'g': (.50, [_arc(.25, .34, .24, .34, 24, 336, 18) + [(.49, .66)],\n                [(.49, .66), (.49, -.20)] + _arc(.36, -.20, .13, .12, 0, -180, 8)]),\n    'k': (.50, [[(0, 0), (0, 1)], [(.40, .56), (0, .28)], [(.13, .38), (.44, 0)]]),\n    'm': (.58, [[(0, 0), (0, .54)],\n                [(0, .54)] + _bez((0, .54), (.15, .71), (.29, .54)) + [(.29, 0)],\n                [(.29, .54)] + _bez((.29, .54), (.44, .71), (.58, .54)) + [(.58, 0)]]),\n    's': (.44, [[(.42, .62), (.34, .72), (.14, .72), (.04, .64), (.06, .52), (.18, .44),\n                 (.36, .36), (.40, .24), (.30, .14), (.08, .14), (0, .22)]]),\n    'v': (.48, [[(0, .68), (.23, 0), (.46, .68)]]),\n}\n\n\ndef _chalk_stroke(bpy, scene, points, width, material, bow=.0, seed=0., depth=1.2145):\n    \"\"\"One chalk mark, built as a flat ribbon lying on the slate.\n\n    A round bevelled curve reads as coloured wire on a blackboard: its top and\n    sides catch the key light differently. Real chalk is a matte deposit with a\n    constant surface normal, so the mark is a strip of quads and all the life\n    comes from width drift, bow and the granular pigment shader.\n    \"\"\"\n    count = len(points)\n    verts = []; faces = []\n    for index, (px, pz) in enumerate(points):\n        t = index / (count - 1) if count > 1 else 0.\n        wobble = bow * math.sin(t * math.pi * 1.35 + seed)\n        press = 1. + .16 * math.sin(t * math.pi * 2.4 + seed * 1.7)\n        press *= 1. - .30 * max(0., t - .88) / .12 - .30 * max(0., .12 - t) / .12\n        pz = pz + wobble\n        if count > 1:\n            previous = points[max(0, index - 1)]; following = points[min(count - 1, index + 1)]\n            tangent = (following[0] - previous[0], following[1] - previous[1])\n        else:\n            tangent = (1., 0.)\n        length = math.hypot(*tangent) or 1.\n        normal = (-tangent[1] / length, tangent[0] / length)\n        half = width * .5 * max(.35, press)\n        verts.append((px + normal[0] * half, 0., pz + normal[1] * half))\n        verts.append((px - normal[0] * half, 0., pz - normal[1] * half))\n    for index in range(count - 1):\n        base = index * 2\n        faces.append((base, base + 1, base + 3, base + 2))\n    mesh = bpy.data.meshes.new('Chalk mark')\n    mesh.from_pydata(verts, [], faces); mesh.update()\n    mesh.materials.append(material)\n    obj = bpy.data.objects.new('Chalk mark', mesh)\n    obj.location.y = depth\n    scene.collection.objects.link(obj)\n    return obj\n\n\ndef _chalk_text(bpy, scene, text, x, z, cap, materials, seed=1, slant=.07, drift=.012,\n                jitter=.020, tracking=.17, width=.092, halo=None, halo_scale=2.1):\n    \"\"\"Hand-lettered line: per-glyph drift, rotation, weight and shear.\"\"\"\n    rng = random.Random(seed)\n    pen = 0.\n    for character in text:\n        if character == ' ':\n            pen += cap * .30\n            continue\n        advance, strokes = _GLYPHS[character]\n        offset_x = rng.uniform(-jitter, jitter) * cap\n        offset_z = rng.uniform(-jitter, jitter) * cap * .7\n        rotate = math.radians(rng.uniform(-2.4, 2.4))\n        scale = rng.uniform(.94, 1.05)\n        weight = cap * width * rng.uniform(.90, 1.12)\n        material = materials[rng.randrange(len(materials))]\n        centre_x, centre_z = advance * .5, .40\n        cos_r, sin_r = math.cos(rotate), math.sin(rotate)\n        for stroke in strokes:\n            points = []\n            for u, v in stroke:\n                du = (u - centre_x) * scale; dv = (v - centre_z) * scale\n                ru = du * cos_r - dv * sin_r + centre_x\n                rv = du * sin_r + dv * cos_r + centre_z\n                ru += offset_x / cap + slant * rv\n                rv += offset_z / cap\n                point_x = x + pen + ru * cap\n                points.append((point_x, z + rv * cap + drift * (point_x - x)))\n            if halo is not None:\n                _chalk_stroke(bpy, scene, points, weight * halo_scale, halo,\n                              bow=cap * .014, seed=rng.random() * 6., depth=1.2171)\n            _chalk_stroke(bpy, scene, points, weight, material, bow=cap * .014, seed=rng.random() * 6.)\n        pen += (advance + tracking) * cap\n    return x + pen\n\n\ndef _chalk_rule(bpy, scene, x0, x1, z, material, cap, seed=2):\n    points = []\n    for index in range(13):\n        t = index / 12\n        points.append((x0 + (x1 - x0) * t, z + cap * .05 * math.sin(t * math.pi)))\n    return _chalk_stroke(bpy, scene, points, cap * .034, material, bow=cap * .01, seed=seed)\n\n\n# -------------------------------------------------------------------- set\n\n\ndef build_room(bpy, data):\n    \"\"\"Build the lab, the block and the bob.\n\n    Returns ``(objects, rig)``: ``objects`` maps the simulation's body ids to the\n    empties the renderer keyframes, ``rig`` carries the thread that has to be\n    aimed at the bob every frame and the pivot it hangs from.\n    \"\"\"\n    from mathutils import Vector\n    scene = bpy.context.scene\n\n    def mat(name, color, **kw):\n        return _material(bpy, name, color, **kw)\n\n    bench = _bench_top(bpy, 'Dark lino bench top', (.043, .050, .047), rough=.44)\n    frame_wood = _wood(bpy, 'Beech bench frame', (.46, .30, .145), (.22, .125, .052))\n    pine = _wood(bpy, 'Pine block', (.500, .340, .165), (.275, .175, .078),\n                 scale=(1.1, 6., 18.), rough=.54, coat=.10)\n    wall = mat('Pale mineral plaster', (.610, .585, .520), rough=.80,\n               bump=.045, bump_scale=210., bump_distance=.00035)\n    floor = mat('Grey terrazzo', (.255, .245, .222), rough=.55, bump=.05,\n                bump_scale=140., speckle=64., speckle_color=(.125, .120, .112))\n    steel = mat('Brushed steel', (.520, .530, .545), rough=.26, metallic=1.,\n                bump=.012, bump_scale=320., bump_distance=.00006)\n    chrome = mat('Polished chrome', (.640, .650, .665), rough=.13, metallic=1.)\n    cast_iron = mat('Cast iron stand foot', (.052, .055, .058), rough=.52, metallic=.55,\n                    bump=.10, bump_scale=180., bump_distance=.0003)\n    # Satin, not mirror: at 48 mm across, a mirror finish gives one blown white\n    # blob where the key light lands and no readable roundness anywhere else.\n    steel_ball = mat('Satin steel bob', (.470, .480, .505), rough=.30, metallic=1.,\n                     bump=.006, bump_scale=460., bump_distance=.00004)\n    brass = mat('Tarnished brass', (.400, .285, .115), rough=.40, metallic=1.,\n                bump=.03, bump_scale=260., bump_distance=.00012)\n    # A medium grey, not black: the thread spends most of the clip in front of\n    # the slate board (dark) and the last third in front of the bench (light),\n    # and a mid tone is the only value that separates from both at 1 px wide.\n    thread = mat('Pendulum thread', (.360, .345, .320), rough=.82)\n    paper = mat('Worksheet paper', (.545, .520, .450), rough=.78,\n                bump=.02, bump_scale=520., bump_distance=.00008)\n    enamel = mat('Enamel tray', (.245, .300, .275), rough=.42, coat=.20)\n    watch_case = mat('Black watch case', (.030, .031, .034), rough=.34, coat=.20)\n    black_ink = mat('Printed ink', (.035, .036, .040), rough=.62)\n    white_face = mat('Stopwatch dial', (.860, .855, .820), rough=.36, coat=.25)\n    def cube(name, loc, size, material, parent=None, bevel=.003, rotation=None):\n        obj = bpy.data.objects.new(name, _cube_mesh(bpy, name, size))\n        scene.collection.objects.link(obj); obj.location = loc; obj.data.materials.append(material)\n        if bevel:\n            modifier = obj.modifiers.new('Soft manufactured edges', 'BEVEL')\n            modifier.width = bevel; modifier.segments = 5\n            obj.modifiers.new('Weighted normals', 'WEIGHTED_NORMAL')\n        if rotation is not None:\n            obj.rotation_euler = rotation\n        if parent:\n            obj.parent = parent\n        return obj\n\n    def rod(name, start, end, radius, material, segments=32):\n        \"\"\"Cylinder spanning two points; used for the stand, arm and thread.\"\"\"\n        begin = Vector(start); finish = Vector(end); direction = finish - begin\n        obj = bpy.data.objects.new(name, _tube_mesh(bpy, name, radius, direction.length, segments))\n        scene.collection.objects.link(obj); obj.data.materials.append(material)\n        obj.location = (begin + finish) / 2\n        obj.rotation_mode = 'QUATERNION'\n        obj.rotation_quaternion = direction.to_track_quat('Z', 'Y')\n        for polygon in obj.data.polygons:\n            polygon.use_smooth = True\n        return obj\n\n    def text(name, string, loc, size, material, parent=None, rotation=(math.pi / 2, 0, 0)):\n        curve = bpy.data.curves.new(name, 'FONT'); curve.body = string; curve.size = size\n        curve.align_x = 'CENTER'; curve.extrude = .0001\n        obj = bpy.data.objects.new(name, curve); scene.collection.objects.link(obj)\n        obj.location = loc; obj.rotation_euler = rotation\n        curve.materials.append(material)\n        if parent:\n            obj.parent = parent\n        return obj\n\n    # --- room shell -----------------------------------------------------\n    cube('Lab floor', (0, 0, -.06), (8, 5, .12), floor)\n    cube('Plaster wall', (0, 1.35, 1.5), (8, .12, 3), wall)\n    # A low upstand where the bench meets the wall: every school lab bench has\n    # one, and it gives the slate board a shadow line to sit on.\n    cube('Bench upstand', (-.15, 1.272, .782), (2.44, .026, .044), frame_wood, bevel=.003)\n\n    # --- bench ----------------------------------------------------------\n    # The top slab's upper face is exactly TABLE_Z: it is the surface the\n    # collision slab uses, so the block never floats or sinks on screen.\n    cube('Bench top', (0, 0, BENCH_TOP - BENCH_SIZE[2] / 2), BENCH_SIZE, bench, bevel=.004)\n    cube('Bench apron', (0, 0, BENCH_TOP - BENCH_SIZE[2] - .035), (2.5, .92, .07), frame_wood, bevel=.004)\n    for x in (-1.12, 1.12):\n        for y in (-.36, .36):\n            cube('Square bench leg', (x, y, (BENCH_TOP - .11) / 2), (.055, .055, BENCH_TOP - .11), frame_wood)\n    for y in (-.36, .36):\n        cube('Bench stretcher', (0, y, .10), (2.20, .035, .055), frame_wood, bevel=.002)\n\n    # --- local blackboard asset (without the pinned note) ---------------\n    _place_blackboard_asset(bpy)\n\n    # --- retort stand ---------------------------------------------------\n    cube('Retort stand foot', (STAND[0], STAND[1], BENCH_TOP + .008), (.26, .16, .016),\n         cast_iron, bevel=.006)\n    for dx, dy in ((-.085, -.055), (.085, -.055), (-.085, .055), (.085, .055)):\n        rod('Foot pad', (STAND[0] + dx, STAND[1] + dy, BENCH_TOP),\n            (STAND[0] + dx, STAND[1] + dy, BENCH_TOP + .004), .012, _material(\n                bpy, 'Rubber foot', (.030, .030, .032), rough=.92))\n    rod('Retort rod', (STAND[0], STAND[1], BENCH_TOP + .012),\n        (STAND[0], STAND[1], STAND_TOP), .0085, chrome)\n    cube('Boss head', (STAND[0], STAND[1], PIVOT[2]), (.040, .032, .046), cast_iron, bevel=.005)\n    rod('Boss screw', (STAND[0] + .023, STAND[1], PIVOT[2]),\n        (STAND[0] + .043, STAND[1], PIVOT[2]), .0075, brass, segments=12)\n    # Cross-arm: from the boss head to the pivot, so the drawn thread starts\n    # exactly where the solver's point constraint is anchored.\n    rod('Cross arm', (STAND[0], STAND[1], PIVOT[2]), PIVOT, .0045, chrome)\n    cube('Arm clamp', (PIVOT[0], PIVOT[1], PIVOT[2]), (.026, .026, .024), cast_iron, bevel=.003)\n\n    # --- bench dressing (kept clear of the block's lane) ----------------\n    # The weights tray sits beside the retort stand, where a lab keeps it, not\n    # on the left half of the bench: that half is the slider's runway now, and\n    # anything standing there turns into a pale shape the block has to slide\n    # through.\n    tray_x, tray_y = .26, .285\n    cube('Weights tray', (tray_x, tray_y, BENCH_TOP + .012), (.24, .15, .024), enamel, bevel=.005)\n    for index, (dx, dy) in enumerate(((-.07, -.035), (0, -.035), (.07, -.035),\n                                      (-.035, .035), (.035, .035))):\n        rod(f'Hooked weight {index}', (tray_x + dx, tray_y + dy, BENCH_TOP + .024),\n            (tray_x + dx, tray_y + dy, BENCH_TOP + .078), .0165, brass)\n        rod(f'Weight hook {index}', (tray_x + dx, tray_y + dy, BENCH_TOP + .078),\n            (tray_x + dx, tray_y + dy, BENCH_TOP + .094), .0035, steel, segments=8)\n    _place_pen_asset(bpy)\n    rod('Metre rule', (.60, -.17, BENCH_TOP + .006), (.60, .17, BENCH_TOP + .006), .011, frame_wood)\n    for index in range(20):\n        cube('Ruler tick', (.60, -.15 + index * .016, BENCH_TOP + .0135),\n             (.028 if index % 5 == 0 else .015, .0012, .0006), black_ink, bevel=0)\n    # Stopwatch: body, dial, bezel and crown, lying face up on the bench.\n    rod('Stopwatch case', (.16, -.175, BENCH_TOP + .006), (.16, -.175, BENCH_TOP + .018), .034, watch_case)\n    rod('Stopwatch dial', (.16, -.175, BENCH_TOP + .0185), (.16, -.175, BENCH_TOP + .0195), .029, white_face)\n    rod('Stopwatch crown', (.16, -.175, BENCH_TOP + .024), (.16, -.175, BENCH_TOP + .035), .006, watch_case, 12)\n    for index in range(12):\n        angle = index * math.pi / 6\n        cube('Stopwatch tick', (.16 + .024 * math.sin(angle), -.175 + .024 * math.cos(angle),\n                                BENCH_TOP + .0202), (.0018, .0045, .0004), black_ink,\n             bevel=0, rotation=(0, 0, -angle))\n    # --- the two rigid bodies -------------------------------------------\n    objects = {}\n    box_root = bpy.data.objects.new('box', None); scene.collection.objects.link(box_root)\n    objects['box'] = box_root\n    width, depth, height = BOX_SIZE\n    cube('Pine block', (0, 0, 0), (width, depth, height), pine, box_root, bevel=.0025)\n    cube('Block end grain', (-width / 2 + .0002, 0, 0), (.0004, depth * .98, height * .96),\n         frame_wood, box_root, bevel=0)\n    # A specimen tag, not a shipping label: the slider is 12 cm long, so the\n    # sticker is 4 cm wide and sits low on the face where a lab would chalk it.\n    cube('Block label', (0, -depth / 2 - .0004, -.010), (width * .30, .0005, height * .20),\n         paper, box_root, bevel=.0003)\n    text('Label lettering', 'WOOD  B', (0, -depth / 2 - .0007, -.010), .0085, black_ink, box_root)\n\n    bob_root = bpy.data.objects.new('bob', None); scene.collection.objects.link(bob_root)\n    objects['bob'] = bob_root\n    ball = bpy.data.objects.new('Steel bob', _sphere_mesh(bpy, 'Steel bob', BOB_RADIUS))\n    scene.collection.objects.link(ball); ball.parent = bob_root; ball.data.materials.append(steel_ball)\n\n    # The thread and its eyelet live in the rod's frame, not the ball's: a real\n    # bob turns freely on a swivel, so the eyelet must not whirl with the spin\n    # the contact friction gives the ball.\n    thread_obj = rod('Pendulum thread', PIVOT, (0, 0, PIVOT[2] - PENDULUM_LENGTH), .0007,\n                     thread, segments=8)\n    eyelet = bpy.data.objects.new('Eyelet', _tube_mesh(bpy, 'Eyelet', .0055, .012, 10))\n    scene.collection.objects.link(eyelet); eyelet.data.materials.append(steel)\n    eyelet.parent = thread_obj; eyelet.location = (0, 0, PENDULUM_LENGTH / 2 - BOB_RADIUS - .001)\n    return objects, dict(thread=thread_obj, pivot=Vector(PIVOT), thread_length=PENDULUM_LENGTH)\n\n\ndef configure_lighting(bpy, scene):\n    \"\"\"Cool window key from the front left, warm fill, and a wash on the board.\"\"\"\n    from mathutils import Vector\n    world = bpy.data.worlds.new('Lab ambient'); world.use_nodes = True\n    background = world.node_tree.nodes['Background']\n    background.inputs['Color'].default_value = (.145, .155, .170, 1.)\n    background.inputs['Strength'].default_value = 1.0\n    scene.world = world\n    rig = [('Window key', (-1.35, -1.80, 2.95), 155., 2.4, (1., .962, .905), (-.10, 0., .92)),\n           ('Soft fill', (1.90, -1.20, 2.10), 34., 2.2, (.94, .965, 1.), (.10, 0., .92)),\n           ('Board wash', (-.30, .60, 2.10), 26., 2.2, (1., .99, .962), (-.20, 1.25, 1.20)),\n           ('Bench kick', (.55, -1.10, 1.05), 12., 1.2, (.98, .97, .95), (-.05, 0., .86))]\n    for name, location, power, size, color, target in rig:\n        bpy.ops.object.light_add(type='AREA', location=location)\n        lamp = bpy.context.object; lamp.name = f'{name} light'\n        lamp.data.energy = power; lamp.data.shape = 'DISK'; lamp.data.size = size\n        lamp.data.color = color\n        lamp.rotation_euler = (Vector(target) - lamp.location).to_track_quat('-Z', 'Y').to_euler()\n", "pendulum_box_collision.scene_geometry": "\"\"\"Metric dimensions shared by the collision shapes and the visible meshes.\n\nEvery number here is read by both ``simulate_pendulum_box_collision.py`` and\n``scene_environment.py``, so the block the solver moves and the block on screen\ncannot drift apart, and the thread in the picture is guaranteed to be the same\nlength as the rod constraint.\n\nThe block is a lab slider, not a crate: 12 x 7 x 8.5 cm of pine, the size of the\nblock that sits next to a dynamics track in a school lab. It is deliberately\nlong and shallow rather than cubic -- a tall block would have to be hit high on\nits face and would read as a box again.\n\nHeight is nonetheless load bearing. The bob rises as it swings and the block may\narrive at any point of the bob's first half period, so the top of the block has\nto stay above the bob's centre for the whole swing: with a 0.36 m thread and a\n26.5 degree maximum amplitude the bob's centre rises 37.8 mm above its lowest\npoint, which is why the block is 85 mm tall and not 60.\n\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\n\n# Bench top, matching the other bench-top scenes in this repo.\nTABLE_Z = .76\nBENCH_SIZE = (2.6, 1.0, .08)\n\n# 12 x 7 x 8.5 cm, 0.45 kg at about 630 kg/m^3 -- dry pine.\nBOX_SIZE = (.12, .07, .085)\n\n# The slider starts well outside the camera frame. Its whole approach is the\n# point: the block has to be far enough away that the pendulum finishes half a\n# period before anything touches it (about 0.605 s), and at 1.3 m/s with bench\n# friction that is 0.70 m of travel. The arithmetic is spelled out here so the\n# start position is not a magic constant.\nCONTACT_X = -(.020 + BOX_SIZE[0] / 2)      # block centre when its face meets the bob\nAPPROACH_DISTANCE = .701                   # 1.3 m/s for 0.605 s at 0.47 m/s^2 of friction\nBOX_START_X = CONTACT_X - APPROACH_DISTANCE\n\n# Bob: a 48 mm steel ball on a 360 mm thread -- a lab pendulum bob, not a\n# wrecking ball. Mass and size are deliberately independent: the mass is an\n# editable parameter, and a hollow demonstration ball is exactly the case where\n# the two come apart. 48 mm is about the largest ball that still reads as a\n# pendulum bob rather than a weight.\nBOB_RADIUS = .024\n# Gap between the bottom of the hung bob and the bench top.\nBOB_CLEARANCE = .010\nBOB_CENTER_Z = TABLE_Z + BOB_CLEARANCE + BOB_RADIUS\nPENDULUM_LENGTH = .36\nPIVOT = (0., 0., BOB_CENTER_Z + PENDULUM_LENGTH)\n\n\ndef box_center():\n    \"\"\"Resting centre of the block, the pose frame 1 must show.\"\"\"\n    return [BOX_START_X, 0., TABLE_Z + BOX_SIZE[2] / 2]\n\n\ndef moving_objects(physics):\n    \"\"\"Per-body metadata shared by the cache, the GT export and the renderer.\"\"\"\n    return {\n        'box': dict(size=list(BOX_SIZE), mass=physics['box_mass'],\n                    initial_location=box_center(), initial_yaw=0.),\n        'bob': dict(radius=BOB_RADIUS, mass=physics['bob_mass'],\n                    pivot=list(PIVOT), pendulum_length=PENDULUM_LENGTH,\n                    lowest_center=[0., 0., BOB_CENTER_Z]),\n    }\n", "pendulum_box_collision": "\"\"\"Shared support modules for pendulum_box_collision.\"\"\"\nfrom pcve_project_paths import project_root as _pcve_project_root, scene_root as _pcve_scene_root\n_PCVE_ROOT = _pcve_project_root(__file__)\n_PCVE_SCENE_ROOT = _pcve_scene_root(__file__)\n"}""")

_BUNDLE_SCENE_ALIAS = 'pendulum_box_collision'
_BUNDLE_ALIASES = ['cache_contract', 'render_quality', 'runtime_support', 'scene_config', 'scene_environment', 'scene_geometry', 'pendulum_box_collision', 'pendulum_box_collision.cache_contract', 'pendulum_box_collision.render_quality', 'pendulum_box_collision.runtime_support', 'pendulum_box_collision.scene_config', 'pendulum_box_collision.scene_environment', 'pendulum_box_collision.scene_geometry']

class _SceneBundleLoader(_bundle_abc.MetaPathFinder, _bundle_abc.Loader):
    def find_spec(self, fullname, path=None, target=None):
        if fullname not in _BUNDLE_SOURCES:
            return None
        package = (fullname == "scene_support" or fullname.count(".") == 1 and fullname.startswith("scene_support.") or fullname == _BUNDLE_SCENE_ALIAS)
        return _bundle_util.spec_from_loader(fullname, self, is_package=package)

    def create_module(self, spec):
        return None

    def exec_module(self, module):
        name = module.__spec__.name
        package = module.__spec__.submodule_search_locations is not None
        if name == "scene_support":
            origin = _BUNDLE_SCENE / "scene_support" / "__init__.py"
        elif name == _BUNDLE_SCENE_ALIAS:
            origin = _BUNDLE_SCENE / "scene_support" / name / "__init__.py"
        elif name.startswith(_BUNDLE_SCENE_ALIAS + "."):
            origin = _BUNDLE_SCENE / "scene_support" / name.replace(".", "/")
            origin = origin.with_suffix(".py")
        elif name.startswith("scene_support."):
            tail = name.split(".", 1)[1]
            if package:
                origin = _BUNDLE_SCENE / "scene_support" / tail / "__init__.py"
            else:
                origin = _BUNDLE_SCENE / "scene_support" / tail.replace(".", "/")
                origin = origin.with_suffix(".py")
        else:
            origin = _BUNDLE_SCRIPTS / (name + ".py")
        module.__file__ = str(origin)
        module.__package__ = name if package else (_BUNDLE_SCENE_ALIAS if name.startswith(_BUNDLE_SCENE_ALIAS + ".") or name in ['cache_contract', 'render_quality', 'runtime_support', 'scene_config', 'scene_environment', 'scene_geometry'] else name.rpartition("." )[0])
        if package:
            module.__path__ = [str(_BUNDLE_SCENE)] if name == _BUNDLE_SCENE_ALIAS else []
        source = _BUNDLE_SOURCES[name]
        exec(compile(source, str(origin), "exec"), module.__dict__)

def install_scene_support():
    if not any(isinstance(item, _SceneBundleLoader) for item in _bundle_sys.meta_path):
        _bundle_sys.meta_path.insert(0, _SceneBundleLoader())

install_scene_support()




